/* 平成18年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h18.committeeSessions.push(...[{"id":"h18-20060628-16","meetingId":"h18-cm06","date":"2006年6月28日","dateIso":"2006-06-28","committee":"街づくり特別委員会","time":"午前１０時０２分～午後 ２時４５分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（ひ）委員長","kind":"質問・要望","question":"○午前１０時０２分開会おはようあります。本日の予定は、お手元の審査・調査予定表のとおり、報告事項３件、特定事件調査、その他、視察と進めてまいります。前回、今後の委員会運営について皆さんからご意見をいただきましたが、先日、理事者の意見も伺いながら、正副委員長で調整をさせていただきました。今年度１年間、このような形で進めさせていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":1,"id":"exchange-001"}]},{"id":"topic-02","title":"生活安全フォーラム（大人のための騙されない講座）","agenda":"生活安全フォーラム（大人のための騙されない講座）","exchanges":[{"speaker":"築舘委員","kind":"質問・要望","question":"振り込め詐欺とかそういった一連の詐欺というのは、最初は高齢者の方とかをねらってやっていたというようなこともありましたけれども、最近は中高年層にも、昨年１年間でかなりの被害が増えておりまして、その被害者の傾向といいますか、あと犯罪者の傾向、要するに外国人が多いのかとか、そういった一連の傾向がありましたら、教えていただきたい。","respondent":"金子生活安全担当課長","answer":"これは事件ごとにそれぞれ違いがありますので、大ざっぱな説明になるかと思いますけれども、例えばオレオレ詐欺という事案に関しましては、被害者の７７％が女性です。特に４０代、５０代の女性にその割合が高いです。","voiceIndex":5,"id":"exchange-002"},{"speaker":"築舘委員","kind":"質問","question":"かなりそういう犯罪が増えていて、身近なことになっているようですし、犯人が捕まってそういうことが少なくなってくれば一番いいなとは思いますけれども、まずそういった被害にならないようにということで、プログラムですか、講演もされたと思います。","respondent":"金子生活安全担当課長","answer":"それと広報です。民生委員協議会と高齢者クラブにつきましては、それぞれ直接私どもが赴きまして、それぞれ参加要請をして、被害に遭わないようにという形でご参加をいただいております。","voiceIndex":7,"id":"exchange-003"},{"speaker":"大西委員","kind":"質問・要望","question":"振り込め詐欺が増えているということですが、高齢者をねらった次々契約というものも大変増えてきているように感じるんですけれども、消費者センターのほうに相談が行くのかと思うんですけれども、この次々契約の昨今の増減というか、それはどういう状態であるのかを、おわかりだったら教えていただきたいんですが。","respondent":"金子生活安全担当課長","answer":"申しわけございません。次々契約に関しましては、消費者センターのほうにもそういうのがあると思うんですけれども、今の警察等に連絡する中では、ちょっとはっきりしたことは把握してございませんので、調査をしたいと思います。","voiceIndex":10,"id":"exchange-004"},{"speaker":"大西委員","kind":"質問","question":"認知症の症状の出ている方々を次々にねらっているという形で、なかなか認知症の状態の方が表に出にくいというか、相談しにくいという現状もあろうかなということで、大人のための騙されたい講座が、今回は振り込め詐欺に特化したような状態であったのかなと思うんですが、現実的に品川区にお住まいの高齢者の財産を守るという生活権にもつながると思うんですけれども、これをやるためには、区のほうでも、今。","respondent":"早津区民生活事業部次長","answer":"お尋ねの中で認知症の方のリフォームを含めた次々詐欺への対応ということですけれども、これはまた認知症があったりとか、高齢者の一人住まいという部分になりますと、民生委員の方のほかに介護の関係のケアマネジャーが訪問したりする中で。","voiceIndex":12,"id":"exchange-005"},{"speaker":"大西委員","kind":"意見","question":"民生委員の方が３００名程度の方を担当されている。ケアマネもということで、これは介護認定を受けて、何らかの介護サービスを受けている方にとっては、ケアマネジャーならびにヘルパーが行く状態もあろうかと思うんですが、そうでない高齢者もおられるということで、民生委員は大体どれぐらいのスパンでこの高齢者世帯とか独居老人に面談をして、そういうところから私は……。","respondent":"鈴木（ひ）委員長、早津区民生活事業部次長","answer":"民生委員の中身になりますと、この街づくり特別委員会の所管とちょっと違ってきますので、その辺を考えた上でのご発言をよろしくお願いします。その方の状況によってはもっと頻繁な方もいらっしゃるし、お元気であれば、もう少し間遠になる方もあるですが、原則的には月１回の訪問なり接触をしてくださいという形になってあります。","voiceIndex":14,"id":"exchange-006"},{"speaker":"堺委員","kind":"質問・要望","question":"ちょっと確認というか、要望というか、先ほどのお話の中で、出席が３０６名でアンケート回収が１４８名ですか。品川の第１地域センターとか、第２地域センターとか、あるいは１３地域センターがありますが、そういう地域センターという細かい単位の中で、そこに該当するであろう人たちに申しわけないけどお集まりいただいて、そこでこういうことで可能なことについて実施されるというんですかね。","respondent":"金子生活安全担当課長、田村地域活動課長","answer":"１点目の資料の活用の関係について説明を申し上げます。委員のほうからお話があったとおり、講演内容を撮影しまして、ビデオ化いたします。この犯罪の特徴というのは、自分は引っかからないよと思っている方が引っかかるという最大の特徴があるので、既に各地区、特に騙されない講座に限らず、防犯活動は町会長単位の中で取り組んでおりますので。","voiceIndex":18,"id":"exchange-007"},{"speaker":"堺委員","kind":"質問・要望","question":"今お話しいただいて、私が住んでいるほうの町会でも、一町会だったと記憶しているんですね。町会の会館にそういう関係者の人に来てもらって、地元の高齢者クラブでやっていただいたこともあると思うんですが、そういう意味で、さっきおっしゃったとおり、細かい単位でやっていかないと、なかなか防災というのは出てこない、そんな思いがありましてお尋ねをしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-008"},{"speaker":"藤原委員","kind":"質問","question":"昨年１年間で品川区内で１１６件ということですが、１１６件はどのぐらい犯人がつかまったといいますか、解決がされたんでしょうか。","respondent":"金子生活安全担当課長","answer":"人員について正確な数字は把握しておりませんが、ほとんど検挙されていないのが現状だと思います。","voiceIndex":23,"id":"exchange-009"},{"speaker":"藤原委員","kind":"質問","question":"単純な質問なんですが、何で検挙されないんでしょうか。","respondent":"金子生活安全担当課長","answer":"そこからまたたどって次のところに行ったところ、また電話機しかなかった。それが何重にもかかってありまして、相当組織立ってやらないと、この１１６件についての捜査ができないというのが実情と聞いております。","voiceIndex":25,"id":"exchange-010"},{"speaker":"藤原委員","kind":"質問・要望","question":"いろいろな問題があると思うんですけれども、金子課長は生活安全担当課長でいらっしゃいますが、警視庁の幹部として来てくださっているという意味でお伺いをあえてさせていただきたいんですけれども、まず委員長、離れちゃったら注意していただきたいんですけれども、確かに区としては引っかからないようにということで、この講座というのは大事だと思うんですけれども、検挙率というのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-011"},{"speaker":"藤原委員","kind":"質問","question":"荏原文化センターでこういうふうにやったということで、３０６人という形だったんですけれども、今、荏原文化センターを想像して、地域活動課長が数に制限があるというんですけど、３０６人だったら、あそこの舞台から見たら、あいているいすが結構見えると思うんですよ。全然満員になっていないじゃないですか。この辺というのはどういう状況なんでしょうか。","respondent":"田村地域活動課長","answer":"５２０名程度来るという前提だったんですが、実際に土曜日開いてみたら、当初５２０人で満席で、いす席も準備していたんですけど、出ると言っていて欠席の方が若干いたようで、さっきの生活安全担当課長の言った結果になってしまったという状況です。","voiceIndex":29,"id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"その中において、さっき民生委員さんという話が出たときに、ここは所管以外だからその話はしないでくれと言ったんですけれども、いわゆる町会にも、町会に住んでいるけれども、町会に出てこないとか、高齢者なんだけど、高齢者クラブとかに入っていないという方を網羅していくというか、そういう方を守っていくためには、そうすると、今日の答弁というのは。","respondent":"早津区民生活事業部次長","answer":"引き続きどういった方にどういうふうに声をかけると、より集まっていただけるのかというのは、また検討させていただきたいと考えています。","voiceIndex":31,"id":"exchange-013"},{"speaker":"藤原委員","kind":"質問","question":"最後にしますが、具体的にこれはオレオレ詐欺に遭ったかもしれないというのを３７７７－１１１１に区民の方がかけてきたときには、どこの課に行って、承った課は具体的にどういうふうに動いて、どういうふうに処置していくんでしょうか。","respondent":"金子生活安全担当課長","answer":"そういった場合については速やかな対応が当然必要だと思います。生活安全担当のほうでお受けして、警察の関係部に速やかに連絡していただいております。ただ連絡するのではなくて、その際には一時的な対応等を指示した上で連絡をしたいと考えております。","voiceIndex":33,"id":"exchange-014"},{"speaker":"須貝委員","kind":"質問","question":"もちろんどうしても伝わらないところもあるかと思うんですけど、私思いますに、特に振り込め詐欺ですか。確かにこういう取り組みとかチラシ、パンフレット、ほんとうにこれも大切なことだと思うんですけど、電話でとりあえず押さえるべきことは押さえて、受話器をとったらそこに相談の電話番号が載っているという、そういうことも区で考えられたらどうかなと思うんですけど、その辺いかがでしょうか。","respondent":"金子生活安全担当課長","answer":"これにつきましては警察のほうでもやっているところです。ただいろいろな形でさらに可能な限りそういったものが拡大していくことが必要かということもありますので、警察のほうと連携をとりながら、一番いい方法を検討していきたいと思います。","voiceIndex":35,"id":"exchange-015"}]},{"id":"topic-03","title":"２番目の木造住宅の耐震改修支援事業の概要","agenda":"２番目の木造住宅の耐震改修支援事業の概要","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"それから今年度の予算がついて、今か今かと待っていたんですけど、６月から始まるとかと言われていながら７月１日に、いろいろな準備があったことだというふうには思うんですけれども、その７月１日から実施するに当たっての、区民の皆さんへの周知は２１日後の広報だということで、ホームページには掲載するというお話ですけど、やっぱりいいことですから。","respondent":"片田建築課長","answer":"制度としてのフレームといいましょうか、それを区のほうでも調整する時間がどうしても必要だということの中で、７月１日を開始予定としたものです。","voiceIndex":41,"id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"いろいろと説明はいただいて、一定程度理解はしたいと思っているんですけれども、しかし品川の対象地域になっている防災の早急な対策を立てるという緊急度合いがかなり厳しい状況ですから、それはそれとして理解はしますけれども、しかし、ほかの地域でもひとたび地震が来たときに倒壊するとかで圧死をされる方が出るとか、あるいは火災の延焼になって被害が拡大するということだってあるわけですから。","respondent":"片田建築課長","answer":"これは３月３１日末現在ですけれども、補強工事を完了したもの、それとあわせて補強に向けた対応を検討しているというものを含めると、約２０件の件数があります。その２０件の内訳ですけれども、その約７割が整備地域に入ってきている。","voiceIndex":43,"id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、どの程度これがこの１０年の間に進んで改善されていくかはよく見守っていきたいと考えていますけれども、そういう区民の声も少なからずあるということはやっぱり見ていただいて、そして今後の検討に加えていきたいと考えていますので、要望だけさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-018"},{"speaker":"藤原委員","kind":"質問","question":"個人資産に税金を、いわゆる助成というか、７５万円を限度に上げるわけですよね、個人の所有物に関して、そこに税金を投入するのはどうかなと思っていましたが、今の課長のご答弁を伺っていて、もっともだなと思いました。５棟は残りました。もっと大々的にやればいいと思うんですけれども、なぜたった５棟をということで出してくるんですか。","respondent":"片田建築課長","answer":"そういうことを含めると、当面数字として実際に成果が上げられるというものを想定した中でその数字を想定してきたわけですので、今後の診断および状況を十分踏まえて、この部分については検討してまいりたいと思ってあります。","voiceIndex":47,"id":"exchange-019"},{"speaker":"菊地委員","kind":"質問","question":"改めて聞きたいんですけれども、新耐震基準前の木造建築物が区内全域に何棟あって、この整備地域内に何棟あるのか、その数字について教えてくれますか。","respondent":"片田建築課長","answer":"先ほど申し上げましたような面積にしていけば、その３分の１というところでの単純な比較計算はできませんし、逆の７割が、診断を受けた中での７割が整備地域内の方だったというのは、２万棟の割合の相当数が整備地域の中にあるのかなということを考えてあります。","voiceIndex":50,"id":"exchange-020"},{"speaker":"菊地委員","kind":"質問・要望","question":"今一緒に聞けばよかったんだけど、忘れてしまいましたけど、さっき平成１８年度から２７年度までが東京都の時限的な措置だということでしたけれども、東京都はどの程度今度のこの施策で東京全体でこの改修を行おうとしているのか、その辺の件数、棟数としてわかれば教えていただきたいんですが。","respondent":"片田建築課長","answer":"これはちょっと古い資料ですけれども、１月の新聞報道等々によれば、東京都が診断改修助成へということで、整備地域で、今後１０年で２万棟強を予定しているという情報が入ってあります。","voiceIndex":52,"id":"exchange-021"},{"speaker":"菊地委員","kind":"質問","question":"東京都が１０年間で２万棟、品川の場合５棟で、１０年間やったとしても５０棟ですか。そういう中での１０年間５棟ずつと考えたときの５０棟というのは、あまりにも少ないような気がするんですよ。そうすると年間１００万円の予算ということになりますよね。その辺を考えれば、危険度はそのまま野放しになるのではないかなという感じがするんですけれども、いかがでしょうか。","respondent":"片田建築課長","answer":"ただ整備地域、東京都のプレス発表では２万棟強というのを出していますけれども、私どものほうも１０年かけて毎年５棟ということは考えてございませんで、私ども今回このように出させていただいた中で、当然初めての事業ですので、今後の様子を当然視野に入れながら。","voiceIndex":54,"id":"exchange-022"},{"speaker":"菊地委員","kind":"質問","question":"今、最後のほうで、毎年５棟とは考えていないということですけれども、ただ東京都と同じように１０年間に限定だというのであれば、１０年間でどれだけ耐震改修する目標を持っているのかというのを教えてください。","respondent":"片田建築課長","answer":"そういうことも含めて、私どものほうとして、地域を限定した中で改善策を考えてきているわけですので、少なくとも啓発に努めて、そういうまたアンケート調査を行いますから、それもよく確認していきたいということで考えております。","voiceIndex":56,"id":"exchange-023"},{"speaker":"菊地委員","kind":"質問","question":"啓発だというのはわかります。２万棟すべてが補助できるわけではないと思いますし、ただ実際に、これはだれもがわかっていることですけれども、実際いつ大きな震災が起こるかわからないという現状の中で、啓発というんだけれども、区の姿勢として、５棟なのか、５０棟なのか、１００棟に対する支援なのか。だから、その辺をもう少し考え方としてお聞きしたいんですけど、いかがでしょうか。","respondent":"片田建築課長","answer":"考え方はこれまでご説明してきた中だと私は考えてありますけれども、これだけの対象件数があるから、それを計画的にやっていくんだということでは私はないと考えております。","voiceIndex":58,"id":"exchange-024"},{"speaker":"菊地委員","kind":"質問・要望","question":"１つだけ言っておきますけれども、先ほど教えていただいた他区との関係で言えば、５棟というのは、東京都の目標なんかも含めて、非常に少ない数字ではないかなと思うんです。私は品川区全体が危険度を持っている中で、もう一度改めてこの辺は耐震診断をやられた、前年６０件といいましたっけ。そこもすべて対象にしていくぐらいの体制をぜひつくっていただきたいと思います。","respondent":"片田建築課長","answer":"その中で東京都としても、広域自治体として、耐震改修計画の策定を検討していると聞いてあります。これらのことを十分視野に入れながら、必要な対応を考えていきたいと思います。","voiceIndex":60,"id":"exchange-025"},{"speaker":"須貝委員","kind":"質問","question":"それについて１点質問。それと、当時の基礎、古い年代の、まして木造ということを考えると、実際さらに傾きまで防ぐとなれば、相当高額な、１５０万円という金額じゃなくて、それこそ１件当たり２階のモルタル構造で２０坪または１０坪等々の建物がありますけど、３００万円なり５００万円なり、下手すればもっと相当の金額がかかるんじゃないかなと思うんですけど、ちょっとその辺の見解をお聞かせください。","respondent":"片田建築課長","answer":"震度６強というような状態であれば、いわゆる旧耐震ではそれをもとに安全性が検討されていますけれども、震度６の地震であれば、仮に多少傾いたとしても、あるいは修復すれば引き続き使用が可能ということを目標としていますので、木造の構造についても。","voiceIndex":62,"id":"exchange-026"},{"speaker":"須貝委員","kind":"質問","question":"ということならば、その事業をやるに対して、今、古い建物で改修をするよりは、今、区のほうでも建替え促進事業を老朽化建物に対してやっていますけれども、基礎や建物の構造というのはほぼでき上がって、でき上がっているところを改修しようとするならば、もともとの根本の基礎とか構造が問題があるんですから、逆に新しく、今、金額のことは金額がかかるのであれなんですが、新しく建てたほうが。","respondent":"片田建築課長","answer":"ただ委員おっしゃるように、地域の中で整備地域という枠の中にさらに重点整備地域、区内で４６０ｈａほどの地域を指定していますけれども、そこの中では建替えの支援ということも含めて、不燃化促進事業、あるいは密集住宅市街地整備促進事業、建替えに対する支援も行っており。","voiceIndex":64,"id":"exchange-027"},{"speaker":"堺委員","kind":"確認","question":"災害に強いまちづくりを区は推進をしていくのだということですから、国土交通省だったでしょうか、あるいは文部科学省だったでしょうか。今回５棟で７５万円ですから、トータル的にいきますと３７５万円という計算ですね。区の持ち出しは１棟当たり２１万円ですから、１０５万円ですよね。それぐらいの投資はやりますよというぐらいの意気込みというんですかね。それを含めて確認をしておきたいんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-028"}]},{"id":"topic-04","title":"３番目の小山台一丁目地区防災街区整備地区計画","agenda":"３番目の小山台一丁目地区防災街区整備地区計画","exchanges":[{"speaker":"菊地委員","kind":"意見","question":"説明のほうだけの話なんですけれども、１つお願いは、資料上の問題なんですけれども、先ほど課長の説明があったように、この地域はいろいろな制度がかかっている地域ですよね。こういう資料を出されるときに、この地域にどういう制度がかかっているか、この地域ですよみたいな、もっと重複した資料として出していただけないかなというのが１つお願いなんです。これをもう少し説明をしていただけますか。","respondent":"伊勢住環境整備担当課長","answer":"今ご指摘ありました点々から広域避難場所「林試の森公園」の間ですけれども、カラーでなくて申しわけないんですけれども、資料２の４ページをごらんいただきたいんですけれども、こちらに既に防災生活圏促進事業を行っておりまして、この資料のちょうど斜線の部分ですけれども。","voiceIndex":74,"id":"exchange-029"},{"speaker":"菊地委員","kind":"質問・要望","question":"もう１つだけ教えていただきたいんですけれども、間口率が出ていますけれども、要は敷地と接合部分の関係なんですけれども、この間口率を定める必要性といったらおかしいかな。どんな文章を読んでも１０分の７とかと出ているんですけれども、ちょっと間口率のところだけ。","respondent":"伊勢住環境整備担当課長","answer":"これは面的なものなんですけれども、それが線であらわした場合に、横から見た場合、７割ぐらいあると、この場合は延焼遮断と避難路の確保と両方やるわけなんですけれども、片一方の面が燃えたとしても。","voiceIndex":76,"id":"exchange-030"},{"speaker":"菊地委員","kind":"質問","question":"それは規定としてこう言われている話で、規定としてそれがあるととらえていいんですか。","respondent":"伊勢住環境整備担当課長","answer":"それに今出てきました間口率、ここには直接書いていないんですけれども、一般的には７割の面ですけれども、それを横から見た場合に７割ぐらい、一番いいのは１００％ですけれども、通風等の問題があると思いますので、７割ぐらいあれば大体避難所が確保できるのではないか。","voiceIndex":78,"id":"exchange-031"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"今回は品川区内５カ所ということですけれども、大体品川区内にはどのくらいの交番が設置されているのか、空き交番はその中でどのくらいあるのか、ちょっとその辺をまず教えていただきたいと思います。","respondent":"金子生活安全担当課長","answer":"区内には３４の交番があります。このうちの空き交番について具体的な数字は示されておりません。ただここにある５つの交番については、この中のさらに幾つかは空き交番と言われるものが含まれております。","voiceIndex":88,"id":"exchange-032"},{"speaker":"南委員","kind":"質問・要望","question":"あまり長く質問できないのであれなんですけれども、八潮に私も住んでおりますけれども、大井ふ頭交番ということでは、八潮団地から外側だと思うんですけど、あの辺は結構土日はオートバイの暴走だとか車の暴走だとか、結構八潮団地には音が聞こえていまして、住民の方たちもうるさいよという声が、遠く離れていてもうるさいということが結構日常的にありますので、そういう関係では。","respondent":"金子生活安全担当課長","answer":"これは新聞等の報道にもございましたけれども、隣接交番との距離、あるいは業務負担、もう少し詳しく申し上げますと、刑法犯の発生件数であるとか、交通事故の処理件数あるいは１１０番の入電件数、こういったものの業務負担の低い高いということになると思いますけれども。","voiceIndex":90,"id":"exchange-033"},{"speaker":"南委員","kind":"意見","question":"最後に意見だけ申し上げておきます。そういう点では、むしろ見直すのではなくて、なくしていくのではなくて、空き交番の解消、ちゃんと配置をして解消していくことこそ市民の願いだと思うので、その点で、時間もありませんので、もう少し別の時間をあれして議論していければいいと思いますけれども、今のところ、私の意見だけ述べて終わりにしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":92,"id":"exchange-034"},{"speaker":"堺委員","kind":"質問・要望","question":"そういうところが５カ所といえども、３４のうち５カ所がなくなるわけですから、そういう意味で品川区的にはこれから検討されるですので、ぜひひとつ安心・安全のまちづくりという視点からも、犯罪の抑止、防止、いろいろな面からさらに区として各警察署と連携をとっていただいて、交番が１つなくなったために、品川区内の犯罪がふえたということが絶対に起きないように、対策を講じていただきたい。","respondent":"鈴木（ひ）委員長","answer":"この問題に関しては特定事件調査でもこれからも取り組んでまいりますので、その中でまたいろいろ出していただければと思います。これでその他を終了いたします。","voiceIndex":94,"id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6328#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":32115,"voices":96}},{"id":"h18-20060629-14","meetingId":"h18-cm06","date":"2006年6月29日","dateIso":"2006-06-29","committee":"行財政改革特別委員会","time":"午前１０時１２分～午後３時２４分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"須藤委員","kind":"質問","question":"東部が品川大崎土木事務所につながってきて、大井土木事務所の下の旧東部公園出張所には全然ラインがないですよと。ですから、この線のつながり方はまたいでここに来ないと、西部の一部はそこに来るだろうけどもということなので、このままスタートしてしまうと誤ったままいってしまうので、いかがでしょうか、私の見方が悪いのか教えてください。","respondent":"日下部企画財政課長","answer":"大変申し訳ございませんでした。確かに、今、ご指摘を受けまして、私も初めて気がつきましたが、おっしゃるとおりだと思います。その辺は、また改めて再確認をいたしまして、訂正をさせていただきたいと思います。","voiceIndex":8,"id":"exchange-001"}]},{"id":"topic-02","title":"これより、特定事件調査を行います。 公有地等の活用に関すること","agenda":"これより、特定事件調査を行います。 公有地等の活用に関すること","exchanges":[{"speaker":"須藤委員","kind":"質問・要望","question":"何点か質問をします。そういったものの考え方が、どのように対応してくるのかということが一つ懸念が残ること。というのは、ケアホームは今後も当然必要になってくる施設だろうけども、地域的に各地区にいろいろ分けて整理していったほうがいいだろうと思っているので、そのあたりの考え方を教えてほしい。今お話ししたような検討の余地があるのではないかと思うので、その辺のお考えを聞かせてください。","respondent":"日下部企画財政課長、新美企画部長","answer":"西大井ほっとサロンも介護予防的な役割も含めて、団塊の世代の人たち、少し若い世代の人たちも含めて対象にしていくわけでありますけれども、今回、原小学校跡の整備にあたりましては、これから具体的に詰めてまいりますけれども。しかしながら、今後も高齢者の数は増えてまいりますし、要介護の高齢者も数が増えていくということは当然想定されますので、その数の増を踏まえつつ、これからはグループホームとか。","voiceIndex":15,"id":"exchange-002"},{"speaker":"須藤委員","kind":"質問","question":"先ほど、福祉施設は大規模ではないというけど、福祉施設利用部分というのは幼保一体施設も含めて全部が校舎の３階まであるわけです。あなたたちはここだけですよ、こちらは地域住民ですよという線をつくるのではなくて、乗り入れられるような形の絵のほうが、民間の方々もいろいろな面でやりいいのではないかと思うので、そういった質問をさせていただいたのですが、その辺はいかがでしょうか。","respondent":"新美企画部長","answer":"そうしますと、やはり学校というのはかなり大規模な施設でありますので、その辺を当然行政需要として何に活用していくかということを検討したときに、やはりここの地域も含めて品川区においても。","voiceIndex":18,"id":"exchange-003"},{"speaker":"伊藤委員","kind":"確認","question":"それを具体的に地域の中に落とし込んでいくと、いろいろな矛盾が出てくる。確認したいのは、今、２町会の避難所になっているわけですが、その方々が原小学校以外に避難できるところがあれば話は別ですけれども、そうではなくてそれも担保しながら、しかもこのような施設を入れていくとなると、避難所計画そのものを見直さなければいけないことになってくるわけですが、どのようにお考えかお聞かせください。","respondent":"日下部企画財政課長","answer":"この点で考えてみますと、今の原小学校の算定にあたりましては、１階に事務室、職員室、校長室、特別教室が結構ありますので、実際の避難人口の算定にあたりましては、１階部分が算定対象に入っておりませんで、ごく一部です。","voiceIndex":20,"id":"exchange-004"},{"speaker":"伊藤委員","kind":"確認","question":"計画上は７００名でしょう。でも、実際はもっと来る可能性は十分ある。だから、ニーズがあることもわかります。ですから、今の避難所の運営一つを取っても、数字はそうかもしれない。ですから、１階を固定した施設に使うということは、自動的に避難所に使えなくなるわけですから、そのことを十二分に考えて対処してくださるのでしょうかという確認の答弁をお願いします。","respondent":"日下部企画財政課長","answer":"十分にご心配のないような形で整理をするということで、進めてまいりたいと考えています。","voiceIndex":22,"id":"exchange-005"},{"speaker":"川西委員","kind":"質問・要望","question":"基本的には、要望したいものが入ってありますので、言うところがないぐらい賛成です。土曜、日曜のみサッカーや少年野球に使っていただくのかどうか、この辺を伺います。ああいうものがここに入れないのか、入れないのだったら要望だけでとどめますけれども、私はまだ西大井ほっとサロンを見せていただいていないから、それがかわるのかなと思いますけれども、そのように思います。","respondent":"日下部企画財政課長","answer":"ですから、幼保一体施設の園庭としての利用ということになれば、平日は少なくとも夕方までは難しい状況になりますので、基本的に少年野球、サッカーで今までの経過も含めてご利用いただくということでありますけれども、その辺をどうするかというのは。","voiceIndex":24,"id":"exchange-006"},{"speaker":"川西委員","kind":"質問・要望","question":"１点だけ要望です。今おっしゃった幾つか挙げられた児童センター、区内の児童センターはティーンズプラザ八潮に比べて比較的規模が小さくて、いろいろな要素を取り入れるには不足です。せっかくですから、跡地利用のときには規模のきちんとしたものをつくっていきたいというのが、品川区に対する願望です。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"基本的な考えのところからお伺いいたします。その辺で、地域の方々はこの地域で今後どうあってほしいのか、学校が小中一貫校で移ってしまうのは仕方ないとしても、地域の方が今まで求めていたこと、今後求めていくことというところでは、どう願っているのかという、その辺をどう受けとめていらっしゃるのか、ここにどう生かされているのかという点をお伺いしたいと思います。","respondent":"日下部企画財政課長","answer":"そういった考え方に基づきまして、私どもは長期基本計画に基づいて中期計画として実施計画の策定をしておりますけれども、幼保一体施設、ケアホーム、シルバーセンターの介護予防拠点としての整備、これもすべて実施計画の中におきましても。","voiceIndex":27,"id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"長期基本計画の中でも、区民との架け橋ということでは、住民参加型ということが書かれております。インターネットを引くと、空いた場所をどうするかというより、もっと生涯教育に使っていくとか、ものづくりに使っていくとか、結構いろいろなアイデアが盛り込まれているので、この案のままいくということではないだろうということも含めて、いかがでしょうか。","respondent":"日下部企画財政課長","answer":"それをスタートにいたしまして、議会からご意見をいただく。さらに地域にもご説明をさせていただいて、ご意見をいただく。","voiceIndex":29,"id":"exchange-009"},{"speaker":"飯沼委員","kind":"提案","question":"住民参加型というところで、公募型はどうかという提案をさせていただいたんですけれども、学校の問題は、これから八潮の問題とか、次々に検討することが生じてきます。そういった面では、スタイルにこだわらなくて、もっと住民が意見を言いやすい方法もぜひ編み出してほしいと思っています。これは要望で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":31,"id":"exchange-010"},{"speaker":"松澤委員","kind":"質問","question":"ただ、今まで学校ですと校庭開放の時間にトライした部分がありませんので、日曜日、祭日、土曜日、丸々使えるということでは、本当に開放してくれるというなら、少年サッカーにも少年野球にとっても本当に大きいんですね、朝から試合が組めるわけですから。今の朝練をやっている、夕方やっているというのは全然違いますから、その辺を。","respondent":"日下部企画財政課長","answer":"ただ一方で、校庭の利活用の問題というのは、地域にとって非常に重要な課題でもありますので、地域の少年野球、サッカーの利用は今までの経過もあって大事にしなければいけませんけれども、対外的な試合とか、より幅広い活用の可能性も出てくるわけでありますので。","voiceIndex":32,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"前回の委員会で、最善の努力を払うとおっしゃっていましたけれども、まず伺いたいのは、先ほど話していた区政協力委員会や関係者、ホームページ、具体的にどのようなものなのか、いつどのような規模なのか、もう少し詳しく教えていただきたい。それから、まず計画がどのようなものなのか。それはどのように考えているのか、ぜひ行うべきではないかと思いますけれども、いかがでしょうか。","respondent":"日下部企画財政課長","answer":"私どもが言うのも何ですが、比較的きちんと手順を追ったご説明を区の責任において行っているわけでありますので、そういう形でご意見、ご要望を承るという、一つのやり方で十分に区民の皆様方のご意見等は私どもとしても受けとめることができるのではないかと。","voiceIndex":34,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ、最善の努力と、「こういう計画です」ということを、説明会という形なのか、公聴会という形なのか、やることは最低限のことではないのかなと思うんですけれども、ご見解を伺いたいと思います。アンケートの中には、例えば「どのような議論、検討案があるのか、区民にオープンにしてほしい」とか、「区の広報とか町会の回覧板の中でも、広くみんなに意見を聞いてほしい」。","respondent":"日下部企画財政課長","answer":"例えば、シルバーセンターの関係者、利用者の皆さん方にもご説明の機会を持つとか、そういう意味ではできる限り幅広く区としての考え方をご説明させていただいて、ご意見、ご要望をいただくという具体的な手順は取ってまいりますので。","voiceIndex":36,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"ＰＴＡの方々はもちろん大事だと思います。それぞれ関係者の方に伺いますので、そこにお寄せいただいてもいいですし、今日のこの場所でもお聞かせいただいてもいいですし、時間がなかったら配ってある用紙に書いて帰りに渡していただいてもいいとか、いろいろな形はあるかと思うんです。なぜ、住民の状況にきちんと耳を傾けていただきたいのかというと、具体的な計画案を見てもそのことは感じるんです。","respondent":"日下部企画財政課長","answer":"ホームページでは、組織的にどうのこうのというより、幅広く区民の皆さん方からご意見をいただくというやり方も併用して、幅広くご意見をいただくような形を取っていくわけですから、そういった意味では。","voiceIndex":38,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"これだけ確認させてください。このことを聞くと、「いや、一般的に広報広聴課のページにありますから」という一般論ではなくて、きちんとページの中に、メールなのか電話なのか、ファックスなのか、お手紙なのか、手法はあるかと思うんですけれども、それが載せられているかどうか、そこだけ確認をさせてください。料金がどうなのか教えてください。いかがでしょうか。","respondent":"日下部企画財政課長","answer":"ケアホームの関係ですけれども、施設としてケアホームを配置するということでありまして、具体的な条件をどういう形で設定していくか、例えば部屋の広さの問題とか、いろいろ要素は絡んでまいりますので、もう少しきちんと骨格が固まった段階で整理調整しまして。","voiceIndex":40,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"もう１点、先ほどサッカーや野球の話が出ていましたけれども、あそこは教育施設ですからスポレク委員会が月１回、調整会議をやって、こちらの学校の改修があったときには、こちらに移動するとか、そういう調整をしています。要は、４月以降、教育施設の枠が外れると、スポレク委員会の月１回の利用調整会議というのはどういう関係になるのか。","respondent":"日下部企画財政課長","answer":"そういった意味では、利用が制約されるとか、そういう心配は基本的にはないと思います。ただ、学校の部活絡みの関係でいろいろな影響が出てこないとも限らないという話は承知しています。","voiceIndex":42,"id":"exchange-016"},{"speaker":"須藤委員","kind":"質問・要望","question":"小中一貫校の跡地利用というのは、先ほど来いろいろありますけれども、新たに出てきた考え方で跡地が生じてきている。ですから、行政側の考え方が新たに出た小中一貫校の跡地をこのようにしよう、こうするのだというものをしっかり示していかないと、例えば八潮に今度つくります。今、説明すればいいというだけではないだろうと感じているので、その辺を聞かせていただきたいと思います。","respondent":"新美企画部長","answer":"したがって、複合的な活用も含め、あるいは全面的に更地にして新しく建てるということも含め、その時点で今の段階の予定されているところについては、その土地について多角的にさまざまな関係方面のご意見もいただきながら、検討せざるを得ないというのが。","voiceIndex":44,"id":"exchange-017"},{"speaker":"須藤委員","kind":"質問・要望","question":"しっかりとしたものを行政側から我々に示してもらわないと、ここではこれだけのメニューでいいですかと言われても、これだけのものが必要だというのはわかるけれども、もっと品川区全体の絵をしっかり見せないと、有効活用にならないのではないかというのが私の考え方だけれども、それは考え方だけで、まだこのとおりコンクリートしたわけではないというので、もう少し議論をさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-018"},{"speaker":"井上委員","kind":"提案","question":"先ほど、いみじくも課長は、今回は行政が考える一つの提案として示させていただいたということですから、これ以外に提案があれば、そういう形で進めていくと。今回は、企画財政課が窓口になってしっかりやりますということでしたので、そういう対応をしてほしいと思います。出されている以上、ある程度のものは見えているのではないかと思うんですけれども、いかがですか。","respondent":"日下部企画財政課長","answer":"確かに、西大井保育園、伊藤保育園もありますけれども、新しい区民のニーズにしっかりとこたえる形で、新しい施設である幼保一体施設をここに配置していきたいという基本的な考え方です。","voiceIndex":47,"id":"exchange-019"},{"speaker":"井上委員","kind":"意見","question":"この計画を知る上では、非常に重要なことですが、幼保一体施設でどのぐらいの人数の規模を考えているのか。通勤に行く前に、そこに寄らなければいけない。逆に戻って来て、そっちに行くということが、どれだけ子育ての人たちが苦労されるのかということを考えると、立地場所というのは、つくったからいいというものにはならないと思うので、その辺のことを考えると、どの程度の規模を考えていらっしゃるのか。","respondent":"日下部企画財政課長","answer":"大体、１,０００m2程度を考えておりますけれども、それでいきますといろいろな基準があります。１人当たり何m2という基準もありますから、それで計算しますとおおむね１００名強ぐらいの規模で整備できると見込んでいるところです。","voiceIndex":49,"id":"exchange-020"},{"speaker":"井上委員","kind":"質問・要望","question":"滝王子児童センターは過密状態の児童センターであり、冨士見台では友達とうまくいくかどうかという不安があるということで、やはりこの地域に住んでいる子どもたちは、学校は小中一貫校に行っても、こういった場を居場所として残してほしいという要望がたくさんあるかと思うんです。今後、そのようなことをする予定があるのかお伺いします。","respondent":"日下部企画財政課長","answer":"この辺を一応踏まえて、地域の活動・交流拠点ということで計画案の中にも盛り込ませていただいているところですので、具体的に何をどのように運営体制を取っていくかというのはこれからですけれども、基本的な今ご指摘の点は。","voiceIndex":51,"id":"exchange-021"},{"speaker":"井上委員","kind":"質問","question":"保育園施設と同じようにケアホームの計画を、第３次介護保険制度でも推進していく計画を立てていらっしゃるということですが、全体的に福祉をどうするかというところで、学校が空いたから、そのたびに学校がそのような施設になると危惧されるということがあった関係で、先ほど特別養護老人ホームは整備する目標値に達したと、ケアホームは今後の課題であるということで。","respondent":"日下部企画財政課長","answer":"そういった意味では、地域バランスに配慮しながら、全区的に整備していくという基本的な考え方のもとで、例えば今回のように具体的に整備が可能なところが出てくれば、それを中長期の視点で実施計画の中に盛り込んで、具体的に整備を進めていくという考え方です。","voiceIndex":53,"id":"exchange-022"},{"speaker":"井上委員","kind":"質問","question":"運営方法のところで、幼保一体施設、ケアホーム、介護予防拠点の福祉施設は、一括で貸し付けをされるという方法は、今後指定管理者制度への移行になるのか、どういう形になるのでしょうか。","respondent":"日下部企画財政課長","answer":"例えば荏原区民集会所も東大井区民集会所も、地域の町会を中心にして運営委員会をつくっていただいて、そちらが運営の母体になっているという実例がありますので、今回、原小学校につきましても、そのような形を含めまして具体的な運営体制を。","voiceIndex":55,"id":"exchange-023"},{"speaker":"井上委員","kind":"質問","question":"今のところだけ、民設民営ということは、改修の費用は区が改修するのではなく、事業者を選定して事業者の費用で改修していくということですか。","respondent":"日下部企画財政課長","answer":"この辺は、お互いにどのように負担し合うかというスキームについては、これから具体的に詰めていきたい。今の段階では、そこまではっきりした形は出せませんので、その辺はこれから検討、調整をしてまいりたいと考えております。","voiceIndex":57,"id":"exchange-024"},{"speaker":"井上委員","kind":"提案","question":"介護保険は仕組みが変わる場合には、極力行政は率先してやっていただいているわけです。本当に地域のシンボルとなる、あるいは高齢者施設になったとしても、子どもたちが自分たちの学校だったよと地域に戻ったり、そこに顔を出せるようなことは必要なことだと思うので、そのような要望があった場合には、行政として説明する予定があるのかないのか、お伺いします。","respondent":"日下部企画財政課長","answer":"そういう意味では、いろいろな意見があるでしょうが、やはり地域の声を広く受けとめていただいている方々だと私どもは承知しておりますし、まずはそういう形でこちらからご説明をするということから進めていくのが基本ではないか。","voiceIndex":59,"id":"exchange-025"},{"speaker":"井上委員","kind":"質問・要望","question":"手順はいいのです。ですから、議会に報告しました、区政協力委員会に中旬、下旬、２回説明します。そこは、どうぞ積極的に十分していただきたいと思いますけれども、地域の方たちが説明をしてほしいと言ったときに、きちんと説明をしていただく機会を持っていただけますかということについてのお考えを伺っただけです。","respondent":"日下部企画財政課長","answer":"あまり拒むような言い方というのはしたくないですが、ただルール、手順ということでまいりますと、例えば何人かが、自分たちの有志が集まったから、そこに来て説明して、自分たちの意見、要望を言うよと。そういうランダムな形でやっていくのは、果たして適切なのかどうか。","voiceIndex":61,"id":"exchange-026"},{"speaker":"井上委員","kind":"質問","question":"いろいろなケースで知らなかったとか、説明不足だったという指摘がいろいろなところでありますので、行政として説明しましたではなく、聞きたい人たちに説明をしてほしい。どういう形であればお話がいただけるのですか。","respondent":"日下部企画財政課長","answer":"いろいろなご意見、ご要望はあるでしょう。繰り返しで大変恐縮ですが、こちら側からきちんとルール、手順を踏んでご説明をする。","voiceIndex":63,"id":"exchange-027"},{"speaker":"藤田委員","kind":"質問・要望","question":"今、教室で一定のスペースしかありませんけれども、例えば補強とか改修工事を行い活用するとなっていますので、その壁をぶち抜いて、いろいろなグループが使いたいと言っているわけですから、それを拒まないような形で多目的に、どうぞ皆さん使ってくださいと。これだけの施設ですから、何でも使えるわけですから、やはり危険のないような、安心して使えるような、そういう施設を考えていただきたい。","respondent":"日下部企画財政課長","answer":"今、ご指摘のような形での施設の活用、運営もいろいろな形でできる可能性を持っていると思いますので、この辺は十分に地域のほうともいろいろ意見調整をしてまいりたいと考えております。","voiceIndex":65,"id":"exchange-028"},{"speaker":"藤田委員","kind":"質問・要望","question":"やはり、この施設が地域の方々のベストパートナーとなるような施設を、ぜひ頭だけの難しいということではなくて、確かに難しいということは我々もわかっています。補強すれば使えるというところも、私たちは見てきているわけです。その辺の研究をお願いしたい。この辺の管理体制をしっかりとした、これは長期にわたるわけですから、その辺もぜひ研究をしていただきたいということを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-029"},{"speaker":"中島委員","kind":"質問","question":"先ほどからいろいろなご意見が出ているんですが、最初にお伺いしたいのは、今回の基本的計画を出されるにあたって、まちの中の声を参考にされたのでしょうか。","respondent":"日下部企画財政課長","answer":"前回も触れさせていただきましたけれども、ＰＴＡの皆さん方を中心にしまして、事前にぜひともという形で強く要望が寄せられました。その辺も参考にさせていただいた上で、計画の中に盛り込ませていただいたです。","voiceIndex":68,"id":"exchange-030"},{"speaker":"中島委員","kind":"質問","question":"その上でいろいろな計画を立てるんですが、建物がしっかりしているので、いろいろ使い勝手はあると思うんですが、中にはいろいろな施設をつくるとなったときに、改修したほうが費用がかかってしまう場合も考えられるのではないかと思いますので、その辺の比較をしていく研究は必要ではないかと思うんですが、いかがでしょうか。","respondent":"日下部企画財政課長","answer":"学校の校舎を改修するとなると、先ほど藤田委員からもありましたように壁の問題とか、いろいろ制約条件が出てきますので、なかなか難しい面があります。ある程度、その辺は施設の所管しているところといろいろ調整しまして、最終的には十分改修してもしっかり使える。","voiceIndex":70,"id":"exchange-031"},{"speaker":"中島委員","kind":"質問・要望","question":"役所が地域の人たち全般にというのは大変なことですから、できるものではないと思うんです。これに関してではないですが、一つ要望しておきたいのは、地域の声を区政協力委員だけに「皆さんのご意見はどうですか」と聞くだけでは、町会長によっては、そこで「いいですよ」で終わっている場合があるんです。今後いろいろなことを開発していく上で、お願いしたいと思うんですが、いかがでしょうか。","respondent":"日下部企画財政課長","answer":"幅広くご意見をいただくという上で、今、ご指摘の点は非常に重要な点だと思いますので、これはしっかりとお願いしてまいりたいと考えております。","voiceIndex":72,"id":"exchange-032"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先ほど来、少子高齢化に対応というのは十分わかるんですが、１のところで具体的に幼保一体施設、高齢者のところはケアホームという具体例が出ているんですが、なぜここに絞られてきたのか、データとか検討過程がどういう内容だったのか教えていただきたいと思います。なぜなら、幼保一体施設は、幼稚園と保育園のどちらにいても、子どもが同じような教育を受けられるという希望は多いと思います。","respondent":"日下部企画財政課長","answer":"データ、検討過程ということでありますけれども、幼保一体施設は先ほど申し上げましたように、委員からもご指摘がありました、幼稚園と保育園のメリットを融合化している。","voiceIndex":76,"id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ケアホームのところは、多様なニーズにこたえていく。この点をもう１回。幼保一体施設のところも、幼保一体化と一括りにしてしまったら、そうかなと思うけど、どのような中身ができるのかという、区のコンセプトがあるのですか。なぜ、このような形を選ぶのかという疑問も生まれてくるわけですけれども、幼保一体化のイメージを全然持たないで業者に任せてしまうのでしょうか、その辺はどうですか。","respondent":"日下部企画財政課長","answer":"具体的な諸条件については、これからいろいろ整理をしていくということですが、ただはっきりしていることは、保育ニーズにしっかり対応していくということが非常に重要な点ですので。","voiceIndex":78,"id":"exchange-034"},{"speaker":"飯沼委員","kind":"質問・要望","question":"保育園と幼稚園の需要を区が長期計画の中でどう解消していくのか見えないために、こういうときに中身はどうなのかという質問が殺到すると思うんです。それから、運営主体ですが、校舎を貸し付けて民間に運営をさせるという意味では、公設民営なのか民設民営なのか、区との関係がどうなっていくのかという心配をされるわけですが、区との関係はどうなるのでしょうか。","respondent":"日下部企画財政課長","answer":"民間による運営ということでありますけれども、先ほど社会福祉法人のケースを出させていただきましたけれども、基本的には土地と建物はもちろん区の所有でありますので、広い意味では公設民営というとらえ方をしていただいたほうがよろしいかと思います。","voiceIndex":80,"id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問・要望","question":"公設民営ということですけれども、指定管理者制度でいかに議会が、区民がチェックできる仕組みをつくるかと言っている中で、公設民営方式になると指定管理者のところより、さらに遠くに行ってしまってチェックができなくなってしまうのではないかという危惧をしています。この辺は、非営利のところでやってほしいということを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5802#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":38385,"voices":87}},{"id":"h18-20060725-6","meetingId":"h18-cm07","date":"2006年7月25日","dateIso":"2006-07-25","committee":"区民委員会","time":"午後１時０３分～午後２時２８分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の「平成１８年度地区総合防災訓練・職員防災訓練について」","agenda":"の「平成１８年度地区総合防災訓練・職員防災訓練について」","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"たぶんなっているんだろうと思うんですけども、その辺の状況というのはどういうふうになっているのか教えていただきたいんですが。","respondent":"久保田防災課長","answer":"したがいまして、それぞれの地域の中での個性といいますか、例えば八潮ですと各学校で実施するという特徴がありますし、内容についても通信訓練とか、それから応急対策等も、特にそういうところもありますし。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"私も大分、何年も前だと思うんですけど、やっぱり八潮のところでは、高層の、八潮に限らず今随分高層化になっているんですけども、高層化の住宅のところで、やっぱり高いところで避難しきれなかった方々の救出を、これは極めて専門的なので是非はいろいろあると思うんですけど、そういう場合の避難訓練だとかということも含めて、通常訓練も非常に結構なんですけど。","respondent":"久保田防災課長","answer":"地区訓練に限らずいろんなそういう訓練の機会もありますので、そういう中でまた地域のそれぞれの課題を生かした訓練を充実させる方向に今現在区のほうもなってあります。","voiceIndex":7,"id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"最後に聞きますけど、そういう地域の特性を生かした訓練内容になっているという説明で、それは当然のことだと思うんですけど、そういうリードというのは区のほうで一定程度この何年かの間にかけて指導といいますか、援助というのかな、そういうのをしてきているということで理解していいんですか。","respondent":"久保田防災課長","answer":"はい、おっしゃるとおりです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"堺委員","kind":"質問","question":"あれは今年の秋から一斉につけるということだったでしょうか。もし、それができるのであれば、せっかくのいいチャンスですから、今回区として、例えば９月３日の大崎第１地区、第一日野小学校であれば、どこでやるかは別として、今回この学校でこういうものができたと、こういうふうに使うんですよというようなご披露を、こういうのが可能なのかどうなのか、その辺も含めてちょっと進捗状況を。","respondent":"久保田防災課長","answer":"できあがりましたら、街づくり特別委員会に報告する予定です。","voiceIndex":11,"id":"exchange-004"},{"speaker":"堺委員","kind":"質問","question":"ですから、例えば、どこかわからないけど、大崎第１地区にＡという幼稚園があったとすれば、Ａという幼稚園で何月何日にこういう訓練をやりますというお知らせを事前に教えてもらって、そこの地区の近くにいる人たちがその訓練にかかわるというんですか、そういう相互の連携というのは、やっぱり常日ごろからやっておかないといけないと思うんですが、その辺、どういう取り組みをしようとしているのか。","respondent":"久保田防災課長","answer":"この場合には、当然ながら地域の町会とか、あるいはＰＴＡを通じて、ＰＴＡも参加するというような形でやっておりますので、そういう機会を活用して、地区の連携を図っていきたいなというふうに思っておりますけども、全部の例えば私立の幼稚園とか、あるいは公立の幼稚園とか。","voiceIndex":13,"id":"exchange-005"},{"speaker":"堺委員","kind":"質問・要望","question":"それが力になっていくわけですから、特にこういう保育園とか幼稚園とか、そういういわゆる災害が起きた場合に、大人の手助けが必要な施設なんかは特にそういうところで何か起きた場合なんかは、どうしたって地域の大人の手は必要になってくるだろう。私は何回か指摘しているが、そういうところはまだ見かけないのでぜひそういうところも同じような形でやっていただきたい。","respondent":"久保田防災課長","answer":"今後連携の充実ということで、いろんな工夫をしていきたいなというふうには思っておりますので、今の趣旨を生かした形で検討していきたいと思います。","voiceIndex":15,"id":"exchange-006"},{"speaker":"南委員","kind":"質問","question":"二十五、六年、もっと前だと思うんですけど、私がまだ保育園の職員だったころ、やっぱり９月１日に総合防災訓練をよくやっていたんですけど、保育園も全部西大井広場公園に集合してという形で、品川区全体だけど、地域で避難所を一時避難場所として、ああいう大きな公園に行くという訓練だったんですけど、その体験で小さい子どもを連れて避難するということが、炎天下の中でちょっと大変な思いがあったので。","respondent":"久保田防災課長","answer":"ただ、なかなかそうは言っても、一気にというわけにはいかないと思いますので、今後も訓練の呼びかけの際に保育園なんかにも呼びかけて、できるだけ多くの方が参加できるような形にしていきたいなというふうに考えております。","voiceIndex":17,"id":"exchange-007"}]},{"id":"topic-02","title":"２番目の涼しさ回復プロジェクト","agenda":"２番目の涼しさ回復プロジェクト","exchanges":[{"speaker":"大沢委員","kind":"確認","question":"裏の２番目の１８カ所の測定ポイントということで書かれておりますけど、測定ポイントを決めるときの基準は何を基準にして１８カ所を決められたのかということと、あと商店街とかの密集しているところでは、先ほど体感温度とおっしゃっていましたけれども、室外機の温度がゆえにヒートアイランドになるんでしょうけども、場所によって室外機の温度でかなり上がっている場所もあろうかと思うんで、そこと。","respondent":"田中環境課長","answer":"２番目のご質問とのところもあるんですが、全く対策をしていないところも比較上、大井町の駅前の広場のところをはかっております。","voiceIndex":23,"id":"exchange-008"},{"speaker":"大沢委員","kind":"質問","question":"もちろんデータをとる上では必要なことだと思いますが、ちなみに私が住んでいる小山の辺はかなり商店も多いので、夏場になると熱がかなりこもって抜けないような状態が非常にあるんですが、商店街のあるところは大体そういう状況というか、環境が似通ったところが多いと思うんですけれども、商店が軒を連ねている場所と、あと住宅地ということで、ここを検証する上において。","respondent":"田中環境課長","answer":"ただ、アーケードの中等は直接ヒートアイランド対策ということで測定ポイントを置いて測定するようにはなっておりませんので、中延ですとか小山の商店街等については日光が当たったりするわけではないので、そこのところは測定ポイントを考える上では考慮に入れなかったです。","voiceIndex":25,"id":"exchange-009"},{"speaker":"大沢委員","kind":"質問","question":"ドライミストの濡れない霧ということなんですけれども、機械の大きさにもよると思うんですけれども、戸越銀座に設置してある機械というのは、どれぐらいの面積で、範囲でミストがかかるようになっているんですか。","respondent":"田中環境課長","answer":"ドライミスト機は発生装置が２本ありまして、それぞれ別の方向に向けて設置してあるんですが、それぞれ３０ｍから４０ｍぐらいドライミストが広がっていくという形になっております。","voiceIndex":27,"id":"exchange-010"},{"speaker":"土井委員","kind":"質問・要望","question":"これがここに書いてある４００万円というのは、公園のところだけだろうなと思えるんですが、それらを含めたものがどうだったのか、そして、それをこれから維持していくのにどのぐらいかかっていくのか、これは今のところ未来ずっと続けてやっていく予定なんですねというのも含めて表現しているんだけど、とりあえず、そこら辺をちょっとお伺いしておきたいというふうに思います。","respondent":"田中環境課長","answer":"今後の運用ですが、検証を単年度だけというわけにはいきませんので、最低２カ年間は稼働させていきます。その後もすぐ壊れる機械ではありませんので、大学側との調整になりますが、できるだけ系統的に運用して、環境教育等を含めて活用していきたいというふうに考えております。","voiceIndex":29,"id":"exchange-011"},{"speaker":"土井委員","kind":"質問・要望","question":"その間にデータがしっかり集まれば、実験的な意味では終わりですから実施をどうするかという話になる、これはまた別な意味ですが、そこがうまく集まるように、またそれを工学院大学とどういう関係になっているのかわかりませんが、学校ですから、すべて公表してくれるだろうというふうに思いますけども、そこら辺、そごのないようにやっておいていただきたいなというふうに思いますし。","respondent":"田中環境課長","answer":"ホームページ上等のそれぞれの建材について、詳しい説明がそれぞれの会社のホームページに飛ぶようになっております。","voiceIndex":31,"id":"exchange-012"},{"speaker":"本田委員","kind":"意見","question":"それは東京２３区のどこも抱えている問題でして、品川区が率先してこの事業を産学協同、そういう特性を生かしながら始まったということで、これは２３区とか、東京都の事業も入ってはおりますけれども、都との関係では今後かなり長くこういう企業を、本当ならば全都的にやって、東京全体をどう涼しくするかと、ヒートアイランドを抑えていくかというようなことが大事なんだと思うんですけれども。","respondent":"田中環境課長","answer":"平成１８年度から行われておりまして、この８月１日からも第２回の屋上緑化と遮熱塗料の公募が始まるということになっております。ということで、全体としていろいろな形を組み合わせながら全都的にヒートアイランド対策を進めていこうということになっております。","voiceIndex":33,"id":"exchange-013"},{"speaker":"本田委員","kind":"質問","question":"財調関係は何か関係しているのかどうかが１点と、それから今回塗料とかいろいろな建材を使って、そのことが非常に効果をあらわしたという場合、今後これをどう普及していくというのか、例えば西品川保育園でこういう塗料を使って、実際どういうすばらしい効果があらわれたということになれば、品川はもちろんですが、かなり多くのところで、保育園だけではなくて。","respondent":"田中環境課長","answer":"ということで、国のクールルーフの今回の補助事業についても、補助を受けた方は５年間測定データを出すというようなことで、その面では確定的に安定した評価が定まっていない段階ですので、もうちょっとその辺のところを見て、今の段階では実験段階ですが。","voiceIndex":35,"id":"exchange-014"},{"speaker":"本田委員","kind":"質問・要望","question":"そういうパイロット的な役割もこのプロジェクトの中には入っているんだなというふうに思いながら説明を聞いたんですけれども、同時に、大変お金のかかる話、これからヒートアイランド対策を本格的にやっていくということになれば、大変お金のかかる話でもあるし、財調に対する算定事業といいますか、そういう要望もぜひ実績といいますか、裏づけを深めながら要望をしていくということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-015"},{"speaker":"南委員","kind":"質問","question":"それと、今いろんな委員から出たように、いろんな形でヒートアイランドの対策をとっていくというのは本当に大事なことだし、品川区が率先していろいろな企業の産学の連携の中で進めているというのは、本当に応援をしたいなというふうに私も思っているんですけれども、そういう点で今は実験段階でこの効果が本当にあるのかどうかを見据えた上で、今後の取り組みをしたいという話で。","respondent":"田中環境課長","answer":"手元に資料がありませんが、ただ実際のところの耐久性ですとか、道路ですので遮熱が本当に、遮熱塗装のほうは効果があるのかどうかというようなところで、所管の管理工事課のほうで検討した上で。","voiceIndex":38,"id":"exchange-016"},{"speaker":"南委員","kind":"確認","question":"ちょっと改めて確認したいんですけど、八潮で行っている実験の結果をもとに今回の商店街の保水性舗装には生かしていきたいと、そういう理解をしていいのかということと、これからの品川区の取り組むこの問題での姿勢については改めて承知いたしましたけれども、ちょっと違う部分で申し訳ないんですけど、例えば、生ごみリサイクルをモデル実施で終わらせちゃったみたいな、そういうところもあるし。","respondent":"田中環境課長","answer":"資料のゆたか商店会の下のところにあります「平成１７年度保水性舗装と遮熱舗装の実証実験を区で行い、効果が実証された」という部分については、八潮での実証実験のことですので。","voiceIndex":40,"id":"exchange-017"}]},{"id":"topic-03","title":"の打ち水大作戦","agenda":"の打ち水大作戦","exchanges":[{"speaker":"南委員","kind":"質問","question":"説明会で出た意見というのは全然なかったんでしょうか。どんな内容のご意見があったのか、ちょっと教えてください。","respondent":"中山資源循環推進課長","answer":"私どもと、あと東京二十三区清掃一部事務組合が来て、清掃工場の説明をやるのを基本のパターンにしておりますが、基本的にはよく理解できたというふうなお声が出ていました。","voiceIndex":50,"id":"exchange-018"},{"speaker":"南委員","kind":"質問","question":"しかし、ちょっと何か理解できたというご意見があったということで、それはそれとして区民のご意見なのだから受けとめなきゃいけないとは思っておりますけども、いわゆる議会でもこの間問題意識として出てきたせっかく分別をしてきたのにという消費者団体の方々からもそういう意見で聞いておりますけども、分別が徹底してきたのに、そこに逆戻りしてしまうんじゃないかみたいな。","respondent":"中山資源循環推進課長","answer":"説明の対象によってということで、例えば今おっしゃったようなそもそもの考え方がどうであるかとか、清掃工場の対応というのはどうなのかというふうなこと、特に最初のころにリサイクル関係の団体の方だとか収集団体の方々にご説明している際には、基本的な質問が出ておりました。","voiceIndex":52,"id":"exchange-019"},{"speaker":"南委員","kind":"意見","question":"中身が変わったり、区民の生活に関連して一部変わったりするときは、ある程度大変かもしれないけども、そういう説明会に出向いて区民の皆さんにわかっていただくという、理解というのかしら、説明をするという、そういうことを本当にこれからも大事にしていただければというふうに思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":54,"id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2464#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":20177,"voices":66}},{"id":"h18-20060725-7","meetingId":"h18-cm07","date":"2006年7月25日","dateIso":"2006-07-25","committee":"厚生委員会","time":"午後１時０４分～午後４時３５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"介護サービス情報の公表ということができた目的、それから具体的にされる時期。講習を受けたことに対しても修得されていることについて確認することが必要だということまで書かれているんですけれども、調査員はどのような形でされてくるのか、介護サービス情報にかわっていくにあたって、どのような形になっていくのかというところを教えていただけないでしょうか。","respondent":"上山介護保険担当課長","answer":"こちらとすれば国の制度と区独自の部分が重複して過度な事業者への負担とならないような形で、今回の制度化された介護サービス情報を活用しながら、区のサービス向上の仕組みを本年度も引き続き検討するというのが今の流れの中です。","voiceIndex":6,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"介護サービス情報の公表は東京都がやるということですけれども、調査員２名というのは区内の調査をすることに対して２名ということになるのか。事業者に年に１回義務づけということになっているので、どのような形で調査に入って調査して、どのような形でいつ頃公表されていくのか、中身も含めて、わかるように説明をお願いできないでしょうか。","respondent":"上山介護保険担当課長","answer":"介護サービス情報の公表ですけれども、まず公表の内容が２点大きく分けてございまして、基本情報と調査の情報になります。基本情報については、基本的な事業所としての運営の情報ですので、そのまま載せることになります。","voiceIndex":8,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今後ともそういうものが必要ではないかということで、区としては定期的に実施する」と書かれているのですが、このことについては品川区として続けるということは大事なことだと思うんですけれども、今までのサービス向上委員会で行っていた施設の自己評価だとかサービス向上委員会として行っていた評価は、介護サービス情報の公表に移していくという形になっていくのでしょうか。","respondent":"上山介護保険担当課長","answer":"こちらでつかんでいるところですと、報告の期限が平成１８年１２月ぐらいで、調査の予定月が報告を受けた後の１カ月後ぐらいで、公表の予定月とすれば平成１９年３月と聞いているところです。","voiceIndex":10,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう一つ、先ほどもご説明をいただきましたけれども、４ページでサービス評価結果をサービス向上へ結びつける仕組みということで、サービス向上委員会がずっとやられてきたと思うんですけれども、私もいろいろな施設にお伺いしてお話をお伺いするにつけ、本当に現場の皆さんは頑張っているなという感じがするんです。","respondent":"上山介護保険担当課長、木下福祉高齢事業部長","answer":"介護サービス情報の公表の目的ですけれども、先ほども触れましたけれども、介護保険の利用をするにあたりまして、被保険者あるいは利用者がよりよいサービスあるいは事業所等を比較検討しながら。区内の法人については、そのことについての認識はあると理解しています。","voiceIndex":12,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう視点で、事業者の方々が最大限努力されているのではないか。現場の努力だけではどうにもならないという状況があるのではないかと思いますので、ぜひ現場の実態が一番よくわかる自治体ということで、その辺のところを国に対して言っていただいて、改善というところに一緒に持っていっていただけたらと、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-005"},{"speaker":"西本委員","kind":"質問・要望","question":"「サービス」という言葉が出てきますが、「サービス」というのはどういう定義を持ってサービスの向上と言っているのか確認させていただきたいと思います。１２ページに在宅サービスを中心にと書いてありますが、在宅ということになると、調査の中身がどこまで広がる形になるのか、本人しか入らないのか、もしくは本人を含めた周りの環境の調査も入るのか、その辺を教えていただきたいと思います。","respondent":"上山介護保険担当課長","answer":"調査は家族まで含めるのかですけれども、３ページをお開きいただきたいと思います。若干説明を省略させていただいたところがありますので、仕組みの考え方で四つほど掲げてあります。","voiceIndex":16,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"１８ページに、「利用者の言うなりにサービス提供することが良い評価なのか疑問を感じる」ということがあります。逆に、あれもやってほしい、これもやってほしい、家族がいるのにやらなければいけないという、在宅サービスもいろいろな意味合いがあると思うんです。そこまで考えた中で、どういうことがサービスなのかということは、きちんと品川区の考えがあるのかどうか、その辺をお聞きしたいと思います。","respondent":"西島障害者福祉課長","answer":"二つ目は、自らの努力だけでは自立した生活を維持できない場合、社会連携の考えに立った支援が必要です。三つ目が、個人が人として尊厳を持って家庭や地域の中でその人らしい自立した生活を送れるようにしましょう。これが三つの理念です。","voiceIndex":18,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問","question":"よくわかりました。１８ページに一部の意見の中にも、何かその辺が統一されていない中で、サービスが前面に出てきてしまっているということが見えているような気がしますので、その辺を今後品川区としてはどのように進めていかれるのか、最後にお聞きしたいと思います。","respondent":"木下福祉高齢事業部長","answer":"訪問入浴介護について言いますと、最近は安定してきて利用者側の理解も進んできていると思うわけですが、ホームヘルプについて言いますと、やはり家政婦をお願いしていた時代のイメージが結構ありまして、報告書の中にも出ておりますけれども。","voiceIndex":20,"id":"exchange-008"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"１３ページに品川区標準の見直しの終りのほうに、「入所施設および障害者通所施設のサービスについても、サービス運営の指針や目標となるような施設版品川区標準を作成する方向で」と書いてあるので、現状はどのような問題点があって、どの部分が改善されて盛り込まれていくのかお聞かせいただきたいと思います。","respondent":"西島障害者福祉課長","answer":"平成１６年度、１７年度にセルフチェックを行いまして、セルフチェックの内容について、再度見直しをかけて、施設におけるサービスについてはどのようにしたらいいのかということをやってきたところですが、ホームヘルプと違いまして標準というものがございませんので。","voiceIndex":22,"id":"exchange-009"},{"speaker":"飯沼副委員長","kind":"質問","question":"介護サービス情報の公表には、障害者のところまでは公表が至っていないというところでは、品川区内の施設サービス向上委員会の役割という意味で、引き続き同じような状況で公表されるということなのでしょうか。","respondent":"西島障害者福祉課長","answer":"必要な情報につきましては、情報というのは本来対称性のあるものですけれども、どうしてもこういうサービスというのは非対称性がございまして、実施している側、それから利用する側というのは、必ずしも受ける情報はイコールではないということもあります。","voiceIndex":24,"id":"exchange-010"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"三村委員","kind":"質問","question":"私の周辺でよく聞く話だと、受けに行こうと思ったけれども、偶数月だとか奇数月の関係で受けられなかったとか、誕生日の関係で受けられなかったという話を、ここのところよく聞くのですけれども、なかなか受けにくい仕組みもあるのではないかと思うんですけれども、その辺のところについてお伺いできますか。","respondent":"倉橋品川区保健所保健サービス課長","answer":"一つは、受診間隔として２年に１回という形で、検診方法が変更されたということ。それからもう一つは、乳がんのマンモグラフィーに代表されるように、精度の高い検診を行おうという、二つの動きがございました。","voiceIndex":31,"id":"exchange-011"},{"speaker":"三村委員","kind":"質問・要望","question":"２年に１回という間隔についてですけれども、２年に１回に変わった理由とか背景とか、その辺について教えていただきたいと思います。","respondent":"倉橋品川区保健所保健サービス課長","answer":"毎年受けましょうという基本検診がありますので、それにあわせて１年に一度ということで始まったわけですが、早期がんから進行がんになるまでには何年かかかるということが、最近の医学的見地からわかってまいりました関係で。","voiceIndex":33,"id":"exchange-012"},{"speaker":"三村委員","kind":"質問","question":"その傾向というのは、詳しく年齢別だとか大くくりの平均値ということですか。高齢者になればなるほどがんの進行がゆっくりになっていくから２年に一度で大丈夫でも、若い人が２年に一度だと、その間にすごく進行してしまうのではないかという印象を受けるのですけれども、その辺についてはどうですか。","respondent":"倉橋品川区保健所保健サービス課長","answer":"今言っているのはがんと診断されるかされないかという、がんのできたてのときにどうやって見つけるか、早期がんのときに見つけるのか、進行がんのときに見つけるのかという話になりますと、そこの期間は年齢が若い段階でも、ある程度年齢が行った方でも。","voiceIndex":35,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"その後、２５歳以上の乳がん検診から、平成１６年度から４０歳からと年齢が上がりました。今年から３４歳からということになったのでしょうか。そういうところでは、年齢をもっと低い段階から検診を受けられるようにしてほしいという希望を言われたのですけれども、その辺の年齢の変更をされた背景、また今回下げられた背景、そこのところについて教えていただけないでしょうか。","respondent":"倉橋品川区保健所保健サービス課長","answer":"今回、３４歳からというふうに引き下げておりますけれども、今後成果をよく検討いたしまして、今後さらに若い世代の検診を実施すべきかどうか検討していくべきだと考えております。","voiceIndex":37,"id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"若い方は発症すると早いですから、命にもかかわる問題で、前は２５歳以上ということでされていたので、今回若干下げたということでは評価できる問題だと思うんですが、さらに年齢を下げて、多くの方が受けられるような検討をぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-015"},{"speaker":"三村委員","kind":"質問・要望","question":"古いデータですけれども、以前のデータを見ると、３０歳代の女性でも死亡原因の１位ががんですので、先ほど鈴木（ひ）委員から出ていましたけれども、ぜひがん検診の年齢の引き下げなども検討してほしいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-016"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"生活習慣病とはというところで、不適切な食生活、運動不足、喫煙などで起こる病気と書いてあります。成人病が生活習慣病と名前が変わってきた経緯と、不健康な生活習慣をしたため生活習慣病になるという、この辺の定義ですか。国を挙げて健康増進法とか取り組んでいますけれども、増加しているという、その辺をどう見て今後の対策をされていくのか、大きなところでお聞かせいただきたいと思います。","respondent":"川口品川区保健センター保健サービス課長","answer":"そのような反省のもとに、今回一つの疾病だけではなくて、幾つかの疾病を加味したものがメタボリックシンドロームが出てきたわけですけれども、生活習慣病に関しては、今後国もそうですけれども。","voiceIndex":42,"id":"exchange-017"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"品川区は区民健診でわかるということですけれども、実際に区民健診を受けてデータが出た段階で、注意を喚起するような手立てはどのように取られているのか、具体的に教えていただきたいと思います。","respondent":"川口品川区保健センター保健サービス課長","answer":"あわせて糖尿病が重篤な疾病だということから、保健所・保健センターでは今年度は糖尿病に的を絞って個別の健康教育ということで、もちろん医療につながる人は除きますけれども、ある程度の高血糖の方を対象として個別に健康教育というか、栄養指導を行ってあります。","voiceIndex":44,"id":"exchange-018"},{"speaker":"飯沼副委員長","kind":"質問","question":"保健所で健診を受けて、指導を受けていらっしゃる方は安心と思うんですけれども、概要の１２０ページを見ましたら、４０歳以上の区民で勤務先等で受診機会のない者と書いてありますけれども、勤務先で受診していない方は把握されているのか、その辺の方たちは全然把握されていないのでしょうか。","respondent":"谷田部健康課長","answer":"私どもは数値の上では把握していますが、実際に職場でやる健康診断を受けているか受けていないかというのは、私どもは対象としてつかんでございませんので、それについては数字の把握はできません。","voiceIndex":46,"id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは全国レベルのものかと思うんですけれども、品川区としては代表目標項目を決めて、それを具体的に減少させるために、また増加させるためにどのように具体化していくかという計画がどこかに出されているのでしょうか、データも含めて、その辺のところが出されているかどうか教えていただきたいと思います。","respondent":"谷田部健康課長","answer":"それと長期計画を持ってありますので、当然、毎年度実施計画をローリングする過程の中で、効果的な施策を展開していくということをあわせてやっているです。","voiceIndex":48,"id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"国の段階では目標数値を持っているということであるにも係わらず、なぜ品川区ではその辺のところを持たないかということ。それから、私も「区民健康づくりプラン品川」を持ってきているのですけれども、具体的に二次予防、循環器病、健康診断を受ける人の増加というところでは、どの辺に書いてあるか教えていただけたらと思います。","respondent":"谷田部健康課長","answer":"２点目の質問の意味がわからなかったので、もう一度質問をしていただければと思うんですが。","voiceIndex":50,"id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"「区民健康づくりプラン品川」の中で、これを具体化しているというお話だったと思うんですけれども、隅から隅までよく見ていないのでよくわからなかったのですけれども、例えば二次予防の循環器病の健康診断を受ける人の増加のために、具体的にどのようなことを計画しているかというところでは、具体的に具体化されているか教えていただけたらということです。","respondent":"谷田部健康課長","answer":"あくまでも、健康増進法に基づく区の健康増進計画ですので、このプランに従ってさまざまな具体的な施策を、予算ですとか実施計画の中で具体化しているです。","voiceIndex":52,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区はいろいろな生活習慣を適正にするためのさまざまな指導の問題ですとか、対策を取られているということは評価しますし、ますますそのようなところは充実をさせていただきたいと思うんです。子どもと食事ができない。それは品川区がどうのこうのという中で、単純に解決できるものはないですけれども、そのような背景に関しては、どのようにとらえていますでしょうか。","respondent":"谷田部健康課長","answer":"委員がご質問されている点につきましては、雇用政策ですとか労働政策ですとか、国または都道府県の担うべき分野だと思ってありますので、区としてできることというのは、やはり決められた法律や条例、それから限られた予算の中で、より効果的、効率的にやっていくということで。","voiceIndex":54,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"早期治療をしていく。事務事業概要の１２０ページに生活習慣改善指導事業が書かれていて、これは何年か前に新たにできた施策だと思うんですけれども、健診で病気が発見されたときに、しっかり指導を受けて中断をさせないで、その後も継続した治療が大事になると思うんですが、今の事業についてはどのような実態になっているのかお聞かせいただきたいと思います。","respondent":"谷田部健康課長","answer":"この事業を進めるにあたって、なかなか利用しづらいという意見を聞いてあります。この事業とこれから平成２０年度の医療制度改革に向けて、保険者が行う特定健診、特定保健指導との関係が出てまいりますので、現在の健診と保健指導を含めた組み立て直しの検討が始まった段階です。","voiceIndex":56,"id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私もこの事業については、意義としては大事な分野ではないかと思うんです。区民健診についても、今度の医療改革の中で大きく変わっていくわけです。その辺のことについて方向が出されたときには、ご説明をいただけたらと思いますけれども、どうでしょうか。","respondent":"谷田部健康課長","answer":"そうすると、所管委員会は区民委員会になりますので、保険者として考えれば区民委員会所管、区民の健康全般を考えれば厚生委員会ということもありますので、両委員会の委員長ともご相談をさせていただきながら、どのような形で議会に報告できるかどうか検討をさせていただいて。","voiceIndex":58,"id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"質問","question":"事務事業概要の１３７ページの健康学習に関してですけれども、数多くやっていただいている中で、例えば高脂血症予防教室はなくなったのですか。区民健診の中ですと、平成１７年は６,４０９人、これは大体行きたくないというのが基本的にある中で、こういう教室をつくっていくのは大変だということは十分承知していますけれども、これからどのように考えていくのか、その考え方だけ。","respondent":"川口品川区保健センター保健サービス課長","answer":"１点目の高脂血症予防教室ですけれども、ただいまご指摘のように平成１６年から実施してございません。","voiceIndex":60,"id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"意見","question":"行けばいいだろうけれども行かないというのが現状でしょうし、健康センターに行っても、時間をつくっていけばいいのでしょうけれども、なかなかそういうところに行かないのが現実で、何か理由をつくって行かないという状況があると思うので、その辺はこれから場をつくって啓発していく形をお願いしたいと思います。","respondent":"川口品川区保健センター保健サービス課長","answer":"ただいまの介護保健法との絡みですけれども、今年度から６５歳以上の骨粗鬆症予防教室は高齢事業課の事業ということで、区としてはすみわけをさせていただいてありますけれども、一部保健センターに執行委任ということで今年度実行しています。","voiceIndex":62,"id":"exchange-027"},{"speaker":"西本委員","kind":"意見","question":"今、いろいろ教室があるというお話を聞いたのですが、その中で例えばがんになったときに、治療代として幾らぐらいかかりますとか、危機感を持たせるために、あまりやり過ぎると脅迫的なやり方になってしまうかもしれないですが、こういう病気になると家庭がこうなってしまうとか、後遺症が残るから早期発見が必要だというようなリーフレットなどをつくったことがありますか。","respondent":"倉橋品川区保健所保健サービス課長","answer":"最近は、「健康日本２１」とか、「プラン２１品川」もそうですけれども、より積極的な健康を目指すという形での健康教育が多いので、確かにわかりやすいですけれども、あまりマイナスの面を出すという形のものは数が少なくなっております。","voiceIndex":64,"id":"exchange-028"},{"speaker":"西本委員","kind":"意見","question":"それを見ていると、やはり大変だな、病気になっては困るし、今の生活は健康があってのことだろうと感じます。そのような方法も一つ考えていくのもいいのではないかというのは私の意見ですが、もう少し自己管理をしなければいけない、自分がしっかりしていないと家庭が壊れてしまうという中から、やはり２年に１回か２回は自分で健康管理してみようというものができたらいいと感じました。申し上げておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":66,"id":"exchange-029"},{"speaker":"三村委員","kind":"質問・要望","question":"子どもを通して保護者の健康にも結びつくかと思うので、どういった自治体でどのような結果が出たのか、それから所管がまたがるかもしれないので連携ができるかどうかわからないですけれども、もし連携ができるようでしたら、ぜひ検討していただきたいと思うんですけれども。","respondent":"谷田部健康課長","answer":"今、委員ご提案の携帯電話で自分の家の食事を撮って、それが栄養的にバランスはどうなのか、携帯電話で撮った写真だけで分析できるかどうかわかりませんけれども、そういったことも食が健康にいかに大事かという一つのきっかけになるとすれば。","voiceIndex":67,"id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"要綱もできているということなので、ぜひ区独自策、通所の場合は３,０００円とか、ヘルパーの３％を拡大するとかできましたけれども、その制度について委員会に報告を次回でもしていただけたらということで希望させていただきたいと思います。","respondent":"木下福祉高齢事業部長","answer":"その内容が基本的に現在の品川独自策のすべてになりますので、それでご理解をいただければと考えています。","voiceIndex":71,"id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3152#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":34681,"voices":75}},{"id":"h18-20060725-8","meetingId":"h18-cm07","date":"2006年7月25日","dateIso":"2006-07-25","committee":"建設委員会","time":"午後１時０３分～午後５時１４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を68件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成１８年請願第１１号、「（仮称）中延６丁目新築工事」建設に関する請願","agenda":"平成１８年請願第１１号、「（仮称）中延６丁目新築工事」建設に関する請願","exchanges":[{"speaker":"井上委員","kind":"質問","question":"この請願事項に対しての区の考え方はお聞きしたわけですが、この内容にあるところの中段なんですが、解体工事協定の話し合いの途中で解体を強行というようなところにおいて、結構この施設は大きいところですから、東京都との調整なんかをしていて、区はこの辺ではかかわられているのかどうか。","respondent":"齋藤住宅課長","answer":"説明が足りなくて申しわけございません。今回は、開発審査会、開発行為に対する不服申し立ては東京都の所管とみなして、東京都の開発審査会で２回ほど法律上の手続に基づくあっ旋の場を持ちました。","voiceIndex":11,"id":"exchange-001"},{"speaker":"井上委員","kind":"質問","question":"その後、今、視察をした中で、住民の方たちと工事協定を結んでから進めるということで、今、とめていらっしゃるわけですけれども、ここのところで、区界であるという道路評価なのか、基本的に私たちがあのマイクロで行っても、工事が本当にできるのでしょうかという、ぎりぎり通る、ここでもありましたけれども、キャタピラーという機種を入れるために２時間、３時間の時間がかかるというのでは。","respondent":"齋藤住宅課長","answer":"基本的には、道路の管理につきましては警察署所管となります。こういうマンションにこういう重機を入れることについては、本件では大田区の池上警察署に申請をして、それで時間、条件づけされて許可をされる、こういうことです。","voiceIndex":13,"id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"だから、そのことに対して品川区としてはどういうふうに考えていらっしゃるんですか。","respondent":"岩田まちづくり事業部次長","answer":"きょう視察で通っていただいた道路は、ちょうど道路中心線が区界になっています。ただ、道路法の規定によりまして、ここは道路管理者の権限は大田区が道路管理者になっておりますので、大田区と池上署、交通警察のほうとで許可をおろしたというふうに我々は聞いております。","voiceIndex":15,"id":"exchange-003"},{"speaker":"井上委員","kind":"意見","question":"許可をおろすとか、そういうことはそうだと思うんですけれども、そうじゃなくて、そこを品川区の方々も利用されている道路であって、そういう区民の方たちの生活に及ぼす影響を品川区としてその工事を着工するに当たっては相当な影響を受けるわけですけれども、そういうところは大田区の池上署と大田区であるという縦割りというか、自分たちの権限が及ぶところではないということではなくて。","respondent":"岩田まちづくり事業部次長","answer":"ここをはっきりしていかないとごちゃごちゃになってしまうんですが、諸官庁というのはそれぞれの権限が法律及びその他の政令等で定められておりますから、その権限がない者が権限のある者に対して口を挟むということは、これは基本的にできません。","voiceIndex":17,"id":"exchange-004"},{"speaker":"井上委員","kind":"質問","question":"また後にしたいと思うんですが、このことについてこういう道路のところで工事をするというときには、事業者のほうが事前にいろいろな状況で相談を行政にすると思うんですけれども、こういう道路を使ってこういう工事ができるのかとか、こういう計画を出すに当たって、今まで建設委員会でマンション紛争、随分かかわってきた中で。","respondent":"岩田まちづくり事業部次長","answer":"そうしないと工事ができませんから。ただし、それには通過交通や、あるいは歩行者への影響が最も小さくなるように、そういう配慮が当然必要となってまいります。","voiceIndex":19,"id":"exchange-005"},{"speaker":"本多委員","kind":"質問・要望","question":"建築主のところでちょっと確認したいんですけれども、この物件、東京建物株式会社と中延開発特定目的会社というところで建築主が２者ということなんですけれども、この特定目的会社については、先ほど制度の説明があったのでおおむねわかったんですけれども、こういう場合の紛争予防に関する説明責任というのは、両者にあるとは思うんですけれども、その辺の仕切りといいますか。","respondent":"齋藤住宅課長","answer":"中延開発特定目的会社のペーパーカンパニーについて実態はありません。要するに、東京建物株式会社が出資会社になっておりますので、事実上も１社です。","voiceIndex":21,"id":"exchange-006"},{"speaker":"本多委員","kind":"質問・要望","question":"ペーパーカンパニーということですから、東京建物のほうが説明をされてきたんだと思うんですけれども、風環境の調査のところで、それぞれ調査の内容が記載されていて、結果も出ているところなんですけれども、この請願の主旨は、やはり風害ですとか、そういう不安があるというところで、この不安の要素については十分理解できるんですが、このさまざまな日照から、風害から。","respondent":"齋藤住宅課長","answer":"風の問題については、何度か住民説明会で説明があったというふうに聞いております。このデータも説明しております。","voiceIndex":23,"id":"exchange-007"},{"speaker":"本多委員","kind":"質問・要望","question":"説明会を何度かされたようですから、それと区役所でのその他の協議等されていて、当然その辺の一番の、環境問題が一番メーンになっておりますので、当然やりとりはあったと思うんですけれども、やはりこの辺の環境調査のこともしっかりと説明をしていかなければいけないと思いますので、区としてどこまで把握しているのかというのを確認をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-008"},{"speaker":"松澤委員","kind":"質問","question":"よく大きな建物の再開発手法なんかですと、容積率の緩和とか、補助金を受けるとかということがありますけれども、それは１つの会社、１社ですから、こういう容積率の緩和とか、区とか都による補助金等々は一切受けていないということでよろしいのでしょうか。","respondent":"片田建築課長、齋藤住宅課長","answer":"その場合は、当然、建築審査会等で地域住民への事前の説明を含めて、許可ですから、法を超えた上でのそれに見合った地域環境を改善できるという程度のことを含めて東京都が許可しているものですけれども、今回の計画については。補助金のほうもないというふうに聞いております。","voiceIndex":27,"id":"exchange-009"},{"speaker":"松澤委員","kind":"意見","question":"この建物が計画されてから相当月日がたっているということと、東京都のほうにあっ旋も含めていろいろなことをやり、あっ旋も不調があり、それでなおかつ区に請願が来た、ちょっと異質なんですね。冬至の時の建物を見ても、既存建物よりも悪くないという説明を受けましたし、どうも私どもの会派から２人の紹介議員が出ていますから、いろいろ困っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":34,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほどの説明中で、道路のことについて、品川区としても周辺の方の理解を得るようにとありましたけれども、現地での説明の中で、重機が入るときに手続上の不備があったという話がありましたけれども、先ほどのお話で６月１０日と１１日にキャタピラー搬入があったというお話でしたけれども、どういう不備があったのか、言い方を変えれば、どういう違法行為がそこであったのかご説明いただいたのと、あわせて。","respondent":"齋藤住宅課長","answer":"平成１７年度に池上署が交付をした許可証そのものを持っていなかったというふうに聞いております。その許可証を持っていなかったことについて区として指導申し上げることはありません。","voiceIndex":35,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問","question":"しかも、住民との話し合いというか、紛争が続いているにもかかわらず、こうやって許可証すら持たずにキャタピラーを搬入するという行為は、私は絶対許されるべきことではないと思うので、この案件ではなくしても、許可証を持たずに工事を入れるという行為に対しては、区はどういうふうに対応するのでしょうか。","respondent":"齋藤住宅課長","answer":"先ほど次長も申し上げましたが、警察の権限でございまして、区としては何か物を申したり、直接言うようなこと、命令するような権限はございません。","voiceIndex":37,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"警察の範疇という話ですけれども、でも、非常に悪質な業者だなと思うんですよね。それともう１つ、風害のことを資料で説明があったんですけれども、ちょっとわからなかったんですけれども、５ページ目の評価結果のこのシミュレーションの結果、色分けの結果ですけれども、この濃い緑のランク３というのは、どのぐらいの風の強さを指すのでしょうか。","respondent":"齋藤住宅課長","answer":"簡単に言いますと、ランク３というのは、五反田や大崎の事務所街と同じような場面がここに出現するということです。","voiceIndex":39,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"このグラフを見ていると、明らかに左から右にランク３の部分が大きくなっているように見えますよね。それに対して区はどのように考えているのか伺いたいんです。僕が言いたいのは、それに対して先ほど受忍限度だと、超えていないという話がありましたけれども、とても今までない風が吹くということをこれは示しているのではないのかと思うんですけれども、その点はいかがでしょうか。","respondent":"齋藤住宅課長","answer":"この表自体、大変わかりにくいので恐縮なんですけれども、ランク３というのは五反田や大崎。","voiceIndex":41,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"ですから困るんだというのがこの請願の中身だと思うんですね。最後に、日照のことを伺いたいんですけれども、先ほどのお話ですけれども、ちょっとご説明を補足いただければ、特段悪くなるわけではないというお話があったかと思うんですけれども、それは面積で見たんですか。日陰で見たんですか。どこからどういうふうな、数値の説明があれば教えていただきたいと思うんです。","respondent":"齋藤住宅課長","answer":"左から８時、この青い線が前の工場があったときの影になります。これは冬至です。春分と秋分は影は立ちません。冬至です。９時が破線の赤で、１０時が赤の線、１１時がグリーン、１２時が水色、１３時が青、右のほうにあります、１４時がオレンジ、１５時が赤、１６時が緑。","voiceIndex":43,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"まとめますけれども、支障がないというのは区の評価であって、実際、日陰の状態が、簡単に言えば、８から１０になれば光が増えるとか、８から７になる、その辺がよく根拠として説明の根拠がわからないので、その辺を教えていただきたいのと、請願にも書かれていますけれども、「寝たきりの母にとってお日様がどれほど嬉しいか。太陽の光やぬくもりが生きている実感を感じるときになると思うんですよね。","respondent":"齋藤住宅課長、片田建築課長","answer":"ちょっとこれも難しいんですけれども、直射日光が入らない時間は８時と１６時の時間に若干増えます。それは８時の面で言うと、地下１階から３階部分で２部屋分ぐらい。ただ、道路がなくて直接的に隣地に接する場合には、その隣地の境界線から５メートル、１０メートル、それが基本的な法規制の中で十分クリアするという状況で今認識しております。","voiceIndex":45,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"これで終わりにします。そこだと思うんですよね。もちろん法的にクリアしていることは百も承知です。しかし、ここの施設がどういう性質のものかとか、太陽に当たって生きているんだなという実感を感じられる、そこをどう理解しているのか、そこだけちょっと教えていただきたい。ただ、そこに暮らしている人の気持ちを、利用者の気持ちをどう理解しているのか、そこだけ最後に聞かせていただきたいんです。","respondent":"岩田まちづくり事業部次長","answer":"この請願を出された地域の方のお気持ちというのは、区の施設に入居されておられる方々への非常に深い配慮をいただいた上でのこういった請願だととらえておりますので、非常にそれはありがたい、温かいご支援だとは思っております。","voiceIndex":48,"id":"exchange-017"},{"speaker":"宮崎委員","kind":"確認","question":"通常いろいろ工事が始まる前は、近隣の家庭のところにいろいろ調査して現状をしっかり把握していくということをしているんだと思うんですけれども、この場合どうだったのかということを確認したいんです。","respondent":"齋藤住宅課長","answer":"それで、本来であれば家屋調査を行って、その上で工事をするんですが、事業者のほうが工事を焦ったか性急に進めてしまいまして、因果関係を証明できないから、一々そんなことに取り合わないような趣旨のことを言ったと、これで信頼関係が損なわれたのは事実です。","voiceIndex":51,"id":"exchange-018"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっとやっぱり工事を始めるときのいわゆる常識ですか、ちょっとないかなという感じがするんですけれども。ちょっと、私も風のほうで聞きたいんですけれども、今、風のところを聞いていてもよくわからないんですけれども、結局、この資料で行くと、実際例えばこういうところは風がどのくらい吹くのかというのがよくわからないんです。","respondent":"齋藤住宅課長","answer":"１２階のビルが建ったがために、例えば大井町にイトーヨーカドーがありますけれども、あれができたがために風害があったとか、風で人が転んだとはございませんで、この風評価というのは、考えがそういう、先生ご指摘になったような視点で判断するものではないので。","voiceIndex":53,"id":"exchange-019"},{"speaker":"宮崎委員","kind":"質問","question":"例えば、じゃあ、そうすると、3)のところの資料で、ビューフォート風力階級表というやつで、人体に与える影響というのがありますけれども、「かさがさしにくい」とか、「普通に歩くことが難しい」とか、「前進をさまたげる」とかとなっていますけれども、これは普通、もしかしたら成人の男性ぐらいのことではないかと思うんですけれども、やっぱり例えばお年寄りだと、すごく風なんかが来ると。","respondent":"岩田まちづくり事業部次長","answer":"先ほどから問題になっているランク３というのが一体体感でどれぐらいかというんですけれども、これは一般的に頻度の問題を問題にしておりますので、これ、一番最初の尺度という表、だから、強い風が１０メートル、１５メートル、２０メートル、それぞれの出現度。","voiceIndex":55,"id":"exchange-020"},{"speaker":"宮崎委員","kind":"質問・要望","question":"私から見るとちょっとよくわからないんですけれども、大成建設のほうで出してもらっている、大成建設と、これを実際に建築主は東京建物なので、そこの関係がしっかりここにないと、何だかシミュレーションというのはどういう位置にあるのかなと、どういう関係にあるのかよくわからないと困るんですけれども、少なくとも建築主のほうは、これを建てたら、それを販売して。","respondent":"齋藤住宅課長","answer":"説明会でのご質問で、風についての住民の方のご不安がありましたので、東京建物が日本で権威のある大成建設のエコロジー本部に風環境に関する調査を依頼したということです。","voiceIndex":57,"id":"exchange-021"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そこなんですよね、やっぱり。要するに、住民の側の一番の心配はそこなんですよ。せっかくそういう要望にこたえたんだったら、そこまでやっぱりしっかりかみ合った資料じゃないと話にならないんじゃないかと私は思うんです。","respondent":"岩田まちづくり事業部次長","answer":"住民の方もそこのところを一番問題にされておりまして、法定再開発でやったところであれば、組合は形成しますけれども、新たに入居される方々で管理組合をつくりますので、そういった事後対策というのを管理組合で引き継いで対応されているようですから。","voiceIndex":59,"id":"exchange-022"},{"speaker":"宮崎委員","kind":"質問・要望","question":"だから、やっぱりこういうふうにマイナス点をつけた以上は、それを取り返すというのはどういうことかということは、お互いに歩み寄れというふうに言っていても、それは歩み寄れないのは、もうこれは住民感情としては当然ですから、こういうみそをつけてしまった、マイナス点をつけてしまったとなったら、それ以上の努力を東京建物がしないと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-023"},{"speaker":"藤田委員","kind":"質問","question":"常に地域住民の人たちは、車との危険、それに非常に神経をとがらせている。ですから、区もやっぱりこの建物については神経を、所管がこれは福祉のほうになるわけですね。ですから、その辺のところをよく連携を取り合って、区も地域住民の１人なんだということで、やっぱり話し合いにきちんと応じる必要性があるのではないかなと私は思います。","respondent":"齋藤住宅課長","answer":"工事協定が整えば、重機を搬入して、山留め、土留めの工事をして、それからだんだん上げていって、２年８カ月ぐらいで上げたいというふうな意向を持っておりました。","voiceIndex":62,"id":"exchange-024"},{"speaker":"藤田委員","kind":"質問","question":"やっぱり先ほど言いましたけれども、相当な車が、このマンション建設に携わるそういった車が入ってくるわけですから、非常に住民の皆さんに不安がある。この行政指導をしていくというふうに一番最初にありましたけれども、これは現時点では、区としてはどのような対応をされているんですか。","respondent":"齋藤住宅課長","answer":"特にこちらのところは風害対策ということで木をなるべく多めに、高さの上限がありますので、いろいろ考えながら、今のお話をしていきたいと考えています。","voiceIndex":64,"id":"exchange-025"},{"speaker":"藤田委員","kind":"質問・要望","question":"この請願項目については、十分区としても受けとめていただいて、そして今言いましたように、風害対策というのは非常に大事な問題でもありますから、実際にどのような風害があるのか僕は知りませんけれども、これはどういう対策をとればいいのか、大体木がいいんだ、植林がいいんだというような現時点の判断ですので、ぜひその辺も含めて対応していただきたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-026"},{"speaker":"大西副委員長","kind":"質問","question":"それと、先ほどの緑地のご説明がありましたが、随分この緑地部分を増やすということは品川区の望むところであろうかと考えますが、この部分だと、ちょっと中ほどに黄土色の部分があろうかと思うんですけれども、こういった部分、黄土色並びに緑地部分というのは、これは公開空地として公開され、この高齢者施設の方々が車いす等で行って日向ぼっこをしてとか。","respondent":"齋藤住宅課長","answer":"そこは自由に立ち入ることができます。中の緑地は基本的には敷地内ですので、マンションが建った後、開放するということならあれですけれども、中は敷地内ですので、こっちの緑地のところは入れません。ただ、連関しておりますので、オープンスペースになっているということです。","voiceIndex":67,"id":"exchange-027"},{"speaker":"大西副委員長","kind":"質問・要望","question":"要するに、先ほど次長が言っていた歩み寄りという点の双方の意識、事業者としては住民の方々のためにこういうふうにしたい、そして住民の方々にこういう不安点はこういう部分であるということの理解を求めるためのこういう説明というのは、先ほどから言われている風害ということと、日照という問題についてのことは、随分ここでは改善され。","respondent":"齋藤住宅課長","answer":"説明会が何回かありますので、この資料で事業主は説明をした、こういうふうに考えておりますが、住民の方にとってみると、説明が難しいのと、これまでの信頼関係がなかなか醸成されていなかったということがございまして、こういう説明をしたんだけれども不十分だと。","voiceIndex":69,"id":"exchange-028"},{"speaker":"大西副委員長","kind":"質問・要望","question":"その部分を行政としても、これはどちらのサイドと、私は品川区ですから品川区住民の安全、財産、そういったものを守るのは大前提だろうかと思いますが、公平な立場でのアドバイスなり、それから説明なりをし、住民がもし必要以上に不安を感じている部分があるとすれば、その部分をよりわかりやすく説明して、あるのかないのかということを客観的に説明していただいて、両者がよく理解されて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-029"},{"speaker":"井上委員","kind":"確認","question":"済みません、ちょっともう１つ。先ほど確認申請を出し直してほしいということで確認審査請求が出されていて、第１回までが終わっていると聞いているということで、開発許可に関連してというようなことをおっしゃっていたんですが、審査会が行われている状況と、工事というのは、これは継続している間に工事というのは進んでしまうものなんでしょうか。","respondent":"齋藤住宅課長","answer":"建築確認の申請を取り消す審査請求があったとしてもとまりません。やめようとすると、裁判所に仮処分か何かをして認められない限りは工事をとめる権能はありません。","voiceIndex":72,"id":"exchange-030"},{"speaker":"井上委員","kind":"質問","question":"建築審査会が進んでいるときに訴訟にはできないんですか。これが続いている間はできないので、これが継続していたら、とめるために裁判ということは、これを取り下げかなんかをしない限りできないということですか。","respondent":"片田建築課長","answer":"今、住宅課長が申し上げましたように、建築審査会から訴訟に持ち上げるためには、通常、前置主義という言葉を使っておりますけれども、行政訴訟のためには審査会の判断を受けてからでなければ行政訴訟をすることはできないと。","voiceIndex":74,"id":"exchange-031"},{"speaker":"松澤委員","kind":"質問","question":"さらに１点お聞きしたいんですけれども、不調に終わったあっ旋の中で、１階を削るという話がありまして、それは当然、日影にかかるもののところを削るという解釈でよろしいんですか。","respondent":"齋藤住宅課長","answer":"６階にしてしまうと事業採算が整わないので、下げられるぎりぎりのところを下げてみせたというのが事業者の提案です。ですから、日影とかではなくて、住民の要望による最低限の対応、そういうものが事業者の立場だったので、住民の方も納得がいかなかった、こういうことです。","voiceIndex":77,"id":"exchange-032"},{"speaker":"松澤委員","kind":"質問","question":"１階削るなら一番日影が当たるこちらの低層のところの角を削れば、日影が改善されるかなというふうに私は理解したんですけれども、結論としては、まだまだ業者側のほうでも解体工事の補修が済んでから工事協定を結んでから重機を搬入したいという話を伺っていますし、そんなことを勘案すると、私は１回見送ってもいいのかな、結論を出さなくても継続でいいのかなという気がしているんですけれどもね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-033"},{"speaker":"藤田委員","kind":"意見","question":"私も、今、住民の皆さんと業者の方との中に話し合ってというのがいいのかどうかわかりませんが、きょうのところは、もう少し成り行きを見守ってみたいということで、継続ということで話がありますので、私もそれでいいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":81,"id":"exchange-034"},{"speaker":"宮崎委員","kind":"意見","question":"やっぱりこれは結論を出していくべきではないかというふうに私は思います。そういう意味では、話し合いの場でも進めているということなんですが、やっぱり今までの経過もありますから、しっかり話し合いをさせるという角度から、議会の態度というものをしっかり出す必要があるのではないかと思いますので、私はきょう結論を出すということで主張したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":82,"id":"exchange-035"},{"speaker":"井上委員","kind":"質問・要望","question":"私もここの思いというところは十分理解できますし、ここは駐車場８４台を設置することで、ここは一方通行のところで、高さも１２階という、本当に法律で一番緩いもので、そこさえクリアしていればいいんだということではないまちづくりが必要だというふうにいつも思っていますので、ここはそういう意味でも業者の方にきちんと誠意を持って協議に臨んでいただくという意味では。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-036"},{"speaker":"大西副委員長","kind":"意見","question":"そしてまた、日照も前の事業所、工場の状況とほとんど変わらないという認識をしっかりと住民の方々がご理解していただいているか、そういう点が推測でおそらくなされているのではないかというようなことろもあろうかと思うので、これはもう一度少し今、私はそれほど悪質な事業者、要するに、最初の段階での搬入等において若干のミスが私もあったかというふうに承知しますが、その後、１カ月半も、今。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":84,"id":"exchange-037"}]},{"id":"topic-02","title":"の区営自転車等駐車場の指定管理者募集","agenda":"の区営自転車等駐車場の指定管理者募集","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"第一次選考委員会、第二次選考委員会、それぞれありますけれども、第一次と第二次と、主に何を重点に審査をするかということ。審査の中身をちょっと教えていただきたいのと、選定委員会ですけれども、メンバー、人数、どなたが選定委員になるのか、この外部委員というのはどういう方なのか、あわせてご説明いただきたいと思います。","respondent":"松嶋交通安全担当課長","answer":"ただ、一応、人数的には７名ぐらい、７名か８名程度になろうかと思います。外部委員につきまして、現在、これも最終決定をしているわけではございませんけれども、一応、公認会計士の方にお願いをするつもりで予定しております。","voiceIndex":90,"id":"exchange-038"},{"speaker":"中塚委員","kind":"質問・要望","question":"次長、部長、課長、それぞれの役所からの方が、今の時点で何もまだ決まっていないとは思えないんですけれども、選定委員会のメンバーを、１人は、今、公認会計士というのはわかりましたけれども、残りがだれなのか、それはわかると思いますので教えていただきたいのと、それと、第一次と第二次それぞれ説明がありましたけれども、計画書を見て第一次を審査して、第二次はヒアリングということですけれども。","respondent":"松嶋交通安全担当課長","answer":"続きまして、議決の関係です。当然、指定議決、第４回定例会のときにいただくようになるかと思いますけれども、当然この指定の議決がなければ指定管理者の指定というのはできないわけですので、その審議にわかりやすいような最小限のものは当然資料として出すつもりです。","voiceIndex":92,"id":"exchange-039"},{"speaker":"中塚委員","kind":"質問","question":"私、同じ資料が提出されなければ、公平かつ適正な議会の議決とは言えないのではないかということを伺いたいんです。例えば、２番目の「放置自転車対策に関する基本的な考え方」、この質問に対して文書で出してくるわけですね。これ、一個一個追っていくとそうなんですよ。私はやっぱり議会としても公正、そして適切な判断を下すに値する資料を議会に出すべきだと思うんですけれども、いかがでしょうか。","respondent":"福田まちづくり事業部長","answer":"例えば委員会の開催の経過ですとか、それから概要ですとか、こうしたものは、これは当然でありますけれども、委員会にご提案をし、審査のための資料としてご提出をする予定です。","voiceIndex":94,"id":"exchange-040"},{"speaker":"中塚委員","kind":"質問・要望","question":"議会として独立して議決として求められている以上は、この応募に当たっての資料、これをきちんと我々の評価、議会が評価するわけですから、この業者がふさわしいのかどうか、問題点はないのか、きちんと資料を出すべきだと思います。ごく基本的なことなんですよね、ここに書いてあるのは。３ですと自転車駐輪場利用者管理計画、どういう方法を考えているのか。","respondent":"福田まちづくり事業部長","answer":"それと、先ほど申しましたように、選定等に関する審議に必要な経過とか対応については、この当該委員会に提出をするというふうに考えております。それらの資料をもとにしてご審議をいただき、議決いただければ大変ありがたいと考えています。","voiceIndex":96,"id":"exchange-041"},{"speaker":"井上委員","kind":"質問・要望","question":"先ほど議決に当たって、経過だとか、概要だとか、審議に対して有意なものは出す用意があるというふうにおっしゃいましたけれども、審議に対する有意になるものというものが、行政のほうで有意になるものととらえられてしまえば、私たちはそこでそれを出されただけで考えていかなくてはいけないので、私たち議会の側が有意と思うものを出してほしいというときには、きちんと出していただかなければ。","respondent":"福田まちづくり事業部長","answer":"委員会の意思として執行機関に提出の要請があれば検討します。","voiceIndex":99,"id":"exchange-042"},{"speaker":"井上委員","kind":"質問・要望","question":"指定管理に当たってなんですが、ここは全部、指定管理を前回に聞いたときに１社にするということで、それは機械設備、システムなんかがそれのほうが効果的だということだったんですけれども、これがまた５年後にはどこかの業者に変わるときには、自分たちのシステムを導入するとかというふうになる可能性もあるとすれば、利用者の側で比べるとか、そういうサービスのあれを検討するというときに。","respondent":"松嶋交通安全担当課長","answer":"確かに委員ご指摘のとおり、これを１社にするのか、それとも施設ごとにやるのか、そういった検討は十分にやってまいりました。","voiceIndex":101,"id":"exchange-043"},{"speaker":"宮崎委員","kind":"質問・要望","question":"それに関連するんですけれども、ここにも公表するということでは選定の結果及び理由ということで、ホームページで公表するというふうにしてやっておりますけれども、区ではどこの辺まで公表するのかというところになってくるのかなと思うんですけれども、ちょっとそこのところを考えてお伺いしておきたいんですが、どうでしょうか。","respondent":"松嶋交通安全担当課長","answer":"公表内容につきましてですけれども、これは基本的には指定管理者として指定された業者、そこがどのような提案を行ったのかというところの部分の公表をする予定です。","voiceIndex":103,"id":"exchange-044"},{"speaker":"宮崎委員","kind":"提案","question":"その業者のほうの提案と、品川区がどういう基準でここに決めたという、そういうものが例えば３社あるいは４社、Ａ社はこういう提案だった、Ｂ社はこういう提案だった、それで品川区としてはこういう事由でここに決めたというふうにならないと、なかなか委員会のほうとしてはわからないんですけれども、もう一度ちょっと確認させてください。","respondent":"松嶋交通安全担当課長","answer":"これは先ほどご説明いたしましたとおり、指定管理者に指定されたところの業者を公表すると言いましたけれども、それは当然、ただ単にＡ社に決定しました、これだけでは当然公表にはならないわけですので、そこでこういう部分が優れていたんですよ。","voiceIndex":105,"id":"exchange-045"},{"speaker":"宮崎委員","kind":"質問","question":"利用料金制を採用しないという部分の考え方を、前にもしかしたら聞いたのかもしれないですけれども、それを改めて聞いておきたいのと、もう１つ、ちょっと細かいことですが、選定委員会のところは、７名か８名くらいで、その中で公認会計士も考えているという話だったんですけれども、公認会計士は今、区の監査委員もされている方がいらっしゃるんですけれども。","respondent":"松嶋交通安全担当課長、岩田まちづくり事業部次長","answer":"利用料金制をとらない理由ですけれども、これにつきましては、駐輪場施設というのは休みなく３６５日稼働しておるわけでございまして、毎日毎日そういった利用料金が発生するわけです。したがって、これが区がやらなくなれば、どんどん放置自転車がまた増えて、駐輪場の収益が減るという、こういう経緯になっておりますので。","voiceIndex":107,"id":"exchange-046"},{"speaker":"宮崎委員","kind":"質問","question":"利用料金制度のほうは、とりあえずわかりましたけれども、先ほど、井上委員の質問のときにもありましたけれども、私も以前、指摘させていただいたんですが、やっぱり１社に絞るということは、やっぱり私も理解できないんです。これはやっぱり１カ所ではなくて、数カ所、これはもう最低限やらないと不透明極まりないというふうに思って、危険性をはらんでいるというふうに思います。ちょっと１点。","respondent":"松嶋交通安全担当課長","answer":"もちろんここに第二、第三はあるにはあるんですけれども、それぞれ利用率的には若干下回っているところですので、そういったところに、例えば中延第一のここは二輪が置けるようになっておりますから、二輪を、じゃあ、第二、第三のほうへどのようにしてやっていくか。","voiceIndex":110,"id":"exchange-047"},{"speaker":"井上委員","kind":"確認","question":"ごめんなさい、１点だけ。先ほど次長の答弁で、放置自転車のところでこっちに考え方にもあるんですが、放置自転車が多いと駐輪場の利用が落ちるというような発言があった中で、今、直営でやっています放置自転車対策を、こっちの業務のほうには入っているのか、確認していないですが、そこを移行されるような心づもりがあるというふうなことはあるのでしょうか。ちょっとその辺を。","respondent":"松嶋交通安全担当課長","answer":"ただ、現実にじゃあ、放置自転車の撤去活動、それを指定管理としてやらせることができるかというと、それはなかなか即時強制部分がございまして難しい部分があります。これは今いろいろなところに聞いているところですけれども、明確な回答が返ってきておりません。","voiceIndex":113,"id":"exchange-048"}]},{"id":"topic-03","title":"平成１８年８月都営住宅入居者募集","agenda":"平成１８年８月都営住宅入居者募集","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"ちょっと伺います。事業再建者向定期使用住宅というのは、ちょっと私もよくわからないので、どういうものかと、あと、何戸ぐらいあるのか。そこをお願いします。","respondent":"齋藤住宅課長","answer":"事業再建者というのは、中小企業を区内で３年以上経営していて、事業が立ち行かなくなってしまった。現在、会社が再生法が適用されていて、借金のかたで家がとられてしまった。そのような方に、事業再生に向けて家を貸していく、こういう制度です。","voiceIndex":121,"id":"exchange-049"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、定期使用というと、そうすると何年ぐらいに決まっているのでしょうか。","respondent":"齋藤住宅課長","answer":"詳細はいろいろな状況によって違うようですが、５年、１０年までです。","voiceIndex":123,"id":"exchange-050"}]},{"id":"topic-04","title":"の（株）品川宅建管理センターを区民住宅および区営住宅の指定管理者に指定すること","agenda":"の（株）品川宅建管理センターを区民住宅および区営住宅の指定管理者に指定すること","exchanges":[{"speaker":"井上委員","kind":"質問","question":"そうでなければ、これから何年かたって変わるところがあるかと思うんですが、そこは民間の企業である、そのときには公募をするけれども、ここでは今まで品川区と協力していた団体だから公募をしないというようなことでは、それはあるべき姿ではないと思うので、これはやっぱり報告ということでしたけれども、これはやっぱりおかしいんじゃないでしょうか。","respondent":"齋藤住宅課長","answer":"具体的に言うと、３年で切られるということになりますと人を雇えない。人材を確保できないんです。区の仕事がなくなったから首を切るというわけにもいきません。","voiceIndex":133,"id":"exchange-051"},{"speaker":"井上委員","kind":"質問・要望","question":"経済的とか、そういう時間的なものとか、行政の仕事の量とかも勘案しているかもしれないけれども、この不透明になってはいけないという指定管理者制度に対して、このことが本当にいいものだというふうに、こういうやり方は私は問題があるということを指摘をして、皆さんのご意見があるのかもしれないですからお聞きしたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":135,"id":"exchange-052"},{"speaker":"宮崎委員","kind":"意見","question":"先ほども言ったんですけれども、結局、ここに書いてある経験とかノウハウを引き続きとなったら、競争、要するに、選定のそのものの考え方がどうなんだと、僕は指定管理者制度そのものに反対なので、やっぱりそもそもおかしいなと、やっぱりおかしいなとつくづく感じるところなんですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":137,"id":"exchange-053"},{"speaker":"大西副委員長","kind":"意見","question":"ちょっと１点、先ほど住宅課長の話の中で、昨年度でしたか、未収というか、家賃をとり損ねているという部分がありましたが、これは私は昨年度もここで指摘しておいたんですけれども、保証人がついている、両方ともにそのままの状況の勤務先にいるという状況でありましたが、そのうちその回収のほう、これはどうなっていますか。","respondent":"齋藤住宅課長","answer":"税金であれば預貯金の調査を課長決定で起案をして、区長に送れば調査ができます。回収は裁判所を通さないとできない、こういう関係になっておりまして、財産調査がまず前提です。それで、滞納されたまま退去された方、十人ほどいます。可能な限りで調査をいたします。","voiceIndex":138,"id":"exchange-054"},{"speaker":"大西副委員長","kind":"質問・要望","question":"提出書類の中に、これは収入書面というのを、当然、区民住宅、今のは区営住宅にかかわっているのか、区民住宅にかかわっているのか、およそ２つのことを言っているのかというふうに想像するんですけれども、その辺はどういう具合なんですか。そして、在籍を確認した場合には、当然それを裁判所を通じて差し押さえるのが当たり前のことだと思いますが、そのこと自体はやっておられるかどうかお伺いします。","respondent":"齋藤住宅課長","answer":"保証人を立てられなかったために代行会社を活用するという制度です。収入の添付を求めておりますが、保証人の収入は２４０万円です。それで、５年、１０年続けますと、大体親御さん、親戚の方なので、滞納されたときには高齢になっております。","voiceIndex":140,"id":"exchange-055"},{"speaker":"大西副委員長","kind":"質問","question":"その保証人の意味をなさない、２４０万円というものに対してなさないという、そしてまた、当該入居人自体がそのままの職場であって継続しているということで、その者に対しての給料の差し押さえをしないということは、それが払えないという前提に立っているから、その者がどうして入居できたのかということになって、応募資格上の瑕疵が想像されるのではないかと思いますが、どうですか。","respondent":"齋藤住宅課長","answer":"ただ、著しく資力が下がって、６カ月以上滞納があるような場合には、先ほどもお話が出てまいりましたように、保証人にも声をかけるし、本人の自覚を促して払っていただける方向で、区としても努力しています。","voiceIndex":142,"id":"exchange-056"},{"speaker":"大西副委員長","kind":"質問","question":"最後に。私は１件、去年あった６カ月、ついに入ってから１回も払っていないということなので、それは昔の話、１０年とか、親御さんの話とかではないと、その案件についてのことをお尋ねしているんです。引き継ぎはされていないんですか。","respondent":"齋藤住宅課長","answer":"名前を言うと支障がありますので。この方は退去していただいています。","voiceIndex":145,"id":"exchange-057"},{"speaker":"大西副委員長","kind":"意見","question":"その後の請求はどうなっていますかという話です。裁判所を通じてやっているかという話。","respondent":"齋藤住宅課長","answer":"やっております。やって、回収できるほどの資力は今のところ見つかっておりません。裁判所を通じて請求しているということは、最低限、四、五十万円かかります。四、五十万円回収できるほどの資力は見つかっていない、こういうことです。","voiceIndex":147,"id":"exchange-058"},{"speaker":"中塚委員","kind":"質問・要望","question":"都市景観、かなり広い概念で、ちょっと伺いたいのは、いわゆる建物の高さの問題とかも含めているのか、それとも観光的な要素に絞っているのか、かなり広い領域なので、ちょっともしお考えがあれば、その辺を含めてご説明いただきたいんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":152,"id":"exchange-059"},{"speaker":"中塚委員","kind":"質問","question":"私たちの会派のほうでは、再開発、まちの問題、また広町の問題、そうした意味では、都市景観という分野でくくると僕は思うんです。そういう理解でいいのかなということなんですけれども、今のお話だといいのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":154,"id":"exchange-060"},{"speaker":"井上委員","kind":"質問","question":"私は、三重県を含めてそちら方面でバリアフリーの都市整備みたいなところで出しましたけれども、ここが複数の会派の委員から出たところということなので、その辺のもう少し、私はバリアフリーの視点で出しましたので、ここに入れました。ほかに何かここへ絞っていただくに当たって、出されたことというのはあるんでしょうか。","respondent":"伊藤委員長","answer":"ほかに出されたのは、まさに水族館めぐりで、調査項目について、それから広い意味で都市景観づくり、この中には高さ規制、それから市街地再開発というようなものが複数の会派から出てきたということでありますので、その調査項目と。","voiceIndex":160,"id":"exchange-061"},{"speaker":"井上委員","kind":"提案","question":"よくわからないんですけれども、この久留米市なんかでいくと、去年なんかも熊本の駅周辺の整備事業とかという項目で視察をさせていただいたんですが、よほど市街地整備というところでは、どういう視点を持つかということが必要で、とてもただ話を行政の方に聞いてどうなんだろうというところがあるので、この久留米の市街地整備。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":162,"id":"exchange-062"},{"speaker":"井上委員","kind":"意見","question":"規模とか、そういうのは、この辺はどうなんでしょう。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":164,"id":"exchange-063"},{"speaker":"中塚委員","kind":"提案","question":"前の委員会で僕は意見として言ったんですけれども、所管事務調査の中身に応じて、僕は現地へ行こうと、であれば理解できるんですけれども、その点で、この水族館、所管事務調査の中でどのような関係があるのかなと。施設を見るのに提案した方に聞いてみないと、僕はわからないんですけれども、どういう具合にこれを提案されたのか、今の区政の視察においてそういうふうな必要があるのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":171,"id":"exchange-064"},{"speaker":"大西副委員長","kind":"提案","question":"これは私も提案させていただいた１人です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":172,"id":"exchange-065"},{"speaker":"中塚委員","kind":"質問","question":"僕はこの「うみたまご」がどんなところか全然わからないのであれなんですけれども、しながわ水族館は教育施設という面と、公園の中にある営業施設というので、かなり特殊な契約というんですか、ものだというのがこの前あったので、どこが売れているんですかね、この大分マリンパレス、わからないんですけれども、運営形態が特殊なんですよね。そうですよね。公園の中にある商業施設、そういう意味では。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":173,"id":"exchange-066"},{"speaker":"中塚委員","kind":"意見","question":"やっぱり肝心なことですけれども、所管事務調査の中で、やっていこうということであれば、いろいろお話も学ぶこともあるでしょうけれども、どうもここだけ行政視察の中で、今の区民の暮らしのなかでこれに重点を置いていこうという、そこに絞り込んだものであればあれだったんだけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":175,"id":"exchange-067"},{"speaker":"藤田委員","kind":"意見","question":"我々委員はいろいろなことを議論します。それには、水族館を品川に当てはめて、それをじゃあ、やらなければならない、そういうのではなくて、その事業を運営するにはそれぞれどういう苦労があるのかというのを、私も旭山の動物園へ行ってきたんですけれども、園長が出てきて、１時間講演したんです。きょう決めないといけないというのであれば、ある程度の枠を正副委員長で決めてください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":177,"id":"exchange-068"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3856#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":53291,"voices":179}},{"id":"h18-20060725-9","meetingId":"h18-cm07","date":"2006年7月25日","dateIso":"2006-07-25","committee":"文教委員会","time":"午後１時０３分～午後２時４６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"八潮地区小中一貫校設置の経過報告","agenda":"八潮地区小中一貫校設置の経過報告","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"特に子どもに対する影響で、子どもの声なんかも慎重に聞く必要があるんじゃないかという意見だとか、非常に揺れ動いている、議事録から読み取ることができるのは、そういうふうに私は思うんですが、これをもって全体の合意が一貫校でまとまっているというのはちょっと無理なんじゃないかと思うんですが、どうお考えでしょうか。","respondent":"古里学務課長","answer":"先日、この説明会が終わった後、八潮北小の保護者会がございまして、一番不安な声を言っておられるところが北小でございましたけれども、そちらに出向き、八潮の将来つくられる一貫校の構想、あるいはそれに至る過程についてるるご説明申し上げたところ。","voiceIndex":5,"id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"だけど結果的には五校の統廃合は決定したという上での説明会ですから、この言っていることと実態というのは乖離があるんじゃないかというのをちょっと考えています。南中について２年と３年しかいない。同じようなことが起きれば、統廃合という格好で第２、第３の八潮地区のようなことが出るんじゃないかと非常に心配をするんですけれども、その辺はどう考えていらっしゃるんですか。","respondent":"古里学務課長","answer":"ただ沢田委員がおっしゃいました周辺学校への影響というのは日野学園でも起こってありますので、この辺は今後そうした状況をしっかり見ながら、対応をそれぞれしていきたいと考えております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"沢田委員","kind":"質問","question":"そういう学校選択は親の学校を選ぶ自由を保証すると同時に、整理淘汰する機能があるから今回こういう状況になっているので、そういうことはないのかと私は質問したんですけれども、周辺に与える影響ということを聞いたわけじゃなくて、第２、第３の八潮が内陸部のほうで出てくるんじゃないかというのが本当に心配なんですけれども、その辺に対してはどうなんでしょうか。ないと断言できるんでしょうか。","respondent":"古里学務課長","answer":"こうした現象を注意深くとらえながら見ていくということを考えてあります。それぞれ一貫校ができるところにつきましては、現在の時点からさまざまな分析をし、それから学校と連携して対策をとるということを今検討しています。","voiceIndex":9,"id":"exchange-003"},{"speaker":"沢田委員","kind":"質問","question":"私は一貫校の問題よりも学校選択による過少校になっているところが心配で、ちょっと学校名を挙げるのがいいかどうかというのはあるんですけれども、１０名を割っているところがありますよね。そうしたところに今回のような事態が及んでいかないのかどうなのか。私はあまりこういうことが広がるのは好ましくないと思うんですが、いかがですか。","respondent":"長田教育次長","answer":"いずれにいたしましても、この一貫校に始まる品川区内の学校のあり方については、次の報告になりますけれども、この小中一貫教育の効果をこれから検証していかなければなりませんので、そういった検証の中で。","voiceIndex":11,"id":"exchange-004"},{"speaker":"築舘委員","kind":"質問","question":"ですから、あとはそういういろいろな自分たちの学校のよさとか、あと統合するにあたっての小中一貫の具体的な構想、それからあと、それがどういうふうに自分たちの学校がなくなるんだけど、それが新しいものに生まれ変わっていくのかという、そこをまず皆さん方に説明しながら、またそれを魅力としていけるように説明していただくということがこれからの、早急にやらなきゃいけないわけですけど。","respondent":"古里学務課長","answer":"それとその過程の中で、９月の前半に予定をしていますが、第２回目の地元それからＰＴＡの説明ということをやりたいと考えていますが、その折りには関係部局への参加の要請もさせていただいて、教育委員会が答えられないことについて。","voiceIndex":13,"id":"exchange-005"},{"speaker":"林（宏）委員","kind":"質問","question":"基本的なところを最初にお聞きしたいんだけれども、いただいた経過報告に入っていないところで、八潮地区の各小中学校で子どもさんが減少あるいは現状維持という数字の流れを説明されているんだけど、今、八潮地区という全体の中で、人口動向というのはどういう、あるいは住まいというか、マンションでの空きとか、例えば八潮地区の活性化というのを考えているとすれば。","respondent":"古里学務課長","answer":"先ほど申し上げた全庁的なプロジェクトの中で、八潮地域の活性化策ということがどのように検討されるかということもありますけれども、もしそれが林委員のおっしゃるような。","voiceIndex":15,"id":"exchange-006"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"たまたま入学するお子さんが０になってしまったということも、この２つの中学校の必要性から考えると１つでもいいのかなという、そういうことも数の上からは見れるかなと思うけど、この最良の教育環境ということについて教育委員会がどうとらえているのか、生徒の数、あるいはいろいろ学校の今やっている小中一貫教育のとらえ方、八潮地区で１校になってしまうと、それこそ沢田さんが言う競争もなくなって。","respondent":"吉村小中一貫教育担当課長","answer":"この点については品川区の考えている小中一貫教育の考え方と合致していますので、その点を十分考慮しながら、これからの一貫校づくりの検討をしていきたいと考えています。","voiceIndex":17,"id":"exchange-007"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"それが八潮づくりと言っていいのかな、活性化というのはね。新しい八潮づくりという中で、教育委員会は教育だけを考えているということではなくて、きちんと区のそういう方針、それからまちの人たちの考え方と教育委員会の考え方がマッチングして進められるようにしていくべきだと思うんですけれども、その辺の対応策として何かお考えがあったら聞かせてください。","respondent":"古里学務課長","answer":"それについては、先ほど来申し上げている全庁的な準備ＰＴがある程度形が整って、実際に八潮の皆さんとどういう協議を進めていくのかというのは、これからつくり上げられる課題ですので。","voiceIndex":19,"id":"exchange-008"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"そういういろいろなことを踏まえてやっていただきたい。最後につけ加えると、これだけ八潮から八潮地区外の学校を選択した子どもがいるということですから、逆にこの学校が一貫校ができ上がった先、八潮を選択するという、八潮地区外から行くような学校づくり目指してほしいなと思いますので、ぜひその辺も十分に考えてやっていただきたいとお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-009"},{"speaker":"武内委員","kind":"質問","question":"報告いただいて、地元説明会の会議録の３０日のところに、８月ごろまでに一定の結論を出しそうだと教育委員会から保護者の方に質問がされているんですけれども、平成２０年４月開校のためにはということもありますが、そうしますと、今回この２日間、３０、３１日の説明を踏まえまして今日ご報告いただいた内容が、ある程度これで一貫校としていくんだよという結論としての報告ということでよろしいんですか。","respondent":"古里学務課長","answer":"平成２０年開校ということで設定させていただいたんですが、実は２０年４月に向けて八潮地区小中一貫校とすべきいろいろな改修工事をしていくためには、実は今年度から設計ですとか、さまざまな具体的な検討にはいる必要があります。","voiceIndex":22,"id":"exchange-010"},{"speaker":"武内委員","kind":"質問","question":"一応説明会の前にいろいろな形で説明をやってこられて、今日報告いただいたのは、この一貫校としていきますよということでよろしいですか。","respondent":"古里学務課長","answer":"委員のおっしゃるとおりです。","voiceIndex":24,"id":"exchange-011"}]},{"id":"topic-02","title":"の文部科学省「新教育システム開発プログラム」事業の受託","agenda":"の文部科学省「新教育システム開発プログラム」事業の受託","exchanges":[{"speaker":"林（宏）委員","kind":"意見","question":"何と言ったらいいのかな。聞きたいのは、裏面の検証すべき仮説の中に(2)の3)に施設一体化による子どもたちの学校生活と書かれているんだけど、ここだけ子どもたちの部分が入ってくる。一貫校による子どもたちの学校生活の変化はとらえられるんだろうけど、連携校についての子どもたちの、一貫校というのは１つの学校の中で一体型で教育を受ける。その辺についての検証は行わないの。","respondent":"吉村小中一貫教育担当課長","answer":"当然連携校についても、一体型一貫校の日野学園のような同じような調査はできないんですけれども、連携校、施設が離れている中でも、カリキュラムを同じことにすることによってどういう変化が生じてきているのか、そのことについては調査をするつもりです。","voiceIndex":30,"id":"exchange-012"},{"speaker":"林（宏）委員","kind":"質問","question":"品川区は小中一貫教育とうたっているわけで、その中で一貫校を６つつくるんだと。ですから、こういう文部科学省のあれで出していくということになれば、日野、日野というふうに一体型一貫校だけを主に検証を加えていくということは、落とし穴があるんじゃないかなと僕は思うので、これをやることは大変結構なことだけど、それを忘れないてほしいと思うのを１つ伝えておきます。","respondent":"吉村小中一貫教育担当課長","answer":"１点目の件ですけれども、私の説明の仕方がちょっと悪かったのかもしれません。ここに(1)から(4)を掲げておりますが、(2)については日野学園、一体型一貫校の話なんですが、(3)はまさに連携校の話です。","voiceIndex":32,"id":"exchange-013"},{"speaker":"林（宏）委員","kind":"質問","question":"受託をしたんだよね。文部科学省の試みに対して受託。これから品川として受託を受けて、３番のこういうことをやっていくわけだけれども、それは丸投げしないで、品川区の教育委員会の中につくる、よそからのいろいろな先生も入っていただいて、検証委員会という中でやっていくわけでしょう。そうすると、品川区の予算も検証委員会の中に入っていくわけじゃないんですか。","respondent":"吉村小中一貫教育担当課長","answer":"この検証については、一切品川区の予算ということではなくて、いただいた国の予算の中で進めていただくです。","voiceIndex":34,"id":"exchange-014"},{"speaker":"林（宏）委員","kind":"質問","question":"１問目のときの前段の小中一貫、連携、それから一体型という、非常に難しいのは、行財政ということに限られてくるということになると、こういうことが入ってくるのかどうかわからないけど、例えば４・３・２という仕組みを義務教育の中で品川は打ち出していく。詳しくは聞けなかったんだけど、４・３・２ではない。そういうことまでも検証できるんですか。","respondent":"吉村小中一貫教育担当課長、市川庶務課長","answer":"２点目の件ですが、まさに私どもは９年間をつなげるという考え方ですけれども、その中を最初の４年間と次の３年間、最後の２年間としたときに。１点目のお尋ねに私のほうからもお答えします。これはいわゆる補助金ではございませんけれども、補助金で言うと１０分の１０に相当する意味合いを持った国からの委託金です。","voiceIndex":38,"id":"exchange-015"},{"speaker":"林（宏）委員","kind":"意見","question":"そうすると、これが出て、３カ年計画で品川の主張というか、品川で検証された結果を文部科学省に報告をしていく。それをベースに品川の教育改革を進める上での１つの研究材料というか、ベースとして考えていく。それで報告をした後、どういうふうにしていくのか。それから、我々に対しての報告みたいなものもどうオープンにしていくのか、それだけ最後に聞かせてください。","respondent":"吉村小中一貫教育担当課長","answer":"先ほどの説明の中でちょっと申し上げたことなんですが、そもそも小中一貫教育をスタートするというときに、当然新しい教育の考え方ですので、教育委員会としてこのことについては学力や人間形成、学校のあり方、さまざまな面で検証は進めていこうと思っていました。","voiceIndex":41,"id":"exchange-016"},{"speaker":"沢田委員","kind":"質問","question":"この開発プログラムの目的のところに将来の制度改正を見据えとあるんですけど、将来の制度改正とは何を指すんですか。今言ったことの。","respondent":"吉村小中一貫教育担当課長","answer":"４つテーマがありますので、それぞれのところに絡んでくる法律ですけれども、私どもとしましては、特に今、教育長が説明した、いわゆる義務教育学校の設置ということについて、自治体の裁量でできるということについての法改正、その制度改正についてここでは考えております。","voiceIndex":45,"id":"exchange-017"},{"speaker":"沢田委員","kind":"質問","question":"一貫教育が４番目のテーマとして手を挙げて指名されたということなんですけど、一貫教育が将来の制度改正として見込まれているんですか。もしそういう背景があれば説明願いたいんですが。","respondent":"吉村小中一貫教育担当課長","answer":"昨年の１０月の中教審の答申の中で、義務教育学校の設置に向けて検討していくということが文言で正式に出ておりますので、国もその方向はにらんでおります。","voiceIndex":47,"id":"exchange-018"},{"speaker":"沢田委員","kind":"質問","question":"教育基本法の改定案の中で、中教審のどこかの部会だったと思いますけど、１７条かな。教育振興計画を立てて、どういう教育をやるのかというのが議論されて、私は議事録を見たんですけれども、その中に小中一貫教育、学力テストの全国実施、習熟度別学習の徹底と具体的に書かれているんですね。一審議会ですよね。だから、それからすると、ちょっと無謀と思いますが、いかがお考えでしょうか。","respondent":"吉村小中一貫教育担当課長","answer":"当然法制化するにあたっては、全国のいろいろなモデルケースを十分に検討しながら法制化に踏み出すわけで、そういった部分について全国の取り組みを見ていくのは当たり前の話ですし。","voiceIndex":49,"id":"exchange-019"},{"speaker":"沢田委員","kind":"質問","question":"今のままの教育基本法によれば、教育行政というのは教育条件の整理ですからね。教育内容まで踏み込んで、ああでもない、こうでもないということを実際にやっているわけですから、教育基本法に抵触すると思います。それから、最後の競争教育の問題について、じゃ、競争教育というのはどういうものか、どう考えているのか、そうじゃないというんだったら説明してもらえますか。何が競争教育なのか。","respondent":"吉村小中一貫教育担当課長","answer":"１点目のお話ですけれども、先ほどもちょっと申し上げたように、中教審の答申の中で、今後の国の義務教育のあり方を、さまざまな学識経験者を交えた検討会の中で、１つの案として。","voiceIndex":51,"id":"exchange-020"},{"speaker":"沢田委員","kind":"質問・要望","question":"点数が多いところを選んでいく。ある不動産会社なんかを見ると、品川の学力のトップの位置にできたマンションですと、それを宣伝しているわけですから。これは学力格差がますますつくじゃないですか。だから、競争教育じゃないとこれまでの議会でもたびたび言っているけれども、それじゃ競争教育というのはどういうのをイメージしているのか、具体的にこういう自治体でこういう教育だというのを出すべきだ。","respondent":"若月教育長","answer":"点数で輪切りされている。それが競争教育です。目に見えないところで競争教育は行われているというのが、私の認識であります。品川の今やっていることは、子どもたちの幸せのために決して間違ってはいない。私はあえてそこを申し上げたいと考えています。","voiceIndex":53,"id":"exchange-021"},{"speaker":"沢田委員","kind":"質問","question":"品川のやっている弊害がダイレクトにあらわれたのが、特殊な事情があったとはいえ、八潮ですよ。こういう状況だとさっきの話だと、内陸部にも今後起きるでしょう、今の状況だったら起きるでしょう、第２、第３の八潮が。ここは弊害が既に出ているんですよ。この問題のあれについては、この後の質問でちょっとまた別の件でしたいと思いますので、とりあえずこれで終わっておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-022"},{"speaker":"武内委員","kind":"質問","question":"先に質問しておけばよかったんですけど、この内容についてお聞きしたいんですけれども、この実施委員会というのはどういうことをされるのかというのと、検証を進める検証委員会との関係について、どういう位置づけにあるのかというのを教えてください。","respondent":"吉村小中一貫教育担当課長","answer":"それともその検証結果から見えてきたこととしてどんなことが言えるのか、そういった大もとのところを話し合うのが実施委員会。その実施委員会で話し合ったことをもとに、実際に調査・検討で動いていくのがこの実施協力機関とお考えいただくといいのかなと思います。","voiceIndex":56,"id":"exchange-023"},{"speaker":"武内委員","kind":"質問","question":"わかりました。ここに品川区教育委員会以外にも外部の大学教授とかがいらっしゃって、そこで外部の、検証委員会というのはおそらく内部的な、品川区的な位置づけだと思いますけど、区独自で内部で評価した部分を、実施委員会の中に入っているいわゆる外部的な位置づけの方にお墨付きというか、検証してもらったものを表に出す、そういう流れなんでしょうか。","respondent":"吉村小中一貫教育担当課長","answer":"最終的にこの実施委員会の中で整理をしてある程度文章化していくと思うんですけれども、当然その中で、ここに書いてあるお二方の学識経験者からいろいろご指導いただきながらまとめていくということになります。今、委員のおっしゃったとおりです。","voiceIndex":58,"id":"exchange-024"},{"speaker":"沢田委員","kind":"質問","question":"前回の当委員会でも言ったんですが、６月に発表された公立小学校の学力テストの状況について聞きたいと発言したんですが、改めてわかる範囲でいいですから、品川の状況と全国の状況とか、試験の中であらわれた問題点、克服すべき課題などについて説明願いたいんですけれども。","respondent":"中島委員長、河野指導課長","answer":"本件については、前回の委員会でも沢田委員より発言がありましたが、理事者の方でお答えできればお願いします。６月に発表された東京都の学力調査の結果ですが、達成率ということで報告されております。それぞれの教科ごとの分析については前年度と大差ございませんで、得点的にはおおむねいい状況にはあるという報告をいただいております。","voiceIndex":62,"id":"exchange-025"},{"speaker":"沢田委員","kind":"質問","question":"ここに足立の記事があるんですけど、全体として思考力、読解力などに問題を残すものの、全教科平均点が７０点を超すという評価を朝日新聞がしているわけですけれども、今の時点で、例えば品川区教育委員会として、品川の子どもたちに今度のテストから導き出す教訓は何なのかということがある程度まとまったものは、これからなんですか。","respondent":"河野指導課長","answer":"その部分については、必ずしも都の調査、あるいは国の調査ですべてはかれるということではございませんので、今年度については、従来どおりの区の調査で実施をしますけれども、平成１９年度以降については、品川区の小中一貫カリキュラムに基づいた問題作成をして、その結果。","voiceIndex":65,"id":"exchange-026"},{"speaker":"沢田委員","kind":"質問","question":"だけど、私は品川区は既に学校ごとに成績を公表しているのならば、今度のこの東京都がやった段階に対して、そのことを公表したという考え方の基本に照らしてどうだったかというのは、答えるべきだと思うんですよ。こういうふうにやれば当然なっちゃうんだけれども、品川区はそういうふうにあえて公表しているならば、この問題に対する考え方を聞かせてほしい。だったら品川も公表はやるべきじゃない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-027"},{"speaker":"沢田委員","kind":"質問・要望","question":"専門的って、その他ありませんかと言うから、前回も私はこの点に関心があるので準備をしていただきたいということを言った上でね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-028"},{"speaker":"沢田委員","kind":"意見","question":"資料要求ではないけれども、関心があるので、非常に聞きたいということを言ったので聞いているので、答弁がなければないで結構なんですけど、もしあるならば言ってほしいと、改めて別の機会も決算や何かもありますから、これ以上だめであるならば、それはそこに回したいと思いますが。","respondent":"吉村小中一貫教育担当課長","answer":"指導改善がねらいだとすると、何が必要かというと、一つ一つの設問について、教育委員会が設定した基準、習熟基準といいますが、教育委員会が設定した基準と、それに対する正答率、その２つを示して、その正答率が基準よりもし下回っていた場合に、学校は指導をどうするのか。","voiceIndex":71,"id":"exchange-029"},{"speaker":"沢田委員","kind":"提案","question":"最初は、提案があったとき、区で一括して出すという話だったんですよ。私はそれは問題だろうと。本当に学力テストでもって先生たちが子どもの到達度を知って授業改善に役立てるというんだったら、品川の学校ごとのそれだってやめるべきなんですよ、それが目標であるならば。今はもうインターネットでスパンと見られるわけですから。それはぜひ検討していただきたいということを要望して終わりたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":73,"id":"exchange-030"}]},{"id":"topic-03","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"林（宏）委員","kind":"意見","question":"「宗像市の小中一貫教育について」という表題だけなんだけど、次の佐賀市は小中一貫芙蓉校。宗像市はどこか学校を見に行くということなのか、宗像市教育委員会で話を聞くということなのか、それだけ聞かせてほしい。それから佐賀市の地域子ども教室というのがあるの。教室なの、これ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":79,"id":"exchange-031"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"子ども教室というと、教育委員会が何かやっていたり、学校の延長線上にあるような感じなんだけど、地域なんだからと思うんです。わかればで結構、次のときで結構なんだけど、認識として、教育委員会がやっている施設を見に行くのか、地域が積極的に運営してくれているのか、その辺を確認させていただきたいと思って聞いています。","respondent":"中島委員長","answer":"１点目の宗像市のこれは日の里東小学校とか、この学校現場に行って、特別支援教育。ここで小中一貫教育もやっているということですね。","voiceIndex":81,"id":"exchange-032"},{"speaker":"林（宏）委員","kind":"質問","question":"この宗像市立日の里東小学校で特別支援教育の何か見るべきものがある、それから小中一貫教育もやっている、そういうことなんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4578#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":32056,"voices":109}},{"id":"h18-20060726-11","meetingId":"h18-cm07","date":"2006年7月26日","dateIso":"2006-07-26","committee":"自治制度特別委員会","time":"","status":"正式会議録","sourceType":"formal","overview":"自治制度特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"今の状況の中でメーカーとかにほとんど独占されているわけだけれども、そういう部分をなくしてやっていこうという検討をされたと思うんだけれども、その方法論は行き詰まったというか、ここの方法論の方がいいだろうということでこれが出てきたわけだけど、この状況をもう１回教えていただきたいなというのと、これが立ち上がってしまうと、先ほど出てきたように、当分の間と言うと、我々ずっと。","respondent":"岩崎環境清掃事業部長、中山資源循環推進課長","answer":"五十七、八歳の係長たちが民間の会社に結構引き抜かれていまして、役所ですと、定年退職しますと、再雇用しても相当給与水準が低いんですが、引き抜く方は「現給を保証するから５年間来てくれないか」とか。一組の解体、あるいは新たにつくる工場のネックになるのではないかですけれども、これは当分の間の中のアウトソーシングの具体的な形の中で、今回、先ほどもありましたメーカーへのアウトソーシングが始まっておるわけですけれども。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田委員","kind":"意見","question":"この経営計画は評議員会等の意見を踏まえてということなんですが、一つは、一組がどうやって意見を言っていくか。今の部分で、会社ができたとしても、メーカーからいろいろな対応があって、なるべく言いなりにならないようにやっていこうということだけれども、この一組の意見を言っていく部分と、各区の意向をどのように伝えていくかというのは、それはどういうふうに我々は理解すればいいのか。","respondent":"中山資源循環推進課長、岩崎環境清掃事業部長","answer":"ですから、まずはその経過を見て、ほんとうに効率的なのか、問題がないのかということから、また意見が出てくると思いますし、そこで問題ありということがありましたら、当然歩調をあわせていくわけですから、各区で出された意見。若干の補足みたいな、蛇足かもしれませんが、今回のこの問題をめぐりまして、全員協議会で、たびたびに渡っていろいろな資料が出されていろいろ説明を一組としております。","voiceIndex":8,"id":"exchange-002"},{"speaker":"石田委員","kind":"確認","question":"再度確認したいんですが、まずこの辺の議決があるわけですよね。各区の議決が必要だということになる。すると、それは１区でも反対だったらというところがあるわけですよね。私はなると思っているんですけれども、行政の皆さんはどうなんでしょうか。","respondent":"中山資源循環推進課長","answer":"もともと自区内処理を前提として、各区の方で持つべきだという東京都時代からの方針を踏まえて移管された中で、具体的にごみ量の減であるとか、それから各区のモデル工場設置が可能であるかという状況の中で、平成１５年の段階で、品川区としては工場がないわけですけれども。","voiceIndex":11,"id":"exchange-003"},{"speaker":"石田委員","kind":"質問","question":"私もそれを聞いたので、工場の建て替えとか、そういうぐらいのことを聞かないとそういう話もできないという大きなくくりはわかるんですけれども、そうすると、必ず最終的にはそこへいって判断しなきゃならない。だけど、そうすると結論は必ずそこになっちゃうのね。だから、これが一つの項目のクリアになるのかという、そこの見解を教えてほしいんですけど。","respondent":"岩崎環境清掃事業部長","answer":"それがどの時点でどう展開できるかというのは、まだ読めませんが、少なくとも、ある特定のところに大きい力がぽんとあって、それに依存せざるを得ないという状況からは、どんどん変わっていくんではないかというふうに思っています。","voiceIndex":13,"id":"exchange-004"},{"speaker":"土井委員","kind":"質問","question":"その結果として、別会社という形の会社がつくられていくわけですから、そこに可能性を大いに含んでいるわけで、そこら辺についてどのような考え方をもっているのかということと、それを実際に働いている皆さんとの間で、今の時点でどのように話が進んでいるのか、あるいは今後どうしようとしているのかということを伺えたらと思います。いろいろな権限が行使できるのは一部事務組合なんです。","respondent":"中山資源循環推進課長","answer":"先ほどご質問の、アウトソーシングの流れと、今、配置されている職員との関係、あるいは労使関係ですけれども、先ほど来出ております、いわゆる経営計画・経営改革プランのポイントとなるアウトソーシングにつきましては、かなり、今までの流れの中で。","voiceIndex":15,"id":"exchange-005"},{"speaker":"土井委員","kind":"質問・要望","question":"それを確認したい。そして、そのことは一部事務組合が技術確保ということについて十分、その会社自体がこういう会社なんだよということをよく認識した経営をしていっていただかないといけない部分もあるんじゃないかと思うので、そういうものをどこかできちんと位置づけをしていってもらわなきゃいけないんじゃないかと思うんですが、その辺はどうなんでしょうかということですね。","respondent":"中山資源循環推進課長","answer":"上下水道の情報を入れながら検討したかということについては、申しわけないんですが、ちょっとわかりません。","voiceIndex":17,"id":"exchange-006"},{"speaker":"土井委員","kind":"質問・要望","question":"場合によっては、変な言い方かもしれないけれども、今度はその別会社の方が完全にノウハウを持っていくことになっちゃって、本体の方は何もわかりません、別会社の言うとおりですということになっちゃってもどうしようもないものですから、その辺をきちっと、技術力も含めてどう伝承していくかというのは、きちんと考えた運営になるようにしていかなきゃならないんじゃないか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-007"},{"speaker":"三村委員","kind":"質問","question":"先ほどプラントメーカーのことで、寡占状態を回避するためというところを最初に言われているんですけれども、そういう寡占状態が起きると、どうしたデメリットが起こるのか。新会社で安くするというようなお話も出ていたんですけれども、委託料はどのぐらいの差があるんですか、その辺のところを教えてください。","respondent":"中山資源循環推進課長","answer":"それは、年間数千万の誤差だと思いますけれども、削減効果が出てくると、運営だけでもコストが下げられるというふうに考えています。","voiceIndex":20,"id":"exchange-008"},{"speaker":"林（宏）委員","kind":"確認","question":"確認しておきたいんですけれども、今、課長から説明を受け、部長からもいろいろ説明を受けているんですけれども、先ほどちょっと触れられたんだけれども、区議会というのは関与はないのかなという感じを持つんだけれども、私たちが、今、議論をしていること自体、興味本位でやっているだけの話で、今、いろいろな話が出たことが、どこにどういう形で伝わり、どういう影響が出。","respondent":"中山資源循環推進課長","answer":"直接に答えていないかもしれませんが、まずは一組の中に議会がございまして、議長も出てこられている中で、既に議論いただいておりますけれども、そういう形で各区議会で出される方が参加される中で、その辺のご意向も伝えていくというのが一つあろうかと思いますけれども。","voiceIndex":22,"id":"exchange-009"},{"speaker":"林（宏）委員","kind":"質問","question":"なぜ東京ガスに８,０００万というのを、４０％で言いなりにオーケーになるのかということだってあるわけですよ。東京ガスがなぜ、８,０００万ありきというのは、ここはおかしいと思う。説明では、東京ガスは、電力小売事業、電力会社としての立場を確保するために、この８,０００万、４０％というのが必要だということになっているんでしょうかね。ここでは議論できないと思うんだけどね。","respondent":"岩崎環境清掃事業部長","answer":"この文言の説明ですけれども、そういうことを言いたいためにこれを書いたらしいんですけれども、何か意味不明の文章であるということは、これはそのとおりであります。要するに、各区がもっと関心を強めていきたいという思いを書きたいということだったです。","voiceIndex":24,"id":"exchange-010"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"例えば、資本金のことで言うと、３％というラインをクリアすると取締役に入れるという、それが４だとすれば、１区６００万なんですよね。２３区で１億３,８００万。基本的なところで行くんですけれども、１ページ目をちょっと説明していただきたいんです。「現員不足により」と書いてあるんだけど、現在、一組ではどのぐらいの職員数で、どのぐらいの職員が足りないというふうに理解されているんですかね。","respondent":"中山資源循環推進課長","answer":"事務なんかであれば、その後の対応ですとか、結構すぐに構想をえがけるんですが、申し上げましたように、技術職の場合は、結構民間に引き抜かれたりという部分もあって、またそのままに流していくと、技術が流れてしまうというところまで行ってしまうということから、今回。","voiceIndex":26,"id":"exchange-011"},{"speaker":"林（宏）委員","kind":"質問","question":"じゃあ、これは品川区がつくったレジュメなんですか。一組がつくったレジュメなんでしょう。","respondent":"中山資源循環推進課長","answer":"一組でつくった想定資料で、あくまでも、繰り返しになりますが、その３枚目は、運転業務の委託に伴う人件費に主に着目した収支のことです。売電収支は別です。","voiceIndex":30,"id":"exchange-012"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"だけど、会社をつくるということなんだから、きちんと会社が運営されていくというところの根底は収入なわけですよ。できれば、区とのかかわりをもう少しきちんと持った形で会社設立していただければいいし、きれいな言葉で言えば、品川区としては、清掃事業ともっと強い絆を持っていたいなというのを要望して、長くなりましたから終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-013"},{"speaker":"三上委員","kind":"質問・要望","question":"そこら辺をちょっと教えていただきたいということと、それから、会社設立に当たって、何かちょっと、聞いていると、区長会のＯＢ区長が取締役に入る、もしくはそういう関連する人たちが何とか役員等に納まるための新会社をつくるためという、そんな雰囲気にもとれるような話にも受けとめられるような話ですね。そのあたりはどうなんでしょう。そこをお聞かせいただけますか。","respondent":"中山資源循環推進課長","answer":"ご報告申し上げたような維持管理費等が、年々上がる傾向があるやに伺っておるところです。ご質問２点目の役員構成等については、申しわけありませんが、その辺まではまだ伺っておりません。","voiceIndex":33,"id":"exchange-014"},{"speaker":"三上委員","kind":"質問","question":"そうすると、１８、１９年度の新規施設の稼動が、いろいろな意味でこの会社がカギを持っているということは、そのプラントメーカー系列の経費的な部分を抑えるための対抗手段というふうに考えているということは、それは単年度契約で一つずつ外していく、時期が来たら全部外していく、それで、この一つの会社にすべて持ち込もうというところまで考えているのかどうか。そういうのは明確に見えているんですか。","respondent":"中山資源循環推進課長","answer":"この積算よりは、退職者による技術者の不足の数は多くなりましたが、先ほどの、１９年度以降、年に１工場ずつ増やして６工場までという積算よりは、委託の必要な工場というのはもっと多くなってまいりますから、考えられるのは、一つはメーカーに発注する場合と。","voiceIndex":35,"id":"exchange-015"},{"speaker":"三上委員","kind":"意見","question":"会社にするという話だけが先行しているというのは、非常に、ある意味ではうさんくさいような話がいっぱい想像できるわけです。つくってどうするのかというような部分について、もうちょっと詳細な説明というものがされない限り、これ以上進んでいかないですよね。この程度の説明だけで説得できると考えているのかどうかということで、我々としてはあまり納得できない話になっています。","respondent":"中山資源循環推進課長","answer":"２３区の中で、こういう清掃事業が特別委員会にかけられているとかというのは把握してございませんけれども、移管の当初に、品川区もそうですが、例えばリサイクルに関する特別委員会を設けられて、集中的に審議されているのは結構ありますけれども、ある種常任だったり。","voiceIndex":37,"id":"exchange-016"},{"speaker":"三上委員","kind":"質問","question":"そこらあたり、もう少し各区の状況を調べていただけないでしょうか。もう一つ、これは電力を企業に売るということで、東京ガスがある程度出すんですけれども、電力を売るという話になってくれば、東京電力の方がはるかに、考え方としては出てくる話なのに、東京ガスを持ってきているというのは、そこらあたりの説明、されたのかどうか覚えていないものですから、ちょっと簡単に。","respondent":"中山資源循環推進課長","answer":"今回の東京ガスが、この間かなり天然ガスを活用した発電と言うものに力を入れ始めていて、こういう合弁事業の中で、東京電力を介してバックアップをもらうよりは安く調達をできるということのようで、ここに書いてある、組むことによるメリットというのは。","voiceIndex":39,"id":"exchange-017"},{"speaker":"原委員","kind":"意見","question":"先ほど部長の方で、この問題について各区がかなり意識が変化していますよというような話があったんですけれども、例えば４月にこの話が出てきたときに、東京ガスという形が議長会の中で出てきたわけなんですが、そのときに、なぜ東京ガスなのかという話も、実はあったんですよね。なぜ東京電力にならないのか。確かにそれは各区によって意識の差はあったわけですけれども、どうして東京ガスが出てくるのか。","respondent":"中山資源循環推進課長","answer":"ただ、もともとアウトソーシングの方向自体が、経営計画、経営改革プランの抜本的な改革の中で、議会のご意見も踏まえてつくってきたということもあり、そういうふうに言えばいろいろなとりようというのはあるように伺っておりますけれども、基本的な流れとして。","voiceIndex":41,"id":"exchange-018"},{"speaker":"原委員","kind":"質問・要望","question":"例えばその認識の中で、３年目以降は黒字に転換をするということ自体も、ほんとうにそうなのかどうかというのも、かなりおかしいし、今、表示されていますが、人件費の考え方にしても、これでいいのかどうかという意見も出されていますからね。その辺のところ、この中で指摘してもどうということでもないかもしれませんが、関心を持って、ここの中で資料を出していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-019"},{"speaker":"本田委員","kind":"確認","question":"官が随分大きい新しい会社ですけれども、東京ガスの退職者の受け皿、また、清掃一部事務組合の技術者ということではあるけれども、受け皿になるようなものだとすれば、高齢者のそういう進路も拡大するというのは大変結構なことではありますけれども、結局、一部事務組合に２３区は分担金を出して、一部事務組合が新会社に運転料としてお支払いをするという格好で、区と新会社との関係で言えば。","respondent":"中山資源循環推進課長","answer":"考え方としては、今回の運営にある分担金のありようと、ここの出資に対する考え方というのは、少し切り分けて、区の規模にかかわらず等しいかかわりを持っていくという形で示されていると思います。","voiceIndex":44,"id":"exchange-020"},{"speaker":"沢田委員","kind":"質問","question":"例えば、現在、一部事務組合でやっていればこそ、２３区が組合をつくって共同してやっていますけれども、会社という法人になれば、そこでまた一つ、株主という発言があったにせよ、４割は東京ガスが入ってくるわけで、２３区が意見を言い、経営に反映をさせていくというのはかなり弱まるんじゃないかという心配があるんですが、その辺に対しての見解はいかがでしょうか。","respondent":"中山資源循環推進課長","answer":"これは先ほどの議論でもありましたので、繰り返しのようになってしまうんですけれども、例えば今後、工場の運営委託だけじゃなくて、整備をどうしていくか、さっきのご質問にもあったような、基本的なフレームをどうしていくか、方針をどうするかみたいな。","voiceIndex":47,"id":"exchange-021"},{"speaker":"沢田委員","kind":"意見","question":"６：４で出資割合を分けるというけど、２３区の側は、工場を持っているところと持っていないところ、財政力のあるところないところ、いろいろ複雑だから、出資割合をどうするかによって意見がいろいろ分かれるわけですよね。まあ、膨大なものなので、きょうは絞って出したんだと思うんですけれども、そういうのを出すなら全部トータルで出して、「こうなんだ」という論理にしてほしいなと、私は思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":49,"id":"exchange-022"},{"speaker":"石田委員","kind":"確認","question":"確認だけさせてください。いろいろ話を聞いてきて、売電も入札になったから売れるんですよとか、６００トンぐらいの工場で数千万ぐらい削減できると思うんですね。それで、プラントメーカーの談合とかの抑止力になってきているんだけれども、これから１年目、２年目とあるけれども、ずっと委託をされる予定で書いてあるんですけど、これって、基本的には入札するんですよね。確認だけお願いします。","respondent":"中山資源循環推進課長","answer":"平成１８年度から始まった工場と、そして差引きの中で出てくる直営という形なんですけれども、そういう形で随意契約になるという可能性が考えられます。１点だけ。先ほど来の中で、業務を今回の会社に委託した場合については、ご指摘もあったように、試算しております。","voiceIndex":50,"id":"exchange-023"},{"speaker":"石田委員","kind":"意見","question":"そうすると、この収支の見通しの５年目、平成２３年は、三つは受託できると。それで、ほかのところは比較をするけれども、逆に言うと、今言ったプラントメーカーがやっているところの方が実績的に安くなったときに、その見直しというのは、実際、これだけでできているんだからこれでやってくださいというのか、契約更新の意味で、そっちの方だけもう１回入札をし直すのか、そこがあいまいになりませんか。","respondent":"中山資源循環推進課長","answer":"当初、立ち上げてやる段階の話と、ほんとうに行って、広がっていって、先ほどからあるように職員もどんどん減っていくと、アウトソーシングの流れは増えていくという中では、少なくともそういう形で随意契約をやっていくということを申し上げるつもりはないんですけれども。","voiceIndex":52,"id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5600#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=11&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":31386,"voices":56}},{"id":"h18-20060726-16","meetingId":"h18-cm07","date":"2006年7月26日","dateIso":"2006-07-26","committee":"街づくり特別委員会","time":"午後１時０２分～午後３時４７分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"安心・安全のまちづくりに関すること」のうち、「公園整備における安全面での考え方について","agenda":"安心・安全のまちづくりに関すること」のうち、「公園整備における安全面での考え方について","exchanges":[{"speaker":"林（和）委員","kind":"質問","question":"品川の公園は２１９カ所あるということで、先ほどの説明もございましたけれども、古い公園はものすごいうっそうとしているわけで、今も見たとおりであったと思う。ここに１ルクス以上の確保としてあるということだけれども、これは全部の公園でそれだけの確保がされているんでしょうか。していると書いてあるけれども。","respondent":"松代管理工事課長","answer":"ここにありますように、基準が１ルクス以上ですので、当然のことながら、造成時には１ルクス以上の照度が保てるように設計をしますし、今日ご覧いただいたような、設計時からかなり植栽が繁茂してうっそうとしたところでも。","voiceIndex":10,"id":"exchange-001"},{"speaker":"林（和）委員","kind":"質問","question":"まして、夏の場合はうっそうとしてくるわけですので、夜なんか本当に怖いというか、非常にその当時から物騒な状況なところがどの公園にもあるんです。ですから、１ルクス以上の確保をされているというから、改造するときには、それはそういう設計をするということですけれども、それだけ確保されているのかどうなのか、巡回しているとはいいますけれども、その点はひとつよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-002"},{"speaker":"菊地委員","kind":"質問・要望","question":"例えば、最初、見せていただいた西霧ケ谷公園ですか、あそこは防災広場と、それと昔からある通常の公園が併設をされている感じになっていますけれども、要は、防災広場と公園の設定って当然違いますけれども、どういうイメージで安全面を確保していけばいいのかというときに、どの公園をイメージすればいいのかがよくわからなかったので、ちょっとその辺をもう少し教えていただきたい。","respondent":"松代管理工事課長、藤田道路公園課長","answer":"そういったものをもとに設計をし、日常の管理をしてきたと思ってあります。そういったことから、今、４カ所ほどご覧いただきましたが、これは安全面で基準が劣るとか、危険であるというような認識はございません。夜間パトロールについてはだれが行っているのかですけれども、私どもから警備会社に委託をして実施をしております。","voiceIndex":13,"id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"ここに書かれているのは、通常やっている安全パトロールのことなんですか。","respondent":"松代管理工事課長","answer":"防犯対策の地域の監視パトロールということで警察官ＯＢというような記述のものは、生活安全パトロールとしているものをここに記載したものです。","voiceIndex":16,"id":"exchange-004"},{"speaker":"菊地委員","kind":"質問・要望","question":"ですから、もちろん地域の皆さんの意見を聞くというのは極めて重要な部分なんですけれども、１つにはやっぱり区としての公園づくりのイメージというのを、かなり的確に地域の中に知らせていきながら、意見を聞いていくという方法をとっていかないと、防災広場は防災広場としての機能が必要ですから、のっぺりした形にならざるを得ないんですけれども。","respondent":"藤田道路公園課長","answer":"そういった公園については、やはり私どもとしても巡回をして注意をして、夜遅くまで騒いでいることのないようにというような形で注意をしていきたいと考えておりますので、そういった公園は幾つかありますので、それをピックアップして、スケジュールを組んで。","voiceIndex":18,"id":"exchange-005"},{"speaker":"菊地委員","kind":"質問","question":"今、あわせて聞けばよかったんですけれども、そこの予算の部分というのはどこから出てくるんですか。","respondent":"藤田道路公園課長","answer":"私どもの公園維持の費用の中から行っているものです。","voiceIndex":20,"id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"それと、雑草がわーっといっぱい伸びている状況もありましたし、それは日常的にいろいろな地域の中で見かける光景ですけれども、そういう管理が今、どういうふうになっているのか、時季ですから旺盛にわーっと伸びちゃうのは当然で、抜いたりとか、調整したりするというのはしておられると思いますけれども、それにもっと先んじて伸びちゃうというのはわかるんですけれども。","respondent":"松代管理工事課長、藤田道路公園課長","answer":"私どもにとっても非常にありがたいことだと思っておりまして、そういったものに対しては、すぐにできるところから対応してまいってきております。あるある点検隊、こちらはまさしく地域との連携を図りながら、地域の人にも力を借りたい、アドバイスをいただきたいということで行っていこうと考えている事業ですので、そういった中でさまざまな情報をいただきながら。","voiceIndex":22,"id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"それと、そういう点でも、本当に安全を守るというのは、こういう時期に、とりわけこれから夏場になってくると、特に外に出て歩く、夜間でも出て歩く状況が多くなってきますので、そういう意味での危険、安全を確保するという、それと防犯対策をとるというのは、やっぱり人の目が届くとか、明るさが届くということが大事ですから、多少公園の維持だとか、そういうものにお金はかかりますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-008"},{"speaker":"藤原委員","kind":"質問","question":"今日、公園を４つ見せていただきましたが、公園は区の施設ですが、これは２４時間、中に入っていい、そして遊んでもいい施設だと区は考えているんでしょうか。","respondent":"松代管理工事課長","answer":"おっしゃるように、基本的には、今つくっている公園はすべて２４時間対応型の公園として設計し、管理をしているものです。１カ所だけ、違うとすれば、しながわ区民公園が閉鎖公園となっております。失礼しました。それに池田山公園の２カ所を含む全部で７カ所となります。","voiceIndex":26,"id":"exchange-009"},{"speaker":"藤原委員","kind":"質問","question":"それは便所ですよね。だけれども、その辺に関しまして、先ほどの課長の答弁で不審者から声をかけられた事例はありますというような現実問題がある中で、公園内にあるあの個室の中に、もし連れ込まれたならという思いがあるんですけれども、そういう意味において、便所は個室なので、あの便所というものの安全面というのはどのように考えているんでしょうか。","respondent":"藤田道路公園課長","answer":"トイレにおけます安全管理といったような視点ですけれども、トイレそのものは、委員がご指摘のとおり当然本当に個室になってするような施設ですから、それを開放してしまうということはやはりできないと考えています。","voiceIndex":28,"id":"exchange-010"},{"speaker":"藤原委員","kind":"質問","question":"だから、例えばあの中に、あるじゃないですか、便所の上に赤いサイレンみたいなのがくるくる回るのとか、品川じゃないかもしれないんですけれども、どこかの公園で見たことがあるような覚えがあるんですけれども、何かそういう、もしあそこに不審者によって連れ込まれた場合に、何か外に知らせる方法、自分の肉声だけじゃなくして、知らせる方法みたいなというのはできないんですか。","respondent":"松代管理工事課長","answer":"そういった中で、つくる以上は利用しやすい、特に女性の方等は利用はなかなか低いということも掌握しておりますので、女性等の利用がしやすいような感じ、また、以前から配置していますトイレの配置状況、必要に応じて、本当にすべて公共がつくるトイレが必要なのか、また。","voiceIndex":30,"id":"exchange-011"},{"speaker":"藤原委員","kind":"質問","question":"次は安全対策で伺いたいんですけれども、実は偶然、まちづくり事業部長と私が平成１４年に海外調査に行かせていただいて調査をさせていただいたときに、緑化ということで、アメリカだったんですけれども、多くの公園を調査させていただいたんですけれども、そのときにすごく印象に残っているのは、公園がすごく高齢者の憩いの場所になっているんだなとものすごく感じました。","respondent":"松代管理工事課長","answer":"施設的には、一番やりたいと思いますのはゲートボールだと、そういったもので使えるようなもの、また、健康遊具というようなことでありますが、高齢者への安全、防犯というところで、正直言いまして、特にそういった施設的なものはございませんが。","voiceIndex":32,"id":"exchange-012"},{"speaker":"築舘委員","kind":"意見","question":"遊具の安全ということで、昔は公園というのは滑り台とブランコと砂場がなければということで、大体その３つがあったわけですけれども、最近はそういうことではないということで、遊具も幼児向けと児童向けでは違いを区別していますよというようなことが今、ご説明があったんですけれども、具体的に最近の公園の、児童遊園はもちろん、そういう遊具を有している公園において、特に幼児向け。","respondent":"松代管理工事課長","answer":"委員がご指摘のとおり、昭和４０年代等の都市公園法に基づく公園のつくり方というのは、３種の神器といいまして、砂場と滑り台とブランコというような形でつくってまいりました。","voiceIndex":34,"id":"exchange-013"},{"speaker":"築舘委員","kind":"質問","question":"遊具の事故というか、そんなに大きな事故はないでしょうけれども、いろいろそういった形での過去のことを参考にして、そういった落下時の衝撃を吸収する舗装というんですか、それが必ず敷いてありますよとか、あと、そういう形で過去のいろいろな教訓というか、そういうことでの安全のための新しいものを取り入れをしていると思うんです。その点で何かありますか。","respondent":"松代管理工事課長","answer":"これは昭和５０年代、６０年代、それまでは鉄製遊具の遊具が多かったんですが、そのほかの木製、木のぬくもりといいますか、木の風合いを生かした木製遊具が非常に好まれまして、これを多く設置した例があります。","voiceIndex":36,"id":"exchange-014"},{"speaker":"堺委員","kind":"質問・要望","question":"ですから、これをそっくりそのままうのみにすると、いろいろな人たちがいろいろな視点からそういう点検をされるのかなというような気もするんですけれども、場合によっては専門家の目も必要かもしれませんが、そういう利用する側の人たちが、自分たちの公園を良くしていきたいから見ていただくというのも、ある意味では最も大切な部分のような気もするので、それも含めて。","respondent":"藤田道路公園課長","answer":"安全点検ボランティアの施設点検等の関係ですけれども、私どもは遊具あるいは公園の施設の点検、それはあくまでもそういった施設の点検のプロにやってもらう話であって。","voiceIndex":38,"id":"exchange-015"},{"speaker":"堺委員","kind":"質問","question":"それとしながわ中央公園だとか、林試の森公園だとか、そして今度新しくできる東品川海上公園、それからかいじゅう公園ですか、大きな公園か小さな公園かによってまた全然変わってくるだろうと思っているんです。そういう広い公園なんかについての夜間パトロールというのは、どういうふうなパトロールの仕方をされているんでしょうか。","respondent":"藤田道路公園課長","answer":"夜間閉鎖をしている公園については、基本的に巡回をするということではありませんので、しながわ区民公園等については、閉鎖をすることで安全性を保っていると考えているところです。","voiceIndex":40,"id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"そのうち粗暴犯とか、風俗犯だとか、そういった直接身体的な危害を加えられる被害というのは５５％で、窃盗的な被害というのは４５％だというんです。つまり子どもが、私たち大人が想像しないような、越えるような危険な環境の中で暮らしているんだという認識を私たちは持つ必要があるのかなとちょっと思ったんですけれども、その辺の見解というのはどうでしょうか。","respondent":"金子生活安全担当課長、藤田道路公園課長","answer":"恐れ入ります。質問の中で、公園あるいは時間帯、そういったものの特筆してデータ的なものを出しているものというのについては、今のところちょっと承知しておりません。今、８・３運動とかいろいろありますので、地域のいろいろな目の中でお子さんを守っていくということが大切なのかなと考えています。","voiceIndex":42,"id":"exchange-017"},{"speaker":"南委員","kind":"質問","question":"この調査をしたのはどこの地域か私もわからないですけれども、事実あるということで公式に出されている文書ですので、したがって品川区内でやっぱり絶対ないと、そういうことはこれからも含めてあり得ないことだと思うので、どういうふうな環境整備をしていくかという視点での調査というのはしていく必要があるんじゃないかなと私は思うので、その辺の見解を教えていただいて、終わりにしたいと思います。","respondent":"松代管理工事課長","answer":"ですから、事例で挙げられたような引き込まれるとか、そういった引き込まれやすいような環境をつくるとか、そういったものがないようにつくりますし、また、管理をしていく、そういったものも今後続けていきたいと、このように考えておるところです。","voiceIndex":45,"id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひそういう声を聞く必要があるんじゃないかなと私は思っているので、ぜひ積極的に、いつの時期になるかわかりませんけれども、そういうことにも取り組んでいただいて、子どもの角度から安全を確保できるような、そして品川で育つ子どもが１人もこういう危険な目に遭わないようなまちづくり、公園づくりを目指していただきたいということを強く要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-019"},{"speaker":"須貝委員","kind":"質問・要望","question":"それが、やはりそのような誤解をされちゃった方がいたので、その辺も考えますと、何か要望がありましたら、道路公園課にご一報くださいでもつけておけるのかどうか、それとも過去にそういうことをやったけれども、いろいろ何か問題点があったのかどうかちょっとわからないんですけれども、その辺のご見解をお聞かせください。","respondent":"藤田道路公園課長","answer":"ただ、大きな公園についてはそういったような記載をしているような公園もあります。私どもは特に道路公園課にということではなく、品川区にご連絡をいただければ、そういったことで声はきちんと伝わってきますので、そういった中で声を寄せていただければなと考えております。","voiceIndex":48,"id":"exchange-020"},{"speaker":"須貝委員","kind":"質問・要望","question":"なかなか一般の方が３７７７－１１１１というのはちょっととっさに皆さん出てこないということがあるので、もしどこかに連絡先等を出しても差し支えないようでしたら、公園を利用なさっている方が気軽にちょっとご要望、ご意見を言えるということで、取り組んでいただければありがたいなという要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-021"},{"speaker":"大西委員","kind":"確認","question":"１点だけ確認というか、私もちょっとど忘れしているかと思うんですけれども、利用者の面からした安全ということで尋ねたい。この区じゃないんですけれども。座る部分のところでのものというのは、もう今は既にその木製のかたいものから全部交換というか、それはなされているんでしょうか。","respondent":"藤田道路公園課長、松代管理工事課長","answer":"木がやせてきて、だんだんもう使えなくなるようなときには、順次そういったものに取りかえていっているということで、さく自体は、私どもの公園、基本的にはどこにもすべてついておりますので。そういった意味では、若干遊具的には古いものもありますが、安全面に関しましては、その一斉点検ですべて補修等をしておるところですので、今あるものがちょっと古いから危険だというものはないと考えています。","voiceIndex":51,"id":"exchange-022"},{"speaker":"大西委員","kind":"質問・要望","question":"そういう部分から、衝突があった場合に、私はすごいその強度というんですか、が、対象となる子どもに当たるということを危惧するので、古くなったらかえているはずだとかということではなく、私はそのものがもし木製のものであったとすると、そこに危険性が予見されるものがあると思うので、点検がなされているかなされていないか、交換がなされているかなされていないか、できれば確認をしていただければと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-023"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"空き交番の関係でちょっとお尋ねしたいんですけれども、いいですか。先だって、急遽報告いただいて、そして、品川区内で５カ所空き交番の廃止をしていくということでご報告があったんですけれども、その後は新聞報道でも廃止交番にＯＢを配置するとかということで、若干方向が変更している部分があるみたいなので、その後の状況をちょっとわかっている範囲で教えていただきたいと思うんですけれども。","respondent":"金子生活安全担当課長","answer":"新聞報道に関しましては、８８カ所、これを防犯拠点等として活用する案がありますけれども、これは警視庁で現在明らかにしているものに関しましては、まだ地元と調整する中で今後変更する可能性もあるということで。","voiceIndex":57,"id":"exchange-024"},{"speaker":"南委員","kind":"質問・要望","question":"それの確認を改めてしたいのと、もう１つは、交番廃止をする理由がどういうことだったのかということを、ちょっとこの間時間がない中で報告をいただいたので、改めて伺いたいし、品川区内で現在、この間の公表されたものは、水上警察も含んだ５つの警察署からそれぞれ１カ所ずつ廃止する交番を出してきているわけですけれども、それが今現在どういうふうになっているのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"わかりました。しかしながら、品川区内の空き交番を５カ所廃止するということは、これはこれで発表があって、それは生きている話ですよね。どこまで、５カ所を全部廃止するのかどうかということはこれからの検討だと思いますけれども、しかし、この間の発表はそのままずっと続いているということですから、そういう点について、やっぱり地域では非常に心配の声が出ていると思うんです。２点です。","respondent":"早津区民生活事業部次長","answer":"空き交番が選ばれた理由ということであれば、これは前回の報告のときにも簡単にご説明いたしましたが、検挙率、犯罪認知度、それから１１０番通報の件数等を踏まえて、件数の相対的に低いところが対象となったというふうに報告を受けているところです。","voiceIndex":62,"id":"exchange-026"},{"speaker":"南委員","kind":"質問・要望","question":"今、注視したいというお話で、それはそれとして今の時点では受けとめざるを得ないと思うんですけれども、先ほどもちょっと申し上げたように、いろいろな地域の状況がありますので、やっぱりその辺は注視をすると同時に、区民の側のいろいろなご意見なんかも積極的に聴取をしていただいて、そして一定の必要な時期に、警視庁からの一方的な報告で終わらせないで、やっぱりこうじゃないか。","respondent":"早津区民生活事業部次長","answer":"事態を注視しているというのは、区としてもどういうようなことをするかということの検討を今後してまいりますと前回も申し上げました。その形に変わりはございません。","voiceIndex":64,"id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6330#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":26176,"voices":66}},{"id":"h18-20060727-14","meetingId":"h18-cm07","date":"2006年7月27日","dateIso":"2006-07-27","committee":"行財政改革特別委員会","time":"午後１時０３分～午後３時０２分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を44件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"民間委託等に関すること","agenda":"民間委託等に関すること","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"民間活用業務のほうで、人材派遣とか、そういったところがここの職員数に入っているのではないと思うんですが、人材派遣の人数とか、これはどういうふうな関係で決められているのかということを、ちょっと大まかに教えていただきたい。保育園のところで、具体的な内容になるので、答えは、もしいただければお願いしたいんですが、特別支援保育というのと保健業務というのがわかればお願いしたいと思います。","respondent":"榎本人事課長、堀越行財政改革担当課長","answer":"保育園につきましては、それぞれこちらに書いてある育児休業代替、病気休業代替が６名、オアシスルームのほうで２０名とか、それぞれの業務について、夜間保育等の部分を含めて、全部で１１２名という形で入っています。特別支援保育のところで、障害児の保育に対応するという形の部分に、人材派遣の方も補助として入れているです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"川西委員","kind":"質問","question":"細かいことですみません。シルバーセンターなんですけれども、受付業務はシルバー人材センターがやっていたのを覚えているんですが、この実態について、清掃業務との関係を。どういうところに、どういうふうに委託されているのか教えてください。","respondent":"堀越行財政改革担当課長","answer":"シルバーセンターの委託なんですけれども、これはシルバー人材センターのほうに委託をしております。業務委託の内容ですけれども、受付を含めて、清掃等、そういったものについて包括的に近い形で委託をお願いしているというものです。","voiceIndex":8,"id":"exchange-002"},{"speaker":"川西委員","kind":"質問","question":"続きで申しわけないんですが、児童センターの清掃業務は、シルバー人材センターだけではなくて、西大井にある障害者施設に委託していると思うんです。その清掃業務の分担はどうなっているんでしょうか。","respondent":"堀越行財政改革担当課長","answer":"概括的になろうかと思いますけれども、清掃等の業務委託については、シルバー人材センターにもう１社、民間の会社と、品川総合福祉センターにもお願いしていると聞いております。","voiceIndex":12,"id":"exchange-003"},{"speaker":"伊藤委員","kind":"確認","question":"確認といいましょうか、まず、直営の施設はこれだけでしょうかという、単純な質問が一つ。それから、ここでも、民間活用業務をされていますけれども、当然、契約の見直しとかを、例えば年度を区切ってやっているでしょうから、何年間も同じ業者ではないと思うんですが、その契約の見直しをどういうふうにされているかということを、お聞かせください。","respondent":"堀越行財政改革担当課長","answer":"民間委託の進め方という形で、今年度より検討を始めておりまして、現行の民間委託の進め方がどうなっているのか、例えばその契約のあり方とか、そういった面も含めまして、もう一度整理しようという形で、今、庁内で調査をしておりまして、今後。","voiceIndex":14,"id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問","question":"ほかになぎさ会館等があったということですが、確かに業務委託に近い形でなさっているということは聞いておりますので、むしろ、その契約のところについて、要は見直しをしているんですかということをお伺いしたわけです。何を言いたいかというと、例えば同じ業者がずっとその業務を引き継いでやっていくという安定した部分もあります。","respondent":"堀越行財政改革担当課長","answer":"これからの考え方につきましては、指定管理者制度ですとか、今回の公共サービス改革法ですとか、いろいろ規制緩和の流れが出ておりますので、そういった社会経済状況の変化といったものをにらみながら、我々としても、今までの区が委託をしている業務とか。","voiceIndex":16,"id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問・要望","question":"最後に確認したいのは、今度は、区側がプロポーザルを受けるに当たって、皆様方のレベルアップをし、そして、適切なプロポーザルの方法を決めていくノウハウの蓄積とか、その部分は、ある意味、それこそ外の方々を講師に招いて、会社経営のノウハウとか、今までの公務と違った素質が相当求められてくると、私は思っているんですけれども、そのことについての対処を、最後にお聞かせください。","respondent":"堀越行財政改革担当課長","answer":"先ほど申し上げた民間委託の進め方の検討という部分では、そういった面も課題であると認識しながら、やっていきたいと思っているところです。","voiceIndex":18,"id":"exchange-006"},{"speaker":"松澤委員","kind":"質問・要望","question":"直営施設一覧の中で、児童センター、保育園、図書館、過去の行財政改革特別委員会の中でも、相当個別にいろいろな議論があったところなんです。児童センターは、常勤職員９０人、保育園は６２７人、図書館は７１人という数字が出されていますけれども、過去の、何年か前からの職員数の動きについて、その数字を明らかにしていただきたいと思います。","respondent":"榎本人事課長","answer":"平成１３年度からなんですけれども、そのときに職員が１１２名という形になって、残りを非常勤で補うという形にしてきましたけれども、非常勤制度では、なかなか人の流動があって難しいということで、平成１６年度から窓口業務委託をとるということで、その際に。","voiceIndex":20,"id":"exchange-007"},{"speaker":"松澤委員","kind":"質問","question":"保育園で一番問題になるのが、よく言われる０歳児、あるいは産休明けの１人当たりの単価がどうかと。子どもを１人預けることによって、当時は五十何万円かかっていた。今、職員数が減っている中で、１人当たりの単価そのものがどのように移動しているのかということ。今、パソコンもできない人なんてほとんどいないぐらい。その辺もつかんでいるのかということもお聞きしたいと思います。","respondent":"堀越行財政改革担当課長、榎本人事課長","answer":"年齢別のデータは持ってないんで申しわけございませんが、児童１人当たりの平均の運営経費、平成１７年度で１８万２７８円です。ちょっと０歳児については、手元にございませんので、申しわけございません。それからあとパソコン研修も毎年継続してやっておりますので、その中でスキルアップを図っているという状況です。","voiceIndex":22,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"若干基本的なことを伺いたいんですけれども、人材派遣のことについて、区とどういう契約になっているのか、教えていただきたいんです。おそらく最近かなとは思うんですけれども。同時に、ここには児童センターと保育園とありますけれども、ほかの事業のところで、人材派遣があるのか、ないのか、これだけなのか、あわせてちょっと総合的に教えていただけますか。","respondent":"榎本人事課長","answer":"人材派遣ですけれども、平成１７年度から実施しているのが現状です、平成１８年度は２年目という形です。","voiceIndex":25,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"これ見ますと、非常勤の方が０になっていると書いてあるので、その関係がよくわからないんですけれども、そこをちょっと教えていただきたい。それから、すまいるスクールのほうでも、人材派遣の人がいると伺ったんですけれども、それは人材派遣ではないのかどうか、もう少し教えていただけますか。","respondent":"榎本人事課長","answer":"児童センターですけれども、委員お尋ねの非常勤職員と派遣職員がいたというのは、平成１７年度は、実際上、非常勤職員が３４名おりまして、平成１８年度になってそれが０という形になりましたので、その間は、人材派遣の方と非常勤職員の方が一緒にいて、今年からは。","voiceIndex":27,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"ちょっと人材派遣のことがよくわからないので、もう少し詳しく伺いたいのは、要は、一方で運営業務のほうを民間委託にしていますよね。先ほどの話ですと、年間契約ということになるんでしょうか。先ほど、人数のところで、児童センターは２６人、保育園１１２人とありましたけれども、ほかに人数以外につかんでいるものがあるのか、ないのか、教えていただけますか。","respondent":"榎本人事課長","answer":"大体、何月で幾らという形で、実態上、進めているところです。","voiceIndex":29,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問","question":"もう一つ別の角度で伺いたかったんですけれども、児童センターのほうがわかりやすいんですけれども、非常勤職員が０になって、若干人数として減っているんでしょうけれども、その分、人材派遣が入っているわけですが、区の非常勤職員をやめて、募集もやめて、その分、人材派遣会社のほうで穴埋めすることにした理由を教えていただけますでしょうか。","respondent":"榎本人事課長","answer":"平成１６年度のときに、特に保育園、児童センター、すまいるスクールで非常勤職員の人数をかなり多く抱えるという形になりまして、そのままずっと推移すると、非常勤職員だけで１,０００名を超えるような形がありまして。","voiceIndex":31,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"区で非常勤職員を雇用いたしますと、当然、社会保険分の負担がありますよね。１,０００人を超えるのは是正するという話の中には、結局は区のコストを下げるということが一番の理由ということで、よろしかったんでしょうか。一般的な会社で、人材派遣を受けると税負担が軽くなっていいんだという話は、よく伺うんですけれども、それと同じような考え方でいいのか、どうか、そこだけ教えてください。","respondent":"榎本人事課長","answer":"それからもう一つは、これは実際には東京都全体の労働組合の関係なんですけれども、やはり非常勤職員の労働組合がありまして、そちらのほうから、そういう継続雇用するんであれば、きちんとした雇用なのかと、継続的に仕事があるんだったら、その分は整理して。","voiceIndex":33,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"児童センターと保育園の人材派遣のところが、人数を聞いたら、大分増えている。本来、私は、ここのところは直接人にかかわる部分で、同じ仕事を違う雇用形態で仕事をしていくのは、チームワーク上、なかなか難しいと思っているんですが、本来であれば常勤職員を確保すべきところであると思うんですが、ここのところの人材派遣を取り入れている基準がどうなっているのか、ちょっと具体的に教えてください。","respondent":"堀越行財政改革担当課長、榎本人事課長","answer":"それからもう一つの窓口業務については、児童センター２５館あるうち、運営業務を委託している４館を除いた２１館ですとか、今、在宅子育ての支援といった施設もつくっておりますので。人材派遣のほうの基準ですけれども、平成１７年度から入れてきたところで、実際上、どういう形でやっていくのが一番いいのかというのは、これから見直しも常にかけていかなきゃいけないと思いますけれども。","voiceIndex":35,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問","question":"あまり内容的な基準というのは、仕事に対しての一つひとつの基準というのはないんでしょうかね。言ってみたら、それこそ経費のところで決まるんですかね。その辺の基準を、もうちょっとわかりやすく教えてほしかった。例えば労働時間とか、休暇とか、賃金とか、社会保障制度、どういう中で派遣をされているのかというところまでチェックができているのか、どうか、ちょっと中身も教えてください。","respondent":"榎本人事課長","answer":"要は、正規職員で入ってしまうとなかなかやめられないという部分もあったりしますので、そういった意味での考え方というのも、一つはあるのかなと感じております。","voiceIndex":38,"id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問","question":"区と同等ということですが、私はさっき、労働条件で、賃金を含めたわけですけれども、社会保障のところも同等なんでしょうか。","respondent":"榎本人事課長","answer":"労働時間という意味では同等ですけれども、社会保険等につきましては、人材派遣会社のほうでやるというのが人材派遣法の基本になっておりますので、保険等社会保障の関係につきましては、人材派遣会社のほうで、きちんと法にのっとった形で保証されていると考えています。","voiceIndex":42,"id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"当然、そういう答弁が返ってくると思いましたけれども、同じ仕事を実際にしている人たちの間に、賃金格差があるわけですよね、実際的に。そういった面で、相手の会社の条件の中で、こちらが求めているだけですという部分では、なかなか収まらない。その辺については、さっきも言いましたけれども、自治体としての社会的責任という部分で問われていくものだと思うんですが、この辺はどうでしょう。","respondent":"本間総務部長","answer":"そういう意味で、労働者は保護されているです。ただ、どういう条件で働くかは、労働者個人が自分の意思で決めるということが基本になっているということで、ひとつご理解をいただきたいと思います。","voiceIndex":44,"id":"exchange-017"},{"speaker":"飯沼委員","kind":"意見","question":"ここのところ、労働法制のところが次々に規制緩和をされて、さっき、外国の例で、二十五、六歳までなかなか一生の仕事を決めないと、だから、日本でもそうやってフリーターというか、正規じゃない時期があってもいいのではないかみたいなご答弁があったんですけれども、本人がそれを望んで、自分で選んでる道だったら、十分納得がいきますけれども、今はそうじゃないんですよ。これは意見で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":46,"id":"exchange-018"},{"speaker":"須藤委員","kind":"提案","question":"ですから、きょうの委員会では、ちょっと違うところだと思っています。先ほど、松澤委員からあったように、行財政改革で、議会からいろいろ提案させていただきましたことで、それぞれの結果、努力をされていることには敬意を表したいと思うんです。一度、行財政改革特別委員会の中でも、その辺の歴史も１回勉強しておかないと、いきなりこれだけを見てというのもどうかなと。わかる範囲で結構です。","respondent":"堀越行財政改革担当課長","answer":"もし民営化する場合には、よその区は民営化したけどどうなんだという話がありますけれども、よその自治体ですと、すみません、個人的な考えになるかもしれませんけれども、いろいろ財政的に問題があって、それが主な理由で委託化しているというような部分もありますけれども。","voiceIndex":47,"id":"exchange-019"},{"speaker":"須藤委員","kind":"質問・要望","question":"今ここで、主な直営というのがここに出ているだけではないと思う。極端に言えば、文教委員会に所属したんだけれども、学校なんかも区立、区営で小中一貫とかいろいろやっていますよね。今、僕らが見ていて、もう少し使い勝手を。やはり区民ニーズにほんとうに合うかどうかということに照らしていってもらうというような考え方をしていただきたいと思いますが、いかがでしょうか。","respondent":"新美企画部長","answer":"シルバーセンターだけで対応というわけにもいきませんが、その辺、団塊の世代対応を考える中で、従来のシルバーセンター、その他文化センター、あるいは、最近出ておりますいろいろな小規模な跡施設等々を組み合わせながら、活動の場をシルバーセンターだけではなく。","voiceIndex":49,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"今、ちょっと議論を聞いていまして、一言だけ指摘させていただきたいんですけれども、効率化という名のもとで、今、企画部長から話がありましたけれども、短時間、短期間の労働者が、この間、急速に増えたことが、今大きな社会問題になっている格差社会の根底をつくってきた。そこをどう受けとめているのか、そこだけちょっと伺いたくて質問いたします。","respondent":"新美企画部長","answer":"民間委託も完全な非正規化とは限らないと考えていますので、あまり全体論と、個別の事例については個別の事例をきちんと見ていく必要があろうかと考えています。","voiceIndex":51,"id":"exchange-021"},{"speaker":"中島委員","kind":"質問・要望","question":"この中で、さっき図書館で、平成１３年度に非常勤制度をとられて、そして平成１６年度から窓口業務に変わられたということでしたが、ここら辺のところを、さっき説明を聞きもらしちゃったので、どうしてこうなって、非常勤制度のときと、今の窓口のところとどういう違いがあるのかということが、ちょっと認識できなかったので、すみません、よろしくお願いします。","respondent":"榎本人事課長","answer":"実際には、非常勤職員の方の出入りがかなり激しくて、少し経つとやめて、また新たな非常勤職員を入れて教育をして、そこまで教えるとまた次の人にかわってという部分がありまして、なかなか継続的な形ができないということが１点ございました。","voiceIndex":53,"id":"exchange-022"},{"speaker":"中島委員","kind":"質問","question":"ほんとうに品川区の図書館は大分改革が進んでいるなと、私も感じているところなんです。特に、先ほど、企画部長がおっしゃいましたように、団塊の世代の活用ということで、そういった方たちがほんとうに生き生きと区内の中でまた働ける場というのも、探し出せばもう少しあるのかなと思うところなんですが、その辺のところはいかがでしょうか。","respondent":"榎本人事課長","answer":"この中で、実際にどこまで広げられるかということはありますけれども、地域の中の図書館という位置づけにして、そういうサービスをしていきたいと考えております。","voiceIndex":55,"id":"exchange-023"},{"speaker":"中島委員","kind":"質問・要望","question":"私も、ここにレファレンスなんかがありますけれども、本が好きな方も団塊の世代の中にはいらっしゃるかもわかりませんし、６０歳代というのは学べばまだまだ開けるし、いろいろな脳の活性化もできると思います。そういったこれからの方たちに希望が持てるような、そういった施策もいろいろ取り入れていただきたいと要望していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-024"},{"speaker":"藤田委員","kind":"質問","question":"小さいことと、大きいことと２点、お伺いしたいと思います。歴史館の中で、民間活用の項目をずっと見てみますと、ここには窓口受付業務が記載されていないんですが、それは何か理由があるのか。非常勤、常勤の人で対応して十分なのか、その辺を、まずお伺いしたいと思います。","respondent":"堀越行財政改革担当課長","answer":"特に委託というようなことは聞いておりません。それから、常勤職員が４名で、非常勤職員については、館長が１名と、学芸員が３名という形になっております。今のところは、そういうような形と聞いております。","voiceIndex":58,"id":"exchange-025"},{"speaker":"藤田委員","kind":"質問","question":"担当所管がそのように言っているということであれば、それはそれで理解しますけれども、やはり私も須藤委員と同じように、品川文化振興事業団があるわけですから、そこから派遣をするとか、何らかの方法があるんではないかと思っています。答弁は結構です。ですから、シルバー人材センターの中で一つの人材派遣部門というものを設けても、私はいいんじゃないかと思います。","respondent":"日下部企画財政課長","answer":"最近になりまして、確かにシルバー人材センターにつきましては、直接人材センターとの関係の中で作業をされる、それが一般的ではありますけれども、今、ご指摘のありましたように人材派遣というような部門を新しくつくって。","voiceIndex":60,"id":"exchange-026"},{"speaker":"藤田委員","kind":"質問・要望","question":"区としても、これから団塊の世代の方々に対応すると言われています。ただ、ボランティアだけではなくて、やはり再就職といいますか、仕事としてつながるような方法も考えていく、大事な柱ではないかなと思いますので、これについても要望して終わりたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-027"},{"speaker":"西本副委員長","kind":"質問・要望","question":"二つほどお聞きしたいと思います。指定管理者制度の中で、まず教えていただきたいんですが、契約が５年間等々あるわけですけれども、おそらく１年ごとにチェックが入りということで、次年度の予算等々、契約金という形になると思うんですが、これは基本的に、区のほうからの業務内容が変わらなければ、その契約金は変わらないという形なんでしょうか。","respondent":"堀越行財政改革担当課長","answer":"それに伴って、指定管理の料金についても変わってくるという形になると認識しております。","voiceIndex":63,"id":"exchange-028"},{"speaker":"西本副委員長","kind":"質問","question":"そうしますと、あくまでも契約金等々のコストの面になりますが、業務内容での査定になってくるのか。例えばぷりすくーる西五反田の例で言いますと、５年間契約があったとしたら、職員はそこでずっと働いているわけですね。その辺の絡みはいかがなんでしょうか。","respondent":"堀越行財政改革担当課長","answer":"それからもう１点、それが実際問題としてうまく機能していないというような場合には、ある程度の調整ということも考えられるかとは思いますけれども、事業者側としては、この指定管理者制度の意味が何かというと。","voiceIndex":65,"id":"exchange-029"},{"speaker":"西本副委員長","kind":"質問","question":"そうなってくると、例えばぷりすくーる西五反田で言いますと、保育料の値上げなんかも自由にできてしまうということなのか、その辺の管理はどうなのか、そこのチェック機能とかは品川区にはないのか、指定管理者のほうですべての判断をしてしまっていいのかというところは、いかがでしょうか。","respondent":"新美企画部長","answer":"自由、自主性は当然尊重されなければなりませんが、それとしかるべく区側の対応策をどうするかということは、個別にちょっとご相談をしていく事項ではないかと考えております。","voiceIndex":67,"id":"exchange-030"},{"speaker":"西本副委員長","kind":"質問・要望","question":"もう一つ確認したいのが、先ほど、部長の答弁の中で、区のノウハウといいますか、今までの歴史がいろいろあって、それを維持しつつ、それから民間を活用して、さらに区民のニーズにこたえていくんだというお話があったと思うんです。その辺の説明の仕方とかを、再度、つくり上げていく、示していく手立てをしていく必要があるんじゃないかなと考えるんですが、その辺のお考えはいかがでしょうか。","respondent":"堀越行財政改革担当課長","answer":"それをなぜ職員で継続していかないのかというお話かと思いますけれども、保育園のお話ですと、今、区としてきちんと先駆的に行っているという部分があって、それを、区内３９の保育園に対して、民間のレベルとしてどうなのかとか、例えば給食調理代行の部分についても。","voiceIndex":69,"id":"exchange-031"},{"speaker":"西本副委員長","kind":"質問・要望","question":"いろいろな方が入る中で、それを指導する側、運営する側、言い方はちょっとあれですけれども、使う側とか、そういうコーディネーターみたいな立場になろうかと思うんですが、そういうふうに、１人の技術とかとなってくると、もっともっと世の中は進んじゃっているなという感じがありますので、そこを含めて、どういう形の立場を、区として責任としていかなきゃいけないのか、民間に頼むべきものなのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-032"},{"speaker":"中島委員","kind":"質問","question":"ちょっと素朴な疑問なんですが、まちづくり事業部のところの区営住宅、区民住宅なんですが、ここの指定期間というのが、(株)品川宅建管理センターの場合は１年、区民住宅のファミーユ西五反田西館がベニーエステートサービス(株)で２年で、東館が３年と、違いがあるのはどうしてなんでしょうか。何か理由があるのか、またコスト的にどうなのか、その辺のところを教えてください。","respondent":"堀越行財政改革担当課長","answer":"こちらにつきましては、基本的には５年という形で考えておりましたけれども、これまで業務委託をやっておりました期間がありましたから、それを考慮いたしまして、残存期間を指定管理の期間として定めたものです。","voiceIndex":72,"id":"exchange-033"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、これから指定管理者を評価する制度を、やっぱり一つの尺度に統一したほうがいいと思います。きのう建設委員会の中では、管理者がすばらしいとつらつら述べられていました。だから、やはりそういうところを明確にしていったほうがいいと思います。ですから、そういう共通の評価の仕組みと、低廉されたコストの明示はしたほうがいいと思うんですが、いかがでしょうかという質問です。","respondent":"堀越行財政改革担当課長","answer":"評価シートの部分についても、基本的な部分、全庁的に整合性をとれたもの、これはきちんと見ておかなければいけないという部分、それからあとは施設ごとに個別に用意しておかなければいけない部分、そういった部分をきちんと効果的に。","voiceIndex":74,"id":"exchange-034"},{"speaker":"伊藤委員","kind":"質問・要望","question":"始まったばかりですので、もちろん検討していく時間も必要だと思います。繰り返しになりますが、たまたまそういう報告を聞いた中では、数字が上がってこないから説得力がなかったというのが正直な感想なんですよ。あわせて、所管の事情がさまざま違うでしょうから、それに足したり引いたりしながら、共通する仕組みをつくって、評価をつくってくださいという要望でありますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-035"},{"speaker":"井上委員","kind":"質問・要望","question":"それが、はいそうですかと判断をする根拠が何も示されていなかったという意味では、こんなにすばらしいんだからいいでしょうという形にならないためにも、やっぱり利用者評価というものを明らかにしていただいて、そのことで、どういうふうに利用者のニーズがきちんと達成されているのかということを、これからシートをつくって評価をしていくということなので、きちんとそういったところが出されて、原則。","respondent":"堀越行財政改革担当課長","answer":"いろいろな手法を使いまして進めていく。コストだけではないということを認識していただければなと思います。","voiceIndex":77,"id":"exchange-036"},{"speaker":"井上委員","kind":"質問・要望","question":"ほんとうに子育て支援というところだけじゃなくて、子育ち支援、子どもたちが育つというところで、どういう環境がいいのかということも、保護者の声とか、保育士たちもちゃんとゆっくりとこの子に向かってあげたいと思いながらも、人がかわっていくというような声も、多分届いていると思いますので、きちんと把握をして、協議をしていただきたいと思います。","respondent":"堀越行財政改革担当課長","answer":"既にご案内かとは思いますけれども、競争の導入よる公共サービスの改革に関する法律、公共サービス改革法が、７月７日に施行されましたので、改めまして、参考までに、民間委託に関する国の動きについて、同法の概要ということでご説明します。","voiceIndex":79,"id":"exchange-037"},{"speaker":"中塚委員","kind":"質問・要望","question":"競争の導入による公共サービスの改革に関する法律のこの資料ですけれども、これは、いつ、どこの資料なのか。おそらく国の審議会のものなのか、ちょっと教えていただきたい。ちょっとご説明いただきたいのは、近年でいいんですけれども、規制緩和の大合唱の中で進んできた法改正は、どのようなものがあったのか、あわせてご説明いただきたいと思います。","respondent":"堀越行財政改革担当課長","answer":"これまでの規制改革ということで言いますと、規制改革・民間開放推進３カ年計画ですとか、そのほか経済財政運営及び経済社会の構造改革に関する基本方針ですとか、そういったところで、公共サービス改革法のいろいろ原案みたいなものがつくられまして。","voiceIndex":83,"id":"exchange-038"},{"speaker":"中塚委員","kind":"確認","question":"働いているのに、生活保護基準以下の暮らししかできない方々が映し出されて、その数は全世帯の１０分の１。伺いたいのは、先ほど、ワーキングプアの話をしましたけれども、決して個人の努力不足では解決し得ない。むしろ、社会の問題とされている中、こうした格差社会を、ワーキングプアの実態を、品川区はどう見ているのか、お考えを伺いたい。そこを、まず伺いたいんですけれども、よろしくお願いします。","respondent":"本多委員長、堀越行財政改革担当課長","answer":"法律の概要についての説明をいただき、それで地方公共団体にとってこれからの課題ということですので、その辺を踏まえて、質疑のほう、答弁のほう、両方よろしくお願いします。先ほどもご説明した民間委託のいろいろなあり方の検討についても、この公共サービス改革法も注視しつつも、動きも見ながら、独自のきちんとしたあり方を検討していく。","voiceIndex":85,"id":"exchange-039"},{"speaker":"中塚委員","kind":"質問・要望","question":"独自のあり方を模索するというのでしょうか。先ほど、派遣の問題を少し伺いましたけれども、ＮＨＫスペシャルで映し出されたワーキングプアの実態を、よく受けとめていただきたいと思うんです。先ほど、法律の説明がありましたけれども、これそのものを、区がどういうふうに理解しているのか伺いたいんですけれども、これは、国民の立場に立っていると思いますか。","respondent":"堀越行財政改革担当課長","answer":"本日、この資料を出させていただきましたのは、７月７日に施行されたということで、今回の法案について、参考までに説明をさせていただいたというものです。","voiceIndex":88,"id":"exchange-040"},{"speaker":"中塚委員","kind":"質問","question":"私は、区の責任として、どうしても取り上げたいと思っていたのが、先ほどの議論の中でも、民間でできるものは民間へといって、いろいろな公共事業の分野を民間に開放していく説明がありました。そうすると、月の収入がどうなるかというと、１０万円を切っちゃうんですよ。そもそも生活保護基準以下の労働者をつくり出している、この責任をどう感じているのか、率直なお考えを伺いたいと思います。","respondent":"榎本人事課長","answer":"その求人広告というのは、それをやりたい人がそれに応募するということであって、それだけで生計を立てるとか、そういう前提でやってものではありませんので、そういう時間帯で、自分のやりたい仕事をやるという形になっていると思います。","voiceIndex":90,"id":"exchange-041"},{"speaker":"井上委員","kind":"質問・要望","question":"来月に公有地のことをやるということなんですが、今、原小学校の跡地で意見募集をされていますけれども、ホームページでああいう形で意見募集をしたということは、そのことに対して、区の姿勢を明らかにしていただけるのかなと思うんですけど、次世代育成のときには、そういう形で、そのことに対する区の見解というものが出されていましたけれども、そういう形で進められていく予定があるのかどうかの確認を。","respondent":"日下部企画財政課長","answer":"その辺の結果につきましては、当然のことながら、次回の委員会で、状況、内容等についても、区としての基本的な考え方も含めまして、ご報告をさせていただきたいと考えています。","voiceIndex":95,"id":"exchange-042"},{"speaker":"井上委員","kind":"質問・要望","question":"次世代育成のときには、詳しくそういう形で出されておりますので、そういうことを参考にしていただいて、区の見解として資料としていただければということを要望したいと思いますので、ぜひ、正副委員長と理事者のほうで前向きに協議をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-043"},{"speaker":"中塚委員","kind":"質問・要望","question":"ちょっと原小学校のことで、ホームページで、私もこの前の委員会以降、見まして、意見募集がはじめにあったんですけれども、さっき見たら、確かにボタンを押していくと、そこのページにはあるんですけれども、トップページではなくなってしまっていた。トップページに残っていないと、大きな意見を募集する姿勢が感じられないんで、ぜひトップページに残していただきたいのですが、いかがでしょうか。","respondent":"日下部企画財政課長","answer":"つい先日、私も確認しましたら、しっかり残っておりましたが、今の委員のお話、改めて確認いたしまして、８月１５日までは最上段にそのまま残るようにということで、改めて、確認、調整をします。","voiceIndex":98,"id":"exchange-044"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5804#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":36736,"voices":101}},{"id":"h18-20060803-5","meetingId":"h18-cm08","date":"2006年8月3日","dateIso":"2006-08-03","committee":"総務委員会","time":"午後１時０２分～午後４時４２分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の２、報告事項","agenda":"の２、報告事項","exchanges":[{"speaker":"山村委員","kind":"質問","question":"今後、大学はこれ以上増やすということがあるかどうか、教えてください。","respondent":"榎本人事課長","answer":"大学なんですが、区内の大学としては清泉女子大学、立正大学ということで、首都大学東京は若干関連校が区内にあるということでやっておりますけれども、多分、区内にはほかに大学はあまりないと思いますので、今後、増やしていく予定はございません。","voiceIndex":7,"id":"exchange-001"},{"speaker":"山村委員","kind":"意見","question":"そうすると、要するに区内以外の大学から受け入れるということは、今後、考えないのか。例えば明治大学とかは商店街といろいろとかかわっていると思いますけれども、私が出ているからというわけじゃありませんが、とにかく今後、区内以外の大学というのは考えられるのかどうか。","respondent":"榎本人事課長","answer":"区外の大学から実際に話があった段階で、どういうふうに実現可能かというのは考えたいと思いますけれども、やはり受け入れ職場にも数に限りがありまして、それと、あとは大学側の要望がどういうところにあるのかというのを勘案してやっていきたいと思いますので。","voiceIndex":9,"id":"exchange-002"},{"speaker":"山村委員","kind":"質問","question":"受け入れの人数というのが、結局、現時点よりあとどのぐらい増やせるのかというのと、インターンを受け入れるにあたって、金銭的なことというのは全く発生していないんですか。","respondent":"榎本人事課長","answer":"受け入れの人数ですけれども、受け入れ先等で、例えば今年から始めた首都大学東京の児童センターとかすまいるスクールであれば、人数をある程度増やすというのは可能かなと思いますけれども、どこにねらいを置くかによってその辺も考えていきたいと思っています。","voiceIndex":11,"id":"exchange-003"},{"speaker":"山路委員","kind":"質問・要望","question":"インターンシップ制度については、五、六年前の一般質問、予算・決算特別委員会のあらゆる機会を通じて訴えさせていただいてきたわけなんですけれども、できるならば、区長秘書というところも、犬山市で当時やっていた例を挙げまして、お願いしたところなんですけれども、インターンシップ制度、将来の品川区の人材づくりという視点から大きな効果を生むんじゃないですかということで、当時。","respondent":"榎本人事課長","answer":"区長秘書の関係ですけれども、職務の内容等をそれぞれ相談してやっていることなので、受け入れができるところ、要は、インターンシップを受け入れるということはそれなりに説明する人をつけないと学生が孤立してしまうので、逆に孤立しちゃうと、就業に対しての意欲とか。","voiceIndex":13,"id":"exchange-004"},{"speaker":"山路委員","kind":"質問","question":"要するに、人材づくりを大目的とした場合に、インターンシップで職場体験、公務員体験をされる方たちは、学校で学んだ知識、教養といいますか、学問といいますか、それと実体験と合致して、社会にどのように、まだ歴史は浅いですからもっともっと時間がたたないと判断はつかないと思うんですが、どのように今後、大きな人材をつくっていくかという夢といいますか、その辺の目標を置いて。","respondent":"榎本人事課長","answer":"要は、逆に自分がそういう今まで知らなかったところをすごく見られたという形と、あとは周りからいろいろ教えられたということで、かなり実際上、就職ということに対しての関心がものすごく高まっているというふうな話で聞いています。","voiceIndex":15,"id":"exchange-005"},{"speaker":"山路委員","kind":"質問","question":"そういう方向でいいんですけれども、学問で培ってきたものを実体験をして、公務員という体験ですから、もっともっとお一人おひとりの能力を大きく引き出していけるか、その辺のご意見というのは、やはり個人でレポートとかかたいものじゃないにしても、ある程度掌握して見守っていく必要性があるんじゃないかと思いますので、その辺をよろしくお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-006"},{"speaker":"塚本委員","kind":"質問・要望","question":"山地委員の発言を聞いてですけれども、せっかくの機会ですから、体験なさった方が職場に対する感想、あるいは公務員の仕事に対する感想をしっかりと受けとめる機会という手続をとっているかどうかということが１つと、金銭的には何も発生していないと言いましたけれども、修了証とか、そういうものは出しているのか、あるいは何か記念品を出しているのか、やっぱりけじめ。","respondent":"榎本人事課長","answer":"高校生の部分については、ちょっとボランティア的なものというか、実際上、高校生でやっているのは、保育園についての子育ての体験ボランティア的な形でやっているところはありますけれども、なかなか高校生となると時間的な制約。","voiceIndex":18,"id":"exchange-007"},{"speaker":"塚本委員","kind":"質問・要望","question":"保育士の手伝いをしたり、幼稚園の手伝いをしたり、あるいは品川の場合でしたら、すまいるスクールのようなところがあるわけですから、やはり現場で働くということと福祉ということは、特に福祉の関係になりますと、福祉というものを体験するという仕組みをもう一歩踏み込んでつくっていっていただきたい。要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-008"},{"speaker":"藤原委員","kind":"質問","question":"２番のインターンシップの目的で、品川区として職場の活性化になると書いてあるんですけれども、インターンシップのこの制度があって、何で職場が活性化するんでしょうか。","respondent":"榎本人事課長","answer":"やはり若い世代、要は大学１年生ですと１９、２０歳ということで、職員でもその年齢層というのはかなりまだ人数が少ない段階ですし、そういう方たちを職場に迎えるということ、それから迎える職場では、だれかが担当になって、人に教えるということで、自分なりにきちんと仕事を。","voiceIndex":21,"id":"exchange-009"},{"speaker":"藤原委員","kind":"質問","question":"ほとんどの方がずっと定年までいらっしゃる、新人を育てるのも活性化には十分なっていると思うんですけれども、もう一回そことの、何で大学生が１０日間、８日間来ることによって活性化されるのかがちょっとぴんと来ないのが１点と、もう一回質問したいのと、それで、今、公務員をどういうふうに思っているかというのも活性化の１つになるというお話なんですけれども、それで。","respondent":"榎本人事課長","answer":"それで、確かに委員がおっしゃるようにやったほうが後々の効果という意味では見られるかもしれないですけれども、実際にその大学、今年でいくと１４名という形になりますので、１４名のうちどれぐらいの方が実際上、将来的になるのかというのは、今後、大学側と協議して。","voiceIndex":23,"id":"exchange-010"},{"speaker":"藤原委員","kind":"意見","question":"そこはよろしくお願いします。そこが私は教えた方の一番の活性化になるし、感情論になっちゃうかもしれませんけれども、公務員としての、人としての喜びでもあると思いますので、その辺というのはちゃんと押さえておいたほうがいいと思いますので、今後、検討していただければ幸いです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":25,"id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"でもこれは、あくまでここの場合には、品川区の場合には体験ですと、１０日間お試し期間ですと、実際、正直言って、研修にしたら、１０日間が実質７日間かもしれない、６日間かもしれないというところで、ちょっとその辺、インターンシップの取り組みについては本当に評価するんですけれども、もう少しその一歩先をやはり考えてあげて、区役所に公務員として勤めたいという若者の強い希望がある方には。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-012"},{"speaker":"須貝委員","kind":"意見","question":"１点だけ。大ざっぱで結構なんですけれども、外構整備工事として、このように舗装工事、排水工事、門扉工事、植栽工事がありますけれども、大体幾らずつかかっているか、大ざっぱでわかったらお願いします。","respondent":"宍戸施設担当課長","answer":"非常に大ざっぱな言い方ですけれども、面積的に５,３５０m2ございまして、平米単価が３万円程度というふうな金額になってあります。","voiceIndex":31,"id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"排水工事とか、いろいろありますよね。それぞれごとにはないですか。じゃあ、後でもしわかったらご説明ください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-014"},{"speaker":"塚本委員","kind":"質問","question":"緑化面積が増えるのかどうか、特に立会緑道、立会川のところはそれほど広くないので、学校の境界が後退するのかどうか、植栽のところがどうなっているのかということと、それから運動場は、これは面積としては広くなっているんですか。それから運動場は、これは絵で見るとある種囲われているのかな、植栽と一緒になっているのか、その辺のところをちょっと教えてください。","respondent":"宍戸施設担当課長","answer":"グラウンドとしましても、今回、今までよりは長い距離の１４２ｍのトラックが確保できます。","voiceIndex":34,"id":"exchange-015"},{"speaker":"塚本委員","kind":"意見","question":"セットバックしないけれども、植樹帯がどっちのほうに、道のほうに、境界はどこにできているの。それを一番知りたい。塀の中に緑があるのか、道路に面している場合は、そのあたりに校庭と区切ってあるのか、随分感じが違ってきますので。","respondent":"宍戸施設担当課長","answer":"フェンスは道路沿いに作りますが、なるべく目立たない色のメッシュフェンスを使うことにより、道路に面して植樹帯が広がって見えるよう工夫いたします。","voiceIndex":38,"id":"exchange-016"},{"speaker":"菊地委員","kind":"質問","question":"２点ほど聞きたいんですけれども、１つは、現在の電柱の場合、道路占用料ですか、発生していますけれども、これは地中化することで、今の説明ですと、何か特殊桝とかといって、これもやっぱり地中に埋めるのかどうかわかりませんけれども、その辺の東京電力なり、このそれぞれの企業からの電柱の占用料に相当するようなものは出てくるような話なのかどうか、ちょっとそこを聞きたいのと、それと。","respondent":"中島経理課長","answer":"それと、トランスですけれども、今は大きなトランスがありますけれども、今回の小型トラフでいきますと変圧器が必要になるわけですけれども、例えば高圧から低圧に変えて街路灯をつけるとか、照明に使うとかという場合、そういったものは今回。","voiceIndex":44,"id":"exchange-017"},{"speaker":"菊地委員","kind":"質問・要望","question":"ちょっとさっきの建設負担金ですか、そうすると、建築負担金というのは今度の契約金額の中で何％ぐらいを占めるのかを教えていただきたいのと、建設後は区の帰属物ということですけれども、管理そのものは新たに管理費用とかが、管理は全くなしということはあり得ないでしょうから、管理費云々というのはどうなっているのかを教えてください。","respondent":"中島経理課長","answer":"それで、もともと建設負担金の考え方としましては、地中に電線を埋設したときに、２５年ごとに買いかえる必要が生じるだろうという基本的な考え方がございまして、それに、そのときに当然、通常地中に埋めた場合、各企業者がそれを線を引き直したりとかするわけですけれども。","voiceIndex":46,"id":"exchange-018"},{"speaker":"菊地委員","kind":"質問","question":"区の帰属物ということですから、ここに書いてあるトラフそのものは区の帰属物になるわけですよね。これそのものが破損をしたりとかということがあれば、これは区がそのための負担をしていくという考え方になるんでしょうか。","respondent":"中島経理課長","answer":"トラフそのものは半永久的なものとして考えてありますので、具体的には、要するに、例えば震災等で破損したという場合はまた全く別の問題ということになりますが、通常、１０年２０年ぐらいで破損するということは全く想定していないと聞いてあります。","voiceIndex":48,"id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"建物の場合には、いろいろそこの地形なり、建物の大きさ、形状等でいろいろ違うと思うんですけれども、電線の地中化に関しては、道路上にこういうトラフとか、そういうものをつくっていくわけですから、せっかく東京都で電子入札、東京都の方式を採用しているわけですから、ほかの区ではメートル幾らぐらいなのかなというのを載せられないでしょうか。どうでしょうか。","respondent":"中島経理課長","answer":"各所管で参考になる数字はあるのかもしれませんけれども、品川区のこの契約の入札状況調書の中に他区のそういったもので載せるのはいかがなものなのかなというふうには考えてありますけれども。","voiceIndex":50,"id":"exchange-020"},{"speaker":"須貝委員","kind":"質問","question":"道路上にこういう、要するに地中化をするには、先ほども申し上げましたけれども、ほぼ変わらない工事内容だと思いますので、今回、工事請負契約にかかわる報告ということで、契約金額がせっかく出ているんですから、品川区ではメートル当たり幾ら幾ら、他区ではこういう感じで出ていますよという参考価格みたいなのがあると非常に審議もしやすいのかなと思ったもので、意見を述べさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-021"},{"speaker":"塚本委員","kind":"質問・要望","question":"須貝委員のお話もそうなんですけれども、電柱を地中化したいという要望はそれぞれのまちにあると思うんですけれども、それで、大づかみの話、１００ｍなら１００ｍ単位で、およそどのぐらいかかるんだよという話がわからないと、まちでこれは進む話なのか、進まない話なのか、見当がつかない部分があるわけです。","respondent":"中島経理課長、日下部企画財政課長","answer":"今のメートル幾らとかですけれども、予算ベースのお話で言いますと、今回の１工区と５工区につきましては、すべての経費ということになりますけれども、全体で約１億２,８００万円ぐらいの経費と、これは予算上なっております。今回の今年度分のその工事費についての金額ということで、今、申し上げましたけれども、ちょっとわかりやすく申し上げますと、全体の整備費用、これは実は地中化というと、地下を掘り返して。","voiceIndex":53,"id":"exchange-022"},{"speaker":"須貝委員","kind":"提案","question":"この総合庁舎のつくりというのは、広々と空間をとっているので、ピロティー方式という形だと思うんです。例えば今回、今、３つの提案がされましたけれども、仮にやったとしても、それは崩れないけれども、傾くことは傾く、もう耐震しか持っていけないと思うんです。","respondent":"宍戸施設担当課長","answer":"それは非常に大きな誤解でございまして、いずれにいたしましても、阪神淡路大震災並みの大きい地震が来ても、きちっと防災の中心的な役割を担う施設ですので、そういった機能がしっかり果たせるような補強法を考えてありますし、それはもう実現可能だと考えています。","voiceIndex":62,"id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1726#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":22189,"voices":68}},{"id":"h18-20060828-6","meetingId":"h18-cm08","date":"2006年8月28日","dateIso":"2006-08-28","committee":"区民委員会","time":"午後１時０４分～午後４時１２分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"１番目に、大崎第二地域センター移転計画","agenda":"１番目に、大崎第二地域センター移転計画","exchanges":[{"speaker":"土井委員","kind":"質問","question":"いわゆる無償で提供をされるのは、床面積というか、敷地面積というか、それだけというふうに理解してよろしいんですよね。ということは、そしてさらにそれは無償の譲渡ですので、いただいてしまうわけですから、後々の管理費等々は区のほうがずっとやっていくということになるのでよろしいんですね。","respondent":"田村地域活動課長","answer":"今、土井委員がおっしゃるとおり、無償譲渡というのは、床面積ということで、その後の管理については、区のほうで管理は行うという形になります。","voiceIndex":7,"id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"今のところは、狭いけれども２階に区民集会所を開放する施設がありますよね。当然、広くなるみたいなので、そういう機能も入れていくんだろうと思うんですけれども、そこのところというのは、これからの検討なのかもしれないけれども、基本的な考え方を教えてください。","respondent":"田村地域活動課長","answer":"先ほども冒頭お話ししたように、基本的には同様な施設を整備したいというふうに思っておりますが、まだ詳細の設計はこれからなので、それの詰めを今後、３年先になりますけれども徐々に検討して、同程度の規模のものは確保したい、このように考えております。","voiceIndex":9,"id":"exchange-002"},{"speaker":"南委員","kind":"確認","question":"たしか大崎第一地域センターが、やっちゃ場のところのあそこの開発の中に地域センターがたしか入っていますよね。あそこは地域センターとあそこの住宅の方々との共同使用ではなかったですか。区民集会所。独立していましたか。その辺を確認したいんですけれども。","respondent":"田村地域活動課長","answer":"大崎第一地域センターの関係ですが、たしか私の記憶ですが、集会所はそれぞれの建物が２つに分かれていますので、特にその旨を、区民集会所を入居者の集会所として利用するという話は特に聞いてございません。","voiceIndex":11,"id":"exchange-003"},{"speaker":"堺委員","kind":"質問","question":"そんなところも含めた跡地の利用については、やっぱり今後、頭の中に入れておかなければいかんかなという気がしましたので、まだわからなければわからないで結構です。３年先のことですから、ちょっとその辺はどうなのでしょうか。","respondent":"田村地域活動課長","answer":"先ほど冒頭お話ししたように、まだ３年先で、町会長方の受けとめ方も３年先かという話で終わっていますので、今、堺委員のご指摘のような話が今後出てきたときには、企画サイドのほうにそういう情報として入れて、今後どうするのか検討していこうという形になっています。","voiceIndex":14,"id":"exchange-004"},{"speaker":"堺委員","kind":"質問","question":"今までもそういうことはなかった。これに関連して今までなかったんですか。","respondent":"田村地域活動課長","answer":"特にそれに当たっての話は現在のところ具体的にはございません。","voiceIndex":16,"id":"exchange-005"},{"speaker":"堺委員","kind":"質問","question":"ほかの地域でもそういうようなことはなかったんですか。","respondent":"田村地域活動課長","answer":"ご指摘のように、ほかの地域でもそういう話は特にございません。","voiceIndex":18,"id":"exchange-006"}]},{"id":"topic-02","title":"の（２）番となります。医療制度改革","agenda":"の（２）番となります。医療制度改革","exchanges":[{"speaker":"南委員","kind":"質問","question":"そのことは異論ないと思うんですけれども、「糖尿病等の予防に着目した」という、こういう具体的に「糖尿病」と挙げて、そして「等」というのをつけている、このところをどういうふうに理解すればいいのかなと思うんですけれども、私はすべての疾病、すべての内容について、健診、予防というのを重視してきていたつもりなんだけれども、そこがどういうふうに。","respondent":"原国保年金課長","answer":"自己負担の２割から３割ですと、現役並みの所得のある方ということで、すべての方が負担が増えるということではなくて、一定所得のある方に対しての負担増ですので、ここの部分についてはご理解をいただいて努めていきたいというふうに思っているところです。","voiceIndex":27,"id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、一定所得がある人だからということでは到底済まされないことなんだろうというふうに思うので、この点について、私どもは、先だって助役交渉を行って、税制改正のほうの部分なんですけれども、緊急に国に中止を求めてほしいという要請もさせていただいたんですが、そういうことも含めて、もっともっと積極的に区民の状況、実態などもとらえて緩和できるような。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-008"},{"speaker":"堺委員","kind":"質問・要望","question":"時間がないときに済みません。というのは、さっきこれを課長がご説明していただいた中で、９月１日の「広報しながわ」に区民への周知としてこの件について掲載をされるというお話がございましたので、その区民への周知で「広報しながわ」に掲載するときに、どういう表現でこの件について周知をされるのかということが僕は大事だろうと。なぜそうなったのかということなんです。以上で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"委員長、ちょっと確認なんですけれども、今、委員長がおっしゃったのは、次回のときに、条例の審査のときに十分な議論をする時間をとおっしゃって、それは本当にありがたいことだと思うんですけれども、条例審査というのは、国保の条例改正の部分ですよね。そういうふうにしていただきたいんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"要するに、今度の審査は条例改正の部分ですから国保の部分だけですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-011"},{"speaker":"大沢委員","kind":"質問・要望","question":"１点だけ確認させていただきたいんですけれども、１番の（３）の現役並みの所得というのと、先ほど同じ説明の中で一定以上所得者という表現が出てきたんですけれども、これは事務事業概要の５ページにある説明書きでいいわけでしょうか。","respondent":"原国保年金課長","answer":"今まで一定所得以上という表現で来ておりましたけれど、これからは現役並みの所得ということで、内容としては同じ内容ではありますけれど、呼び方がそういった形で統一されていくような形になると思います。","voiceIndex":41,"id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2466#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":14178,"voices":56}},{"id":"h18-20060828-7","meetingId":"h18-cm08","date":"2006年8月28日","dateIso":"2006-08-28","committee":"厚生委員会","time":"午後１時０４分～午後４時３１分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を60件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"木下委員","kind":"質問","question":"ちょっとお尋ねしたいんですが、先ほどの説明で、日常における監視指導状況の中で、屋外プールの再開届に伴う立入検査とか、プールに対する立入検査、感染症発生情報に基づく立入検査とありますが、件数はちょっと違うかと思うんですが、この違いというのはどこら辺で、その差みたいなものを、もう一度お教えていただければありがたいんですが。","respondent":"高橋品川区保健センター衛生課長","answer":"日常管理の指導状況ですが、屋外プールにおける再開に伴う立入検査の６２件につきましては、許可プールが３件、そのほかにつきましては、区立の施設５３カ所、それから、都立５カ所、私立１カ所ということで検査をします。","voiceIndex":6,"id":"exchange-001"},{"speaker":"木下委員","kind":"質問","question":"感染症発生情報に基づく立入検査１件というのが、その情報に基づく立入検査ということで、結果的には何もなかったという認識でよろしいわけですね。それから、先ほどの１番と２番の違いというのは、通年か、通年じゃない違いという認識でよろしいんでしょうか。","respondent":"高橋品川区保健センター衛生課長","answer":"そうです。感染症については、一応疑いということで学校から情報が入ったんですが、実際には何もなかったです。","voiceIndex":8,"id":"exchange-002"},{"speaker":"三村委員","kind":"質問","question":"裏面のほうで、８月２１日現在で、吸い込み防止金具などがついていない施設が０になっているんですけれども、事故発生当時はどういった状況だったのか、教えていただけますか。７月時点です。","respondent":"高橋品川区保健センター衛生課長","answer":"ただ、その中で、１カ所についてはもう工事済みということで、現在のところ３カ所ということになっております。","voiceIndex":10,"id":"exchange-003"},{"speaker":"三村委員","kind":"質問","question":"今回、プールの事故も大きい事故として報道されていたんですけれども、それと並行して、プールの塩素が強すぎて体調を崩した生徒が出たというような事故報道もあったかと思います。そういった空気中の塩素濃度の対応でありますとか、飛び込みだとか、溺れた場合の対応というのは、どのように安全対策をしているのかお伺いします。","respondent":"高橋品川区保健センター衛生課長","answer":"最初、飛び込み等の監視状況ですが、基本的に、この条件につきましては、衛生管理設備基準ということで、監視状況につきましては、そこの施設管理者が、具体的に盲点がないように管理者を立ててやってほしいということで、自主管理を進めているところですので。","voiceIndex":12,"id":"exchange-004"},{"speaker":"三村委員","kind":"質問","question":"今、各管理会社のほうの自主管理にゆだねているということで、品川区のほうとしては、管理基準みたいなものは定めていないということなんですか。","respondent":"高橋品川区保健センター衛生課長","answer":"衛生管理基準、それから監視のところの基準につきましては、条例施行規則の中で別表で、監視人を置かなくてはならないとか、濾過器のところとか、または塩素濃度の検査の方法とか具体的に載っておりますので、それに基づいて実施してほしいということで指導しております。","voiceIndex":14,"id":"exchange-005"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろな関係を知りたいので、教えていただきたいんですが、こういうプールの事故があったりした場合に、今回は、厚生労働省から通知が来たと。８月２日の段階で、それを、許可プール施設管理者と教育委員会のほうに送付した。そもそもそのチェック項目になかったというところも、大きい問題点としてあるわけですけれども、その責任の所在がどういう関係になっているのか、教えていただきたいと思います。","respondent":"高橋品川区保健センター衛生課長","answer":"ですから、品川区におきましては、プールを管理しているところでは、許可プールについては私ども、学校プール、届出プールについては教育委員会で監視しておりますので、そこのところで責任を持って指導しております。","voiceIndex":16,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"仮に、許可プールでこういうことがあったから、教育委員会でもこういうふうにやったらいかがでしょうかとか、そういうお互いの危機管理というのを統一していきながら、お互いのミスチェックがないような形がつくれるんじゃないかなと思うんですが、その関係はどうなっているんでしょうか。","respondent":"谷田部健康課長","answer":"ともすれば縦割り行政ということで、なかなか横の連絡がとりにくくて、同一の業務を行っていながらも、事故の発生に対しての迅速な対応がなかなかとりにくいということで、今回、ふじみ野市の事故を受けまして、いわゆる条例上の許可プールについては。","voiceIndex":18,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろな担当によっては、それぞれ施設があるわけで、それを品川区としてはまとめていきましょうと、きちんと流れをつくっているというところでは、今後もそういう形でやっていただきたいなと考えています。だから、そこのところは、いろいろなところを含めて、今後も継続してお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"確認","question":"１点だけちょっと確認させてください。品川区における対応の中で、８月１日に安全状況確認調査を１０カ所実施していらっしゃるんですけれども、これは区のほうで直接実施しているんですか。それとも、向こうの報告の確認をしているのか。","respondent":"高橋品川区保健センター衛生課長","answer":"これにつきましては、区のほうで立入検査とあわせて、その時期に実際に行きまして調査をしたものです。","voiceIndex":21,"id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"確認","question":"そのほうがいいと思ったんです。念のため、もう１回確認なんですけれども、よく網が２カ所とか言っていましたね。水を抜かないとわからない部分があるという状況の中で、これは、民間の営業している部分なんですが、その日、営業しないで水抜きをやったのかなという確認なんですけれども。","respondent":"高橋品川区保健センター衛生課長","answer":"流れるプールですので、２人の監視員が両端からそれぞれぐるっと回っていくということも確認しております。","voiceIndex":23,"id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"８月９日に行われている吸い込み防止安全対策遵守状況調査は、許可プール、施設管理者ということなので、１９カ所、この調査をされて、先ほどの二重構造になっていないのが４カ所あって、１カ所が工事済みということなんでしょうか。３カ所については、二重構造への指導がされるのか、どうかということを一つお聞きしたい。","respondent":"高橋品川区保健センター衛生課長","answer":"二重構造のところにつきましては、厚生労働省については、必ずしも二重構造がいいのか、どうなのか、今の時点でもはっきりしないところですが、私どもでは、残りの３カ所については、現在、使われているところですので、水抜きをした後、工事をするということで確認をしています。","voiceIndex":25,"id":"exchange-011"},{"speaker":"三村委員","kind":"質問","question":"基本的なことをちょっとお伺いしたいんですけれども、２階の平面図なんかを見ますと、面積のわりには居室数が多いなと感じるんですけれども、居室の平米数がどのぐらいかとか、国の基準がどうなっているのか、共用スペースのパーセンテージだとか、そういう基本的な情報を、ちょっと教えていただけますか。","respondent":"蓼沼高齢福祉課長","answer":"２階のケアホームの居室ですけれども、計画段階での面積は、大体１６m2という構成になっております。国の基準が１５.６３m2です。それから共用部分の面積について、すみません、今ちょっと数字がございません。","voiceIndex":32,"id":"exchange-012"},{"speaker":"三村委員","kind":"質問","question":"今回の計画の中にも、福祉の専門家だとか、保育関係者が入ったりとか、利用者とか、プロが計画段階から入っているか、その辺についても、教えていただけますか。","respondent":"蓼沼高齢福祉課長","answer":"その際に、プロポーザルで提案された施設整備の計画内容等について十分検討してきて、この施設提案内容をもって施設管理運営事業者を決定したという経緯が、まず一つあります。","voiceIndex":34,"id":"exchange-013"},{"speaker":"三村委員","kind":"質問","question":"そういう実績のある事業所が計画をしたということだと思うんですけれども、先ほどの、十分庁内で検討というところには、保育園の運営に携わっている人だとか、高齢者の介護や何かにも携わっている人が入ったりとかではなくて、そこの部分は庁内検討のみで、実際の運営に携わっている現場の人が入っているということはないということですか。","respondent":"蓼沼高齢福祉課長、小林保育課長","answer":"今後また、サービス内容を検討していく中で、変更もさらにはあるかもしれないという点はあります。保育園部分のレイアウトに関しましては、基本的に品川保育園の移転という状況も踏まえまして、該当する園の園長、現場の保育士等、ワークグループをつくりまして検討する中で、導線の確保等を行っております。","voiceIndex":36,"id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ケアホームに関しては、１部屋ずつになっている感じなんですけれども、夫婦で入れるところという計画があるのか、どうかを教えていただきたいと思います。それからもう一つ、今、ケアホームというところでは、西五反田に１カ所できていますけれども、ここで入所待ちをされている方がどのぐらいいるのかについても教えてください。","respondent":"蓼沼高齢福祉課長","answer":"ご夫婦で入れるのかですけれども、基本的には個室ということになっておりますので、夫婦で入居をするということは想定してございません。それから、西五反田のケアホームのほうの入所待ちの人数については、すみません、今ちょっと数字がありません。","voiceIndex":39,"id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"西五反田のほうは、わかったら後でぜひ教えてください。そういう点では、ぜひ、夫婦で入れるところもご検討いただけないかということで、要望をさせていただきたいと思います。それから、この施設をつくるに当たっての総事業費と、それぞれ補助金が出ると思うんですけれども、その額がどれぐらいなのかということについて、教えていただけないでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"小規模多機能の居室の面積ですけれども、約９m2です。最低基準が、これはグループホームと同じ７.４３m2になっております。それから、ご夫婦でというご要望は、検討させていただきたいと思います。","voiceIndex":41,"id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"国のほうの補助金制度から、一つのケアホームとか、小規模多機能、それぞれに交付金という形で出ることになったと思うんですけれども、そこら辺の、それぞれの交付金と補助金というのがわかったら教えていただきたい。それから、これからつくられるケアホーム、グループホーム、小規模多機能の利用料が、おおよそわかったら教えていただきたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"国の交付金、都の補助金の内訳です。都の補助金が、認証高齢者グループホームに対しまして交付される予定です、これが７５０万円。そのほか国の交付金が、各施設に交付される予定ですので、それらが７,７５０万円。","voiceIndex":43,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"都からはグループホームに７５０万円だけしか出ないんでしょうか。それから、国の７,７５０万円というのも、ちょっと内訳がわかったら教えていただきたいと思います。それからもう一つ、保育園の園庭が１階と屋上ということになっていますけれども、それぞれ園庭の面積がどれぐらいになっているのか、もうちょっと教えていただけないでしょうか。","respondent":"小林保育課長、木下福祉高齢事業部長","answer":"最低の基準で言えば二百五、六十m2前後、それ以上の確保を予定しておりまして、十分な面積が屋上部分で確保できるという計画になっております。それから利用料の問題につきましては、ケアホームの場合には、いわゆる賃料相当と光熱水費、食事代、それから介護報酬の１割負担というような形のものも基本的な要素として構成してまいりますので、今後、運営事業者と。","voiceIndex":45,"id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この利用料に関しては、できる限り低廉にということで、ぜひご検討をよろしくお願いしたいと思います。南側の土地を買って、子どもたちが十分に遊べるような園庭と、また高齢者の憩いの場にできないかと思うんですけれども、そういう点では、そういう方向にしてほしいと思うんですけれども、いかがでしょうか。","respondent":"小林保育課長","answer":"園庭の関係ですけれども、通常の保育を行っていく上で、屋上の園庭で機能的には十分足りると考えています。なお、用地の取得につきましては、現段階では予定がないやに聞いております。","voiceIndex":50,"id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"やっぱり屋上だと、大きな木は育たないですし、やっぱり、土を感じるということも、地面のようにはなかなか難しいんじゃないかと思いますので、ぜひ南側の土地を買って、そういう方向でご検討いただきたいという要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-020"},{"speaker":"木下委員","kind":"質問・要望","question":"園庭というと子どもたちの遊ぶ場なので、今、景観ですとかそういうもので、できるだけオープンにしたいという部分はあるのかもしれないんですけれども、イメージ図を見ていると、ちょっと柵が低くて、何かあったら、それこそそういう景観云々というよりも、そのほうが重要じゃないかなとふと思ったものですから、細かくて申しわけないんですけれども、そこら辺は、どのぐらいの高さで考えていらっしゃるのか。","respondent":"蓼沼高齢福祉課長","answer":"ですから、園庭はその内側に位置するということになりますので、直接外と接するようには、イメージ図からもなっていないことにはなっておりますが、いずれにしても安全確保第一に、設計、建設は進めてまいりたいと考えております。","voiceIndex":53,"id":"exchange-021"},{"speaker":"西本委員","kind":"質問・要望","question":"なぜ、こういういろいろな機能を持たせたのか。それから、指定管理者制度を導入されるということで、それは何年になるんですか。その中で、子どもたちの安全確保というのは、当然出てきますし、園庭が１階と４階の屋上にあるというところでは、当然１階から屋上への移動も当然あるわけですので、その中での安全確保をどういう考え方で進められているのかを、お聞きしたいと思います。","respondent":"蓼沼高齢福祉課長、小林保育課長","answer":"施設構成のケアホームの３ユニットという考え方ですけれども、今後の施設整備に当たりましては、これまでですと、例えば特別養護老人ホームですと、いわゆる相部屋が中心だったわけですけれども。イメージとしては、台場の幼稚園、保育園のような感じです。１点危惧されますのは、エレベーターが共有という点なんですが、これにつきましては、エレベーターのコントロールの中で十分に対応可能かと考えております。","voiceIndex":55,"id":"exchange-022"},{"speaker":"西本委員","kind":"質問・要望","question":"指定管理者なんですけれども、これは、平成２１年度からということでよろしいのですか。それから、保育園のほうの関係ですが、エレベーターの話、メカニック的にはできるんでしょうけれども、エレベーターというのはちょっと怖いなという部分もあって、問題がたくさんいろいろ起きていますので、その辺の安全管理をきちんとしていただきたいということ、これは要望です。","respondent":"木下福祉高齢事業部長、蓼沼高齢福祉課長、小林保育課長","answer":"じゃあ、今後はどういう施設整備をしていくかということでは、基本はまず在宅重視ということは変わりありませんけれども、その中でも。指定管理者としての時期の問題ですけれども、平成２１年２月、高齢者福祉施設の開設予定です。保育園の移転開設の時期につきましては、工事の進捗状況、それから子ども、園の負担の状況等を踏まえまして、最終的に決定をしてまいりたいと思います。","voiceIndex":58,"id":"exchange-023"},{"speaker":"三上委員","kind":"質問・要望","question":"それからもう一つ、どちらかというと、駅に近い施設ということになってくると、どうしてもやはり要望的には、７時半の施設がいいのか、８時半の施設がいいのかという、お父さん、お母さん方の希望、声が当然、少し遅い時間に設定してほしいとかという要望が出てくる可能性があるとなれば、そこらあたりの現状の考え方というのは、７時半ということが固まったということであるのか、ないのか、ここらあたり。","respondent":"小林保育課長","answer":"品川保育園の現状の定数は９０名。０歳児のいない１歳児園で、７時半までの園です。新規開設に当たりましては、委員ご指摘のとおり、より駅に近い駅前立地的な要素がありますので、この要素を加味して、詳細については、今後検討してまいりたいと思います。","voiceIndex":62,"id":"exchange-024"},{"speaker":"三上委員","kind":"質問","question":"１０名増えるということですよね。そこらあたりは、もう少し増やすという考え方はないんでしょうかね。０歳からやるとか、そういった基本的な考え方はどうなんですか。","respondent":"小林保育課長","answer":"定員につきましては、施設の制約等もありますが、今回、詳細な設計が決まりました段階で、必ずしも定員以内にこだわらずに、施設の状況、もちろん職員の配置等に余裕も持っておりますので、弾力的な運用ということで、定員を超えた、ある程度の対応も可能と考えております。","voiceIndex":64,"id":"exchange-025"},{"speaker":"三上委員","kind":"質問・要望","question":"まだ少し時間がありますので、そこらあたりしっかりといろいろな調査の上で、やはり区民サービスをどう拡大できるかということについて、しっかりと取り組んでいただきたいとお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その中で何点かお聞きしたいんですが、例えば、延べ床面積３,１００m2は、建築基準法上でほとんど限度いっぱいなのか。その辺が１点。それから、せっかく平成１９年２月で基本設計、実施設計ができる段階で、何で着工が平成１９年９月なのか。そこら辺から、まずは教えていただきたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"そのスケジュールを考えますと、平成１９年度の交付金の内示があるのが夏ぐらいだろうという見込みがありまして、一応９月着工というスケジュールを立てたものです。","voiceIndex":67,"id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"質問","question":"わかりました。内示がなければできないというのではしようがないけれども、一日でも早く進めてもらいたいなという思いの中で、その辺を前から言わせてもらったんです。先ほどの質問にちょっと絡んじゃうんですけれども、指定管理者制度が平成２０年の第３回定例会というお話があったと思うんですけれども、そうすると、建物が完成してない時期に指定管理者が決まるという状況で、それは構わないんですか。","respondent":"蓼沼高齢福祉課長","answer":"指定管理者の議決そのものは、建物が完成されていなくてもできるものと考えております。亀田邸につきましても、来年完成、オープンの予定ですけれども、年内にご議決をいただくという予定を考えております。","voiceIndex":69,"id":"exchange-028"},{"speaker":"鈴木（真）委員","kind":"確認","question":"わかりました。確かに、早く決まったほうが次に進めていくのにいいと思いますので、その辺だけちょっと、念のための確認だったんです。それから、建物の問題でちょっと気になったのが、ここは北側には入口はつくらないということでよろしいんですか。ですから、そこら辺にどう対応するのかということ。","respondent":"蓼沼高齢福祉課長","answer":"傾斜になっているところは、そういう傾斜に合わせた構造になると聞いております。中で段差を解消するような設計になるのではないかなと考えております。","voiceIndex":71,"id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"中で解消というと、例えば高齢者には結構きついんじゃないかと思うんですけれども、設計の問題で細かいところだから後でも結構ですけれども、ちょっとその辺は気になります。逆に北側あたりに自転車の置き場をつくれるのかという気もするんですけれども、ただ、つくってしまうと逆に、周りから置かれてしまう危険性もある場所なんですよね。ですから、そこら辺も十分に注意していただきたいなと思っています。","respondent":"蓼沼高齢福祉課長","answer":"特に段差というものがないような形で上の利用階に行けると考えております。駐輪場につきましては、この駐車場の一角をそういったスペースに当てることができるのではないかと考えております。","voiceIndex":73,"id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"確認","question":"建物のほうはその辺でお願いして、もう１点だけ、小規模多機能の件でちょっと確認をさせてもらいたいんですけれども、通所で大体１５人ぐらいというお話で、小規模多機能のことでちょっと間違っていたら申しわけない質問なんですけれども、その中で居室を９室つくっていらっしゃるということは、対象としている方は、介護度で言うとどのぐらい基準に考えているのかを教えてもらいたいんですが。","respondent":"蓼沼高齢福祉課長","answer":"今後、この活用については、まだ十分検討していく必要があるかなと考えております。","voiceIndex":75,"id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"確認","question":"この夏でも、家の中で面倒をみている方が、暑い中でちょっとショートステイに入りたいというのに、やっぱり入れないという現実があった中で、そういうものも利用できるのか、どうかということを確認したかったということです。その辺、まだこれから検討ということで、ある程度ショートステイということに限定して言うと、使うことはできるんですか。","respondent":"蓼沼高齢福祉課長","answer":"居室の多面的な利用といいますか、ショートステイという具体的なお話がありましたけれども、これにつきましては、今後の検討課題になると思いますけれども、この管理運営事業者が運営している他区の施設では。","voiceIndex":77,"id":"exchange-032"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"最後にします。先ほど、南側の土地を買ってほしいという要望があったんですけれども、あれは、前に私も別の委員会でもちょっと発言させてもらったことがあるんですけれども、現実にはなかなか売れない土地らしいということを聞いています。ですから、逆に言うと、国から区が借りるということが、いつまでになるかわからない状況ですけれども、その辺も検討の余地がないのかなということを要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"特別養護老人ホームであれば、今はほとんど、要介護度４か５しか入れないというのが現実、実態だと思うんです。そういうところで、私は、特別養護老人ホームをぜひつくっていただきたいという要望をずっと続けているわけなんです。そういうところで、先ほどの、基本的な施設の考え方、それからケアホームや特別養護老人ホームのニーズの点に関して、もう１回ちょっとご見解をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ほんとうに、特別養護老人ホームの入所待ちの切実な実態、それから老人保健センターを転々として、しかも、品川区内には１カ所しかなくて、他区を３カ月ごとに転々とせざるを得ないという方が、区民の中にあふれているという実態を見ていただいて、しかも、特別養護老人ホームと老人保健施設設備の整備率というのは、高齢者の人口からすると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-035"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"保育園についてお伺いします。屋上園庭のことなんですけれども、先ほど、エレベーターの利用の仕方の説明がございましたけれども、エレベーター以外、これは階段を使って昇降ができるようになっているのか、どうか。その点が１点。それから、運営のところなんですけれども、改めて見ますと、直営予定と書いてあるんですね。なぜ、予定がついているのかというところで、１点お伺いをしたいと思います。","respondent":"小林保育課長","answer":"いろいろなところへ散歩等出てまいりますけれども、上へ移動することがイコール危険とは考えておりません。ただ、物理的に、あらかじめ予防できるところは、今後、施設計画の中で十分に検討し、対応してまいりたいと考えています。","voiceIndex":84,"id":"exchange-036"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"３階までの移動は、階段の使い方が１点抜けていたので、それは後でお願いします。実態としては、多分、現場からたくさん声が上がっているのではないでしょうか。そういった面でお伺いをしたんです。子どもを育てる、高齢者の生活の場が日陰になってはならないと思うんで、ぜひその先も見越して手だてを打っていただけたらと思いますが、この点はいかがでしょうか。","respondent":"小林保育課長、木下福祉高齢事業部長","answer":"失礼しました。階段については、２方向避難の関係もございまして、設置をする予定です。屋上利用の園児の安全確保につきましては、今後の詳細な導線の確保等の中で十分に配慮してまいりたいと思います。したがって、私どもとして、都南病院の真ん中の土地１,５００m2をもって高齢者施設、保育園事業をきちんとやっていきたいと考えております。ご指摘の土地については、これまでもお話ししていますけれども、取得の予定はないです。","voiceIndex":86,"id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今、最後のほうにご説明いただきました社会福祉協議会の主催事業なんですけれども、高齢者に敬老祝品の贈呈というところで、７３歳以上ということになっているんですけれども、なぜ７０歳でなくて７３歳なのかということ。それから、低所得者世帯というのは、住民税非課税世帯ということなのか。そこら辺の中身について、教えてください。","respondent":"福島福祉高齢事業部副参事","answer":"お尋ねの件につきまして、お答えします。７３歳以上の低所得者世帯ということで、７３歳という数字ですが、実は、３年前までは７０歳以上の高齢者にお配りしておりました。","voiceIndex":94,"id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"わかりました。というのも、今、高齢者を狙い撃ちというぐらいに負担がどんどん増えていると思うんです。しかも、高齢者の増税になった分、区に対しては住民税が増収という形で入ってきているわけですよね。そういうふうに増税になって、増収になった分というのはやっぱり高齢者に使っていくというところで、ぜひ復活させていただけないかと思うんですけれども、いかがでしょうか。","respondent":"冨岡高齢事業課長","answer":"やはり、このまま、８０歳は女性の平均寿命より下ですけれども、平均寿命以上の節目ということで、当分の間はこれで進めさせていただきたいと思っています。","voiceIndex":96,"id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今、当分の間ということでお話があったんですけれども、ぜひ、ほんとうに高齢者が今大変になっていて、もちろん生活が大変になっているという事態の中で、さらに精神的にもそういう不安が広がっているという状況があると思いますので、これはぜひ、今後に向けてご検討いただきたいと要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところで、実際にどれぐらいの人が、どういうふうに影響を受けていくのかというのを、ちょっと教えていただきたいんです。実際に老人の医療費で、現役並みの２割の窓口負担の方が、１０月から３割になるという方がどれぐらいいらっしゃるのか。そして、ずっと１割のままという方が何人ぐらいいらっしゃるのかということを、ちょっと教えていただけないでしょうか。","respondent":"冨岡高齢事業課長","answer":"そうしますと、１０月から３割になる方ですが、引き続き２割の方と１割から２割になった方を合計いたしますと、６,４１１名です。それから、１割負担ということで、合計をいたしますと２万５,８２７名でございまして、合計で３万２,２３８名が、老人医療保険の対象者です。","voiceIndex":105,"id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"すみません、ちょっと数字が書き取れなかったんですけれども、平成１８年度に１割から２割になった方というのは、８月に新たに、今まで１割だったのが２割になったという方が２,２４２名ということなんでしょうか。ちょっとそこら辺の意味と、数字をちょっともう１回、わかりやすく教えていただけないでしょうか。どういうものかという説明もあわせて、ちょっと教えていただければと思います。","respondent":"冨岡高齢事業課長","answer":"もう１回。引き続き２割の方が４,１６９名、１割から２割になった方が、今申し上げた２,２４２名、合わせますと、２割の方が６,４１１名です。先ほどの２割から１割も含めまして、１割の方が、合計で２万５,８２７名です。","voiceIndex":107,"id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、１割のままの方が２万５,３３４名から、１０月で２万５,８２７名。この数の違いというのは何なんでしょうか。平成１８年度というのは、今回新たに８月に通知を出したという意味ですよね。平成１７年度の数も言っていただくと、よりわかるのかなと思うんですけれども。","respondent":"冨岡高齢事業課長","answer":"平成１７年度ですが、トータルが３万４,１５７名でございまして、内訳となりますと、２割の方が５,０５１名、１割の方が２万９,１０６名です。申しわけございません、この内訳については出しておりません。","voiceIndex":109,"id":"exchange-043"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この件に関しては、申請をしていただきたいということで、申請書を送られたということなので、既に申請を出されている方がどれぐらいあるかというのはわかっていると思うんですけれども、そこら辺の申請者の人数も教えていただきたい。特に高齢者ですから、こういう文章を読み解くというのはほんとうに至難の技だと思うんですよ。わかったら、教えてください。","respondent":"冨岡高齢事業課長","answer":"申請いただいた方で、結果的に１割負担になった方がありますけれども、８４８件ございました。","voiceIndex":113,"id":"exchange-044"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"８４８名がもう申請をして、手続をとられたということですが、これはこれで終わりなのか。それとも、まだもしかしたら手続をすればもっといらっしゃるのかというあたりは、どのぐらいになるのかという数が、今ちょっとわからないのか、ほとんどなられたということなのか、どうか、そこら辺のところをちょっと教えてください。","respondent":"冨岡高齢事業課長","answer":"話がちょっと戻りますけれども、申請書を送らせていただいた方は１,２７５件でございました。そのうち約８５０件ほどです。","voiceIndex":115,"id":"exchange-045"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それからもう一つお伺いしたいのは、今回、現役並みということで、窓口負担が２割から３割になるということそのものは、ほんとうに現役並みの所得のある方には、現役と同じように負担をしていただくんだということで、国会の中でもやりとりされていますけれども、私は、現役並みの所得者と、高齢者の有病率というか、病気になる確率ですとか、治りにくさというのは全く違うと思うんです。","respondent":"冨岡高齢事業課長","answer":"療養病床で、どのぐらいの方が負担をされているかですが、私ども、数字をちょっと調べてみたんですが、入院時の食事療養というトータルでは報告が出ておりますけれども、その方が療養病床に入っておいでになるのか、そうでないのかというところにつきましては。","voiceIndex":117,"id":"exchange-046"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"国民健康保険のほうでは、はっきり療養病床のほうに入院されている方が１１名ということでわかるんですよ。これだけの負担増が、どれぐらいの区民に、どういうふうに影響が出ていくのかというのは、やっぱり区として把握する必要があると思うんですよ。そういうところで、じゃあ、２万４,０００円の負担が５万２,０００円になってしまう方がどれぐらいいらっしゃるのかというのは、わからないんでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"今、ちょっと新しい資料が手元にないんですけれども、２００２年の資料になってしまうんですけれども、要するに病床の数は出ているんですけれども、大体、医療保険適用されているのが２３０台です。","voiceIndex":119,"id":"exchange-047"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"品川区内に療養病床のベッドが幾つあるかということではないんですよ。現在、療養ベッドが、２８万から１５万ベッドに、２３万ベッドを、この６年間でなくしていくという方向が出されたと思うんですが、区としては、ここら辺のところは、どういうふうに対応していくと考えてられているのか、ちょっとそこら辺のお考えをお聞かせいただけないでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"これにつきましては、区としては、今現在、介護保険適用の病院は２カ所ありますけれども、今後、その施設とよく相談しながら、今後の対応をどうするかということは検討しなくてはいけないと考えております。","voiceIndex":121,"id":"exchange-048"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう中で、一番身近な自治体として、この問題は国会の中でも、与党の中でも問題なんじゃないかという発言がたくさん出されるような状況もありましたので、こういう実態を一番つかんでいる身近な自治体から、ここのところはしっかりと意見も言って、行き場のないような介護難民と言われる方があふれるような状況にならないような意見をぜひどんどん言っていただきたいというふうに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":123,"id":"exchange-049"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この１０月から、地域生活支援事業が始まるということと、新体制への移行が始まっていくということになると思うんですけれども、新体制というのがどういうものなのかということと、新体制への移行に対しては、区としては、どういうスパンで考えられているのかということを、まずはじめにお聞かせいただけないでしょうか。","respondent":"西島障害者福祉課長","answer":"福祉サービスにおける変更だと思いますが、いわゆる現行が、居宅サービスと、いわゆる施設系のサービスとなっていますが、これが新しいサービスに移りますと、いわゆる日中活動の場と住まいの場という形になってまいります。","voiceIndex":129,"id":"exchange-050"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうすると、一斉に移っていくということですけれども、小規模作業所とか何かもそういうときに移っていくのかということを、一つお聞かせいただきたい。今までとどう変わっていくのかというあたりを、ちょっと全体のところで教えていただきたいと思います。","respondent":"西島障害者福祉課長","answer":"現在、事業につきましては、都の補助金と区の補助金で運営しているわけですが、おそらく、国、都ともに早く移行をということで、その辺の補助金の動向も、おそらく、現状のままいくとは考えられませんので、その辺も、先ほどお話ししましたように、状況を見ながら。","voiceIndex":131,"id":"exchange-051"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"予算の部分では、思っていたよりもこんなに少ないのかということで、すごく大変だというような自治体の声というのも、どこかで載っていたところがあったんですけれども、区としては、今までと比べてどんな予算になっていくかというのは、１０月から始まるということですけれども、まだわからないという状況なんでしょうか。そこら辺、何かあったら教えてください。","respondent":"西島障害者福祉課長","answer":"移動介護ですが、地域生活支援事業を検討するに当たりまして、区のほうでは、全体の自立支援法の精神を根底に置きながら、全体のバランスを考えながらやっていきたいというのが、まず基本として考えてあります。","voiceIndex":133,"id":"exchange-052"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それからもう一つ、現在のレベルは下げないということですので、そういうことはないのかもしれないんですけれども、３の日常生活用具の給付では、これからどういうものを具体的にしていくのかというのは、当事者を含めた検討グループで検討を行って決定していくということなんですけれども、この中で、現行制度で適用とされているものが外されるということはないのかということを。","respondent":"西島障害者福祉課長","answer":"検討委員ですが、肢体不自由者の会の代表の方を委員としてお願いをしていますので、その方を入れて、ご意見を聞きながら決めてまいりたいと思ってあります。日常生活用具は、時と共にいろいろな形で物が変わってまいります。","voiceIndex":135,"id":"exchange-053"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"最後にちょっとお聞きしたいのが、自己負担額のところで、移動支援のところでも、低所得者１、２および住民税均等割のみの課税者となっているんですけれども、その下の日常生活用具のところも、課税者となっているんですけれども、この支援事業に関しては、世帯ではなくて、その方ということでされるのか、どうか。そのことだけ、ちょっと確認をさせていただきたい。","respondent":"西島障害者福祉課長","answer":"基本的には自立支援法の枠組の中で実施をしてまいりますので、世帯での、住民税同一世帯ということで判定をしてまいりたいです。それから、いつごろですが、現在、もう作成にかかっておりますので、中旬ぐらいまでには出来上がるのではないかと考えているところです。","voiceIndex":137,"id":"exchange-054"},{"speaker":"西本委員","kind":"確認","question":"一つだけ確認をさせてください。コミュニケーション支援事業の中で、手話通訳派遣事業ということですが、これはどういう団体をお使いになろうとしているか。品川区内の中でもいろいろな団体があると思うんですが、そういうところをお使いなるのか。それとも新たに、区として何かそういう養成みたいなことをしていくという形で啓蒙していくのか。その辺の考え方を教えてください。","respondent":"西島障害者福祉課長","answer":"心身障害者福祉会館では、手話サークル、登録手話通訳の会、それから聴覚障害者協会と連携いたしまして、毎年、定期的に手話通訳の養成講座を実施しています。","voiceIndex":139,"id":"exchange-055"},{"speaker":"西本委員","kind":"質問","question":"いろいろ経費等々がかかると思うんですが、補助金とか、そういうお金の関係ですね。区として進めていく以上は、一応ボランティアという観点よりも、それなりの事業費みたいな考え方が必要かと思うんですが、その辺はいかがですか。","respondent":"西島障害者福祉課長","answer":"手話サークルの会をお使いになるときは、これはボランティアですから、おそらく実費相当だろうと思いますが、区がいわゆる手話通訳派遣事業として実施をしている場合は、当然有償でございまして、１回４,４００円。","voiceIndex":141,"id":"exchange-056"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"例えば、先ほど来、ガイドヘルプサービスの軽減策がありましたけれども、ここのところ、いかにこの自立支援法が障害者に過酷な負担を与えるのかということで、全国でもいろいろな軽減策が出て、新聞に載っているので、品川区もぜひ検討して、特にガイドヘルプサービスのところは、手話通訳同然、本当に目のかわりとか、自立支援法というんだから。","respondent":"西島障害者福祉課長","answer":"全体の制度のバランスを見据えながら、一時的な軽減策を実施するよりは、きちっと計画をして、利用者にとって使いやすいものにしていくというのが基本ですので、これからもそのように考えていきたいと考えています。","voiceIndex":143,"id":"exchange-057"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"ストマの入札のところで、単価が下げられるという、そういう細かいところでの配慮は当然していただきたいんですが、総額がどうなるのかわからないと。その辺のおおよそのところのつかみはどうなのかということを、ぜひお聞きしたいんですけれども、いかがでしょうか。","respondent":"西島障害者福祉課長","answer":"したがいまして、申しわけございませんけれども、もう少し状況を見させていただいて、あまり過大に見積もってもいけませんけれども、過少に見積もって足りないということでも困りますので、その辺についてはもう少しお時間をいただいて、今年度の歳入。","voiceIndex":145,"id":"exchange-058"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"でも、品川区の今の予算を見ていると、決して赤字の団体ではないというところでは、障害者自立支援法という名前がついているからには、やはり自立ができる方向に、品川区が頑張ってほしいと思います。サービスは下げないと、先ほどから、力強くたびたび伺っていますが、サービス水準はもちろん下げない、ほんとうに上げていただきたい。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":147,"id":"exchange-059"},{"speaker":"三上委員","kind":"質問","question":"それは何かというと、それ以前に、私ども公明党が、障害児の利用者負担の軽減とか、施設の安定的な事業運営の配慮とか、いろいろな形で、今、いろいろな団体の方から伺ったご意見等を受けて、今、緊急に申し入れをした。負担等についても軽減をしていくべきであろうと、こういうようなことから、そういったことについての概算的に追加措置ということでの説明を、２５日に受けた。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":148,"id":"exchange-060"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3154#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":55979,"voices":157}},{"id":"h18-20060828-8","meetingId":"h18-cm08","date":"2006年8月28日","dateIso":"2006-08-28","committee":"建設委員会","time":"午後１時０３分～午後３時４８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"井上委員","kind":"確認","question":"大変難しいので、わかるところでちょっと具体的なこととかになってしまうかもしれないんですけれども、１２０ページの建築確認事務の流れで、書類審査と意匠、構造設備というところで検査をした後、その隣に消防審査というのがありまして、ここのところで、今まで建設委員会で請願などを聞いていた中で、消火作業が住民の方にとっては今までの事例で救急車も入れない。","respondent":"片田建築課長","answer":"特に消防審査については、建築計画でどうしても現況の計画、建築確認というのは、一つの敷地に対して、一つの建築物という原則の上で成り立っていますので、一つの敷地の中に建つそれぞれのいろんな用途がありますけれども、その建物が備えるべき性能、それを消防のほうで言えば。","voiceIndex":6,"id":"exchange-001"},{"speaker":"井上委員","kind":"確認","question":"今、本当におっしゃったように、一つの建物として問題がなければということで、建物に確認がおりたり、消防の中でも、その一つの建物については問題がないと。","respondent":"片田建築課長","answer":"用途にあった形の形態を考えていただく、あるいは機能も対応するといった内容ですので、その辺は都市計画と建築基準法という単体の規制の中の一応分け方をしているです。","voiceIndex":8,"id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"都市計画が重要であるということをもっともっと住んでいる方たちが理解をして、そのことに意見が言えるような知識と学習も含めて必要だと思うんですけど、別な視点で１１９ページのほうの３番の特例許可等に関する事務というところで、先ほど一定の要件と公益に合えば認可するという、許可をするということでしたけれども、この点について条例がマンションに対して駐車場の付置義務なんかがある中で。","respondent":"片田建築課長","answer":"したがって、冒頭申し上げましたように、技術的な基準に合致すれば確認にはなりますから、民間でもできるというところが民間開放の根拠になっているということで認識しております。","voiceIndex":10,"id":"exchange-003"},{"speaker":"本多委員","kind":"質問・要望","question":"中間検査のところでちょっとお聞きしたいんですけれども、工事に着手する前の審査はどれでも書類審査で当然必要だと思うんですけれども、着工してからの中間検査まで構造審査と設備審査が一番重要になってくると思うんですけれども、中間検査を受けるに当たって、平成１０年の改正で構造と設備の中間検査のやり方が変わった点があれば教えていただきたいと思いますし。","respondent":"片田建築課長","answer":"ただ、主な理由としては、そういう構造もそうですけれども、むしろ建物を大きくしているとか、あるいは斜線制限に木造３階建てで、建ぺい率等の制限がありますけれども、むしろ形態的なところを重視して検査を進めていくというふうな考え方になってきています。","voiceIndex":12,"id":"exchange-004"},{"speaker":"本多委員","kind":"質問・要望","question":"完了時点での全部の書類へのチェックというのは当然そういうことで進めていただきたいと思いますけれども、例えば、今コンクリートを打つ場合に、コンクリートの精度ですとか品質をはかる検査とかが義務づけられたりしておりますけれども、それとあわせて、そういう構造のことですとか、写真ということになっておりますけども、その辺の今後改善をしていかなければいけないとか。","respondent":"片田建築課長","answer":"当然建築工事をやる場合には、資格を持った、これまでもそうですけれども、規模によって当然１級建築士がやらなければいけないという建物が大方ですけれども、あるいは工事の管理士というようなことで、そういう資格を持った方が当初建築確認を受けた図面に基づいて。","voiceIndex":14,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"明らかに自然災害などの天災ではなく、あの事故、事件は人災であったと。決して安全よりも利益や効率を決して優先しちゃいけないんだということがやっぱり問われているんじゃないかと思うんですけど、そこをまず１点伺いたいのと、もう一つ、先ほどイーホームズの認可が取り消されたというお話がありましたけれども、過去に品川区内において、どれぐらいの数が確認業務として何件ぐらいあるのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-006"},{"speaker":"中塚委員","kind":"確認","question":"今の課長のお話ですと、一つは倫理上の問題、二つに職能の問題、それぞれ事件のかぎを握っている人たちのことを聞きますと、ただ、問題はそこだけで済まされないものがあるんじゃないかということを伺いたいんですね。住民の毎日の暮らしにかかわるこれらの事件を決して起こしてはならない。確認審査、つまり法律で裁判所的な存在ですよね。これに対する区の認識をもう一度教えていただけますか。","respondent":"片田建築課長","answer":"それと、いろいろやはり問題があった後の対応というようなことも含めて、瑕疵担保の補償ということでの保険制度、財産の関係になるかと思いますけれども、そういう考え方がなされている。","voiceIndex":19,"id":"exchange-007"},{"speaker":"宮崎委員","kind":"質問","question":"今の中塚委員の質問に関連して、イーホームズの手がけた建築、それが１,０００件を超えるというのが品川区のほうに送られてきたということなんですけど、それはそれで今度品川区で全部見直すわけですよね。これがどのぐらい進んでいるのかというと、問題があったのかないのか、その辺のことはどんな状況だったのか、わかったら教えてください。","respondent":"片田建築課長","answer":"ただ、工事中のものとか、それについては必要な指導を工事のタイミングとその中で確認をしながら対応していくということになろうかなということで考えております。","voiceIndex":21,"id":"exchange-008"},{"speaker":"宮崎委員","kind":"確認","question":"いろいろ住宅をつくるときは資金繰りも大変な中でやるんだろうと思うんですけれども、例えば作っている最中の建物がどうもあなたも問題がありましたよなんていう場合に、また費用をかけて壊さなきゃいけないということが出てくる場合もあるんじゃないかなという心配をするんですけど、そういうときは、だれが責任をとるんだということになってくるんですけど。","respondent":"片田建築課長","answer":"イーホームズの対応に当たっても、一応私も直接行ってまいりましたけれども、国土交通省のほうにそういうふうな要望をしております。ただ、残念ながら６月の今回の法律改正の中には、そこの責任の明確化というものが何も記載されていなかったというところがあります。","voiceIndex":23,"id":"exchange-009"},{"speaker":"宮崎委員","kind":"確認","question":"実際、計算ソフトをいじくっていたらわからなかったんだということなんですけども、実際上建築確認のほうでは、構造のほうの審査でも、構造計算などにより審査、指導を行うというふうになっているんですけども、現実は建前上、そういう計算式を変えられたら全くアウトになっちゃうということなのか、本来はやっぱり区は区で、審査する側は審査する側で自分たちの計算でやっていくということになるのか。","respondent":"片田建築課長","answer":"若干、やはり今国のほうの法律の中でも、そういうプログラムをもう一度再検証するようなことも含めて、新たなチェック機関を設けてというような議論もされているところがありますので、その辺は次回に改めて法改正の概要を含めてご説明します。","voiceIndex":25,"id":"exchange-010"},{"speaker":"松澤委員","kind":"確認","question":"話の中で、建築確認というものは民間、行政を問わず、すべての建物は確認を受けて建物を建てるんですけれども、この中間・完了検査が建築主の申請に基づいてということで話の中では２０％から３０％しか受けていなかったと。それが近年５０％ぐらいになりましたよという話ですけれども、びっくりするんだよね、その数字を聞くとね。その点について、どのように理解しているのか、ちょっとお聞きしたい。","respondent":"片田建築課長","answer":"これは東京都のほうで各自治体の検査率、こういうのをまとめてございまして、今東京都全般的にそういう検査率を上げていきたいという思いの中で、１点目標をつくりましょうということで。","voiceIndex":28,"id":"exchange-011"},{"speaker":"松澤委員","kind":"意見","question":"コメントを聞いたんですけど、わかったようなわからないような、難しそうな答えでした。一般はどうかというと、今課長は、自分の建物は自分で建ててと言うけど、そうじゃないよね。それを調査するとかしないとかの問題じゃなくて、やはり完了検査を受けるというのは大事なことで、やっぱりこれは何かキャンペーンするとか何か本当は義務づけるべきだと思うんだけれども、その辺の行政の考え方はどうなのか。","respondent":"片田建築課長","answer":"そこまでさかのぼって入居された方の使用ができないと、行政処分ができるのかとか、そういう話になるわけですけれども、やはり複数の建物、分譲マンションとかを一番適正な形で、特に購入者についてはそういうことを認識した中で完了検査を受けるかどうか。","voiceIndex":30,"id":"exchange-012"},{"speaker":"松澤委員","kind":"質問","question":"今お話を伺いましたけれども、そうすると、これは増改築の場合にも申請をしますよね。今話したのは、おそらく新築のものについての話で、私もそういう質問をしたと思いますけど、増改築については、これは完了検査なんていうのはあるんですか、そのパーセンテージみたいなのは。","respondent":"片田建築課長","answer":"ただ、今回細かい数字の中で、その内訳については恐縮ですけれども、持ってございませんので、ご了承いただければと思っていますけれども、ただ、増築については、なかなか受ける率というのは多いかどうかということなっていくと。","voiceIndex":32,"id":"exchange-013"},{"speaker":"藤田委員","kind":"確認","question":"新聞等のニュースで恐縮なんですけれども、今回改正案では中間検査というのが出てくるわけなんですが、東横インホテルといいまして、業者が完了審査で引っかからなかったという、東横インの社長はその意識がなかったような話をしていますけれども、これはやっぱり中間検査、どこが中間検査なのかよくわかりませんけれども、その辺をしっかりやることが問題ではないかなということで。","respondent":"片田建築課長","answer":"したがいまして、中間検査というのは、先ほど申し上げましたように、建物の３階が建ち上がった時点、もしくは２階の床とかそういうものの工事が進んでいる時点という条件ですから、完了検査にとってはなかなかでき上がった後のものまでは把握できないと。","voiceIndex":34,"id":"exchange-014"},{"speaker":"井上委員","kind":"質問","question":"すみません、ちょっと今おっしゃっている意味がよくわからないんですが、出されたものがどういうものかというのは、正副委員長と議論した中でわかるのかもしれないですが、どういうものが出されるかということがわからないのに質問項目を用意するということなのか、その辺が今日の説明をされたことに対して質問するわけですが、どういう意味をおっしゃっているのかよくわからないんですけど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-015"},{"speaker":"井上委員","kind":"確認","question":"所管事務調査のスケジュールみたいな、今回が建築確認事務についてということで、次回もそうですというお話がありました。じゃあその後、所管事務調査をいろいろ出されたわけですが、それが出た段階で、資料が出るのは２日前ですよね、ですから、その間に質問を用意して、職員ならびに理事者側に伝えてくださいということでよろしいんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-016"},{"speaker":"井上委員","kind":"提案","question":"ちょっと具体的にそういう正副委員長が詰めた内容でどういうことが提案されるのかということが少し把握できない状況では、そうすることはもちろんしようと思っていますけれども、少しこういうことが説明をされる場によって必ずしも用意できるかどうかというのは微妙なところということで、もちろんそのことについては用意していただいたほうが早いと思いますからいいと思いますけど。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":41,"id":"exchange-017"},{"speaker":"宮崎委員","kind":"質問","question":"要するに、そういう事前に質問があれば、出してもらえればそれはそれで対応するということですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-018"},{"speaker":"宮崎委員","kind":"質問","question":"してくれるということですね。当然、ほかの方の質問を聞きながら、これが足りないとかというのは当然出てくる話ですから、それはそれでということでいいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-019"}]},{"id":"topic-02","title":"を議題に供したいと思います。 まず、大崎駅西口中地区再開発事業の現況","agenda":"を議題に供したいと思います。 まず、大崎駅西口中地区再開発事業の現況","exchanges":[{"speaker":"井上委員","kind":"意見","question":"今のご説明は大崎駅西口中地区の組合設立後行われたということと、地域活動拠点として無償譲渡したいという申し出があるというこれとはどういうふうに、第二地域センターの問題ではないのか、その辺がよく、今日の説明、よくわからないんですが。","respondent":"青木都市開発課長","answer":"それともう一点、あわせて説明することがよろしいかどうか、確かにご指摘の部分ではあるんですけれども、このたび、より計画が具体化していく中で、地域貢献施設として予定していたものについては、区に無償譲渡したいという申し入れが６月末か７月でしたか。","voiceIndex":52,"id":"exchange-020"},{"speaker":"井上委員","kind":"確認","question":"じゃあ、庁内でまとまりましたということは、こういうところで報告といった段階で私たちはどういうふうにそれを判断していいのかというのがいつもわかりにくいところなんですけれども、まとまりましたということは、決定をしましたというふうに認識をするのか、それはただ報告をした段階でその先はまだ決まっていないということなのか、そこのところを確認させてください。","respondent":"青木都市開発課長、岩田まちづくり事業部次長","answer":"現在、一方では、施設建築物、再開発建物の着工に向けまして確認申請も行う中で、再開発建物の建築内容を固めていかなければならないという時期に来ておりますので。建設委員会におきましては、この再開発の事業内容のうち、非常に重要な地域貢献施設、計画の柱になっている施設ですので、これの内容がほぼこういう形で決まったということをあわせて建設委員会にご説明をしたと、こういうことです。","voiceIndex":54,"id":"exchange-021"},{"speaker":"井上委員","kind":"質問・要望","question":"じゃあ報告のほうは区民委員会ということですが、この流れでいくと、どういうふうなスケジュール、時期的なものなんですけれども、その辺の予測と、あと大崎第二地域センターがそこに移転するということが条例変更とかになるんでしょうか、その辺の詳しい仕組みがわからないんですが、その辺で教えていただきたいと思います。","respondent":"青木都市開発課長","answer":"厳密に言うと、確認申請上の問題はあるんですけれども、建物の内装、間取り等、細かいところになりますので、これは建築確認の変更等でも対応できる部分ですので、そういった細かい間取りなどの調整につきましては。","voiceIndex":57,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"大井第二地域センターの移転ということですけれども、当然地域センターですから、窓口の業務と、そのほかに区民集会所、これはまとめて移転するというところだと思うんですけれども、それをちょっと確認させていただきたいのと、あと、現状よりも大きくなるんですかね、小さくなるんですかね。もう少し説明していただきたい。","respondent":"青木都市開発課長","answer":"この断面図のご説明が漏れましたけれども、委員のおっしゃるとおり、まず、この断面図からちょっと補足してご説明申し上げますと、約３１０m2と書いてある部分、これが先ほどご説明した歩行者デッキとほぼ同じ高さになりまして、そこから出入りできる部分で、その上。","voiceIndex":59,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"従前の施設と同じになるよう最大限努力されるというようなお話ですけれども、今大崎第二地域センターを利用されている団体がありますよね。今後どういうテンポで利用者団体に説明していくのか、ここに書いてある近隣説明会の中でそれを入れちゃう考えなのか、それとも団体の状況によって今後移転先の活用を考えているのか、その考え方を教えてください。","respondent":"青木都市開発課長","answer":"現在のところ、まだ地域センター、行政サイドのほうであるべき間取りと使い方等を検討している状況でございまして、近隣の方々に対しましては、ご説明でも申し上げましたとおり、８月１６日に標識設置と同じ日に町会長会議におきまして、町会長の方々にご報告した段階です。","voiceIndex":61,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"わかりました。移転されるところは区の一任で使い勝手を含めてやるものだから、改めて利用者やほかの利用している方々に区が説明すると、そういう考えでよろしいですか。","respondent":"青木都市開発課長","answer":"はい、おっしゃるとおりでよろしいと思います。","voiceIndex":63,"id":"exchange-025"},{"speaker":"宮崎委員","kind":"意見","question":"地域活動拠点を再開発組合から無償譲渡されるということなんですけれども、区は組合とはどういうふうになるのかなと思っているんですけど。組合との関係でしばりがかかっている、そういうことは何かあるのかなと思うんですけど、どういう関係になるんでしょう。","respondent":"青木都市開発課長","answer":"細かい運用等の規定と約束事につきましては、また今後詳細を詰めなければならないんですけれども、無償譲渡を受けることによりまして、全体の建物の中の一部を区が区分所有する形になりますので。","voiceIndex":65,"id":"exchange-026"},{"speaker":"宮崎委員","kind":"質問","question":"それとあと、全体のいわゆる管理費の負担だとか、そういうところも出てくるのかなというふうに思うんですけれども、そこら辺のところはどうなんでしょうか。","respondent":"青木都市開発課長","answer":"管理費等につきましても、今まだ具体には詰めておりませんけれども、例えばご説明したとおり、できる限り機能を分離することで、共用部分を少なくすれば、例えば管理費の負担を一定程度低減できるとか、そういったような交渉事になると思うんですけれども。","voiceIndex":67,"id":"exchange-027"},{"speaker":"宮崎委員","kind":"意見","question":"今説明を聞いただけでもちょっと気になるというか、無償なのでいいかななんていうふうにならないところがちょっとあるので、私も区の判断でいろいろ、例えばいろいろ人口変動になっているその中で、出張所の配置だとか地域センターの配置だとか、そういうことも変更になってくるときは、ここはそういう約束だとずっとしばられるというか、そういうことにもなるんだろうと思うんですけど。","respondent":"青木都市開発課長","answer":"今の委員のご指摘の件ですけれども、今回老朽化している大崎第二地域センターが近くにあったことと、たまたま今回無償譲渡というご提案があったのでそれを大崎第二地域センターの更新に活用できるだろうという判断で移転するものでございまして。","voiceIndex":69,"id":"exchange-028"},{"speaker":"宮崎委員","kind":"意見","question":"じゃあわかりました。ちょっとついでに聞いておきたいんですけど、そうすると、例えばこういうふうにするということになると、今のところはどういうふうに考えているのか、考えがあればお聞かせいただければなと思います。改めて中地区のところの総事業費、今時点でどのぐらいになるか、あと、補助金があるのかどうか。","respondent":"青木都市開発課長","answer":"１点目の事業費の問題ですけれども、約４６０億円を見込んです。国あるいは区からの補助金、交付金になりますけれども、現在のところ７６億円から７８億円ぐらいのいわゆる公的なお金が補助されるということで予定しています。","voiceIndex":71,"id":"exchange-029"},{"speaker":"宮崎委員","kind":"質問・要望","question":"それと権利者が８３名で、共同住宅１,０８０戸、単純に言って、この戸数が住宅の事情では、一方では供給過剰じゃないか、そういう指摘もあったり、一方ではつくるところから買手がついていると、そういう状況もあるんですけど、報道なんかもあるんですけど、ここのところで改めて区のほうの見通しというか、あるいは組合のほうの見通しというか、そこのところを教えていただきたい。","respondent":"青木都市開発課長","answer":"住宅の見込みですけれども、こちらにつきましては、もともと都市再生特別措置法の趣旨を踏まえた都市再生特別地区に指定してございまして、その再生特別措置法におきましては、都心部における居住環境の向上ということをうたっておりますので。","voiceIndex":73,"id":"exchange-030"},{"speaker":"本多委員","kind":"質問・要望","question":"国の役所の建物とかが民間の建物に入るような時代になっていると思うんですが、文部科学省の一部が民間のビルに入ったり、昔の従来型の明治時代からの国の役所はこうだと決まったあれではなくて、民間のそういう施設にこれからの時代はそうあるべきだと思っておりまして、この地域センターが民間のこういう建物に入るということは、まさにこういうことをどんどん進めていただきたいなとすごく思っております。","respondent":"岩田まちづくり事業部次長","answer":"そのときにも、地域の町会あるいは行政の人間が入居説明会に参加して、町会への、町会をあそこの場合はつくっていきましょうというような説明をして、その後各棟で自治会が結成に向けていろいろ動いたということがありますので、ここの場合は地元町会に加入をしてもらうですので。","voiceIndex":77,"id":"exchange-031"},{"speaker":"中塚委員","kind":"質問","question":"説明の中で、共同住宅の話がありましたけれども、住宅の需要が高いということですけれども、どこの層を望んでいるのかというか、見込んでいるのか、ファミリー層を想定しているのか、ちょっと教えていただけますか。","respondent":"青木都市開発課長","answer":"具体の戸数内訳等については、現在手元に資料を持ち合わせてございませんけれども、いわゆる１ＬＤＫからファミリータイプ、４ＬＤＫまで、多様な層の住宅を用意するということで考えているように聞いております。","voiceIndex":79,"id":"exchange-032"},{"speaker":"中塚委員","kind":"質問","question":"仮にファミリー層が来ると、当然そこに新たな学校の需要だったり、保育園の需要だったり、そういうのが自ずと想定されるわけですよね。品川ではないですけど、他区でマンションが乱立して、そういうのが間に合わない事態が起きていますけど、そういうのは何か対応策を同時に考えられているのか、考え方を教えてください。","respondent":"青木都市開発課長","answer":"保育関係の点ですけれども、説明の中で申しましたけれども、説明の資料、１枚ペラの資料の裏面の断面図をご覧いただきたいんですけれども、ご説明いたしました地域活動拠点施設、網かけしてあるところの下、言い方によりますと地下１階という言い方になってしまうんですけれども。","voiceIndex":81,"id":"exchange-033"},{"speaker":"大西副委員長","kind":"提案","question":"２点ほどあるんですけど、１点目がこのところに書いてあります地域活動拠点施設、「平成１６年、事業者からの都市計画提案において、地域貢献のための施設として提案された施設の一つである」ということなんですが、これを見ると、提案された施設の一つであるということですが、ということは、もっとほかに何か提案を受けていて、その中で区がこういう選択をしたということなのかどうなのかということが１点。","respondent":"青木都市開発課長","answer":"１点目のその他の施設と何があったのか、それをどう選んだのかというご意見ですけれども、先ほどご説明申し上げました子育て支援等に関する施設も、地域に貢献する施設という中の一部に入ってあります。","voiceIndex":83,"id":"exchange-034"}]},{"id":"topic-03","title":"の区民住宅（あき家）入居予定者登録募集","agenda":"の区民住宅（あき家）入居予定者登録募集","exchanges":[{"speaker":"松澤委員","kind":"質問","question":"あき家入居予定者登録募集ということですけれども、今お話を伺いますと、みんな入っていますと。そうすると、募集しておいて、あきましたら１番から何番まで入れますよ。これは確率、平均で結構ですけど、今回募集されますファミーユ下神明、西五反田西館・東館、これは大体どれぐらいあくだろうという予想みたいなものはあるんですか。","respondent":"齋藤住宅課長","answer":"今年は６件、去年が５件あきました。ですから、５人の方が入りました。ファミーユ西五反田西館が平成１６年の６月にできまして、去年は８件、東館は１６年の１月にできまして、２件あきました。ですから、５番目ぐらいに入っていないとなかなか入れないです。","voiceIndex":90,"id":"exchange-035"},{"speaker":"松澤委員","kind":"質問","question":"これは住みかえ可能な住宅ということでつくられたということなんですが、この出ていった、あいた方の事情なんですけど、住みかえ可能なところに移動したのか、それとも何か事情があって移転したのか、その辺のところまではわからないですか。","respondent":"齋藤住宅課長","answer":"基本的には転勤ですとか、マンションを買われて出ていかれる方など、一応報告はいただいておりますけれども、詳細は不明です。","voiceIndex":92,"id":"exchange-036"},{"speaker":"中塚委員","kind":"質問","question":"今の質問の中で、要はあき家になった理由が、転勤、またはマンション購入とありましたけど、件数としてもし押さえているのであれば、それぞれ教えていただけますか。一番多いのかどうなのか。","respondent":"齋藤住宅課長","answer":"そこの欄にどういう理由で転居されるかということを書いていただいております。個別具体的に言いますと、さまざまご家庭の事情がありまして、事業に失敗されたとか、離婚されたというような事情もありまして、詳細はとらないということです。","voiceIndex":94,"id":"exchange-037"},{"speaker":"宮崎委員","kind":"質問","question":"今回は宅建管理センターの管理のところだと思うんですけど、ほかのところの区民住宅の募集の予定というのはどうなっているんですか。","respondent":"齋藤住宅課長","answer":"ほかは７月に終わっております。７月と今回の違いは、家賃の方式が傾斜家賃かフラット家賃か、委託先が宅建管理センターか三井不動産住宅リースか、こういうことで分けてございまして、年間２回に分けてあります。","voiceIndex":96,"id":"exchange-038"},{"speaker":"中塚委員","kind":"質問・要望","question":"土砂崩れの原因ですか、もしわかったら教えていただきたいんですけど。そのためにも、崖崩れの原因の調査、今どういう状況なのか、今後の崖崩れ、危険箇所の総点検などはどのようにあるのか、それだけ教えていただきたい。","respondent":"藤田道路公園課長、片田建築課長","answer":"土の中に２段目の段のところに排水のパイプを入れて、土砂が水をあまり含まないような形の対策も今現在行っているところです。今道路公園課長のほうから原因の説明を行ったところなんですけれども、区内については特に一定規模以上ということで高さが５ｍ以上で、なおかつ傾斜度が３０度以上、がけの上下に５戸以上の人家があるものというところについては。","voiceIndex":102,"id":"exchange-039"},{"speaker":"中塚委員","kind":"質問・要望","question":"今の話では、今日の話が１件特別で、あとの地域もあって、品川の地形を見ても、川があったり、高いところがあったり、坂が多い地域もあるし、相談の窓口もあるということですけれども、ＰＲの内容、対策をしっかりとっていただきたいと思いますので、どうぞよろしくお願いします。要望で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-040"},{"speaker":"井上委員","kind":"意見","question":"そういう視点でもし取り組みがわかるんであれば、お願いしたいと思います。","respondent":"福田まちづくり事業部長","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":116,"id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3858#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":44209,"voices":118}},{"id":"h18-20060828-9","meetingId":"h18-cm08","date":"2006年8月28日","dateIso":"2006-08-28","committee":"文教委員会","time":"午後１時０４分～午後３時４８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を8件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の校舎改築事業","agenda":"の校舎改築事業","exchanges":[{"speaker":"林（宏）委員","kind":"確認","question":"ちょっと確認だけさせてください。現地で説明を受けて聞くのはあれなんですけれども、改めてもしあれなら、何かのときその他でも聞け……。現地だとやっぱりそう長時間にはわたれないと思うので、そういうことも考えておいていいですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-001"}]},{"id":"topic-02","title":"の大井地区小中一貫校の愛称","agenda":"の大井地区小中一貫校の愛称","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"１つだけ。愛称の定義はどういう。それぞれ小学校、中学校というのは歴然としてあるので、幼稚園、保育園もこういう名前のつけ方をしているんだけれども、愛称というのはどういうふうに受けとめておけばいいんですか。","respondent":"市川庶務課長","answer":"近い将来、学校教育法の改正がございまして、小中一貫校が制度化された折には、その時点では、当然のことながら、もしその制度に乗っかった学校にするとなれば、条例の制定を通して名称を決めるわけでございまして、またその折には改めて名称の検討をする、こういった趣旨です。","voiceIndex":12,"id":"exchange-002"},{"speaker":"林（宏）委員","kind":"意見","question":"というと、ゆくゆく小中一貫義務教育法と呼ぶようになりましたね、義務教育法が正式になったときは、これが正式な学校名になるということなのか、あるいは今の説明だと、改めてそのときは正式名称は考えるということになると、愛称じゃなくて仮称じゃないの。","respondent":"市川庶務課長","answer":"ちょっと表現の仕方が不適切だったかもしれないんですが、私どもはこれがそのまま通用する名称ということで考えていただきたいという気持ちは当然あります。","voiceIndex":14,"id":"exchange-003"}]},{"id":"topic-03","title":"のプールの安全対策","agenda":"のプールの安全対策","exchanges":[{"speaker":"林（宏）委員","kind":"確認","question":"１つだけ。確認したいのは、子どもたちが移動教室とか修学旅行とか、そういういわゆる学校行事、一般家庭でどこかの行楽地へ行ってプールへ入るというのは、それはそこまであずかり知らないだろうけれども、学校の行事としてプールを使用する、区内ではなくて移動教室で行ったり、林間学園で行ったりとか、そういうところについては学校現場と連絡はとったんですか。","respondent":"河野指導課長","answer":"学校行事等で学校外の、いわゆる民間も含めて他の施設のプールを利用するという予定については、私どものほうで今までの中では全くございませんので、その心配は要らないと思います。","voiceIndex":21,"id":"exchange-004"},{"speaker":"沢田委員","kind":"質問・要望","question":"最後に言われたところ、平成１１年に指示されていながら、２番目の項目が事実上放置されてきたということですけれども、私なんかも確かにボルトで格子状のものをやって、その中に排水管の前にもう１つやれ、そこまでやる必要があるのかなというふうに思うから、ある程度、その時点では絶対条件ではないととらえたのかもしれないんだけれども、ただ、今、事故が起きてみると。","respondent":"市川庶務課長","answer":"それと、今回、影響を受けている学校ですけれども、基本的にはお話ししました３８校につきましては、具体的には、この資料の裏面にお示ししています小学校、中学校ですけれども、ここの学校が期間の多い少ないの違いはあっても、当初予定してきた水泳指導ができなかったです。","voiceIndex":26,"id":"exchange-005"},{"speaker":"沢田委員","kind":"質問","question":"３８校全部だめ、できなかったということなんですか。さっきの説明だと、何か４つの業者に頼んで４分の１の学校はオーケーだと言ったのは、その吸い込み口のではなくて、その前の格子のことなんですか。それとの関係をちょっと。","respondent":"市川庶務課長","answer":"２週ずれ込むと、２学期に予定していた水泳指導はできない。こういう事態で、それぞれ当該の学校については、残念なお知らせですけれども、それをあらかじめお知らせして計画の変更をしていただく、こういうことで対応しています。","voiceIndex":28,"id":"exchange-006"}]},{"id":"topic-04","title":"の平成１９年度学校希望選択","agenda":"の平成１９年度学校希望選択","exchanges":[{"speaker":"林（宏）委員","kind":"意見","question":"１つお願いだけ。説明の中でも言葉にあったんだけれども、わかりにくい部分があるじゃない。特に第１順位のところに住んでいる人は、もう優先順位だからいいんだけれども、２位、３位になると、エリアが離れてくるじゃない。僕も実際に学区域がどこなのかなというのがわからない人もいらっしゃったから、その辺をちょっと考慮してくれればありがたいなと思うので、お願いだけしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":35,"id":"exchange-007"},{"speaker":"築舘委員","kind":"質問","question":"新入生の受入枠ということなんですけれども、例えば、城南とか、城南第二は、大分近くのマンションが増えてきて人数が増えるのではないかという、話にちょっと聞いたりするんですけれども、その２クラスまでとするというのは、今まで２クラスだからそれの継続性ということだとは思うんですが、この辺の基準というか、もし増えてしまった場合は、それはもう２クラスですよと固定化して考えるというか。","respondent":"古里学務課長","answer":"ただ、これからの課題を考えた場合に、学区域内の児童生徒であれば２クラスで何とかおさまる、それを学区域外からわざわざ入れて、今年窮屈な思いで３クラスにするのか、築舘委員もおっしゃったように、現在もうマンションが建築中ですから、将来に備えて。","voiceIndex":36,"id":"exchange-008"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4580#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2006-01-01&TermEnd=2006-12-31"}],"sourceMeta":{"pages":0,"characters":16393,"voices":54}}]);
